  ui_story_5051_50510101_X44_dialog_content = "君を？それは構わないけど、急にどうしたの？",
  ui_story_5051_50510101_X45_dialog_content = "うーん…最近は治療のおかげで、\n病気がだいぶ良くなったの。",
  ui_story_5051_50510101_43_dialog_content = "ええ…最近は治療のおかげで、\n病気がだいぶ良くなったの。",
  ui_story_5051_50510101_44_dialog_content = "それで、思い出したの…",
  ui_story_5051_50510101_45_dialog_content = "何を？",
  ui_story_5051_50510101_46_dialog_content = "私が<color=#FFB400>カレンの姉</color>だということ…",
  ui_story_5051_50510101_47_dialog_content = "カレンの！？",
