  ui_story_5051_50510101_59_dialog_content = "病気が良くなってきて、色々思い出してきたなら、\nそれに越したことはないよ。良かったね！",
  ui_story_5051_50510101_60_dialog_content = "もうすぐ白夜城で「ソルラド家記念日」のパーティーが開かれるって聞いたわ。",
  ui_story_5051_50510101_61_dialog_content = "特別な、とても大切な日だった気がするの…",
  ui_story_5051_50510101_62_dialog_content = "私の妹…カレンも参加するのでしょう？",
  ui_story_5051_50510101_X62_dialog_content = "だから、この目で確かめたいの。\n記憶の中のぬくもりが、本物かどうか…",
  ui_story_5051_50510101_X63_dialog_content = "ただ遠くから、一目見るだけでもいいから…",
  ui_story_5051_50510101_63_dialog_content = "だから、私は会って確かめたいの。\n記憶の中のぬくもりが、本物かどうか…",
  ui_story_5051_50510101_64_dialog_content = "いいえ、確認なんて出来なくても、\n遠くから楽しくしているところを見られればそれでいい…",
  ui_story_5051_50510101_65_dialog_content = "PlayerNameはカレンとお友達だし、白夜城では顔が利くでしょう？",
  ui_story_5051_50510101_X65_dialog_content = "だから、あなたにお願いできないかと思って…",
  ui_story_5051_50510101_X66_dialog_content = "そういことだったんだね。…あ！でも、時間がない！",
  ui_story_5051_50510101_X67_dialog_content = "ミヤ、パーティーに着て行けるようなドレスは持ってる？\nそれから、贈り物も用意しないと…",
  ui_story_5051_50510101_66_dialog_content = "なんとか手伝ってもらえないかしら…？",
  ui_story_5051_50510101_67_dialog_content = "招待はされてるけど、友だち連れで参加できるかどうかは分からないんだ。",
  ui_story_5051_50510101_68_dialog_content = "うーん、そうだなぁ…今日じゃなきゃダメ？",
  ui_story_5051_50510101_69_dialog_content = "（北境からの使いが一向に姿を見せないうえに、\nミヤに頼みごとをされちゃった…）",
  ui_story_5051_50510101_70_dialog_content = "（断りもなくミヤを連れて行って大丈夫かな？）",
  ui_story_5051_50510101_71_dialog_content = "（大切なパーティーで、いきなりミヤを連れて行って家族と会わせるなんて…）",
  ui_story_5051_50510101_72_dialog_content = "（それに万が一バーバ・ヤーガが騒ぎ出したら大変だ！）",
  ui_story_5051_50510101_73_dialog_content = "もしかして、困らせちゃったかしら？",
