  ui_story_5051_50510101_77_dialog_content = "いや、いいよ！ミヤ、一緒にパーティーに行こう！",
  ui_story_5051_50510101_78_dialog_content = "え？でも…迷惑じゃないの？",
  ui_story_5051_50510101_79_dialog_content = "「ミヤ」が自分から色々話してくれたのは初めてでしょ？",
  ui_story_5051_50510101_80_dialog_content = "今までは何か困ったことがあると、\nすぐバーバ・ヤーガに入れ替わってたのに…",
  ui_story_5051_50510101_81_dialog_content = "君がそこまで言うんだ。\nむげに断るなんてできないよ。",
  ui_story_5051_50510101_82_dialog_content = "それに、気負わなくていいよ。\nカレン以外にも、白夜城には仲のいい友だちがたくさんいるんだ。",
  ui_story_5051_50510101_83_dialog_content = "カレンと話すチャンスがなくても、\n今日は遊びに行っただけとでも思えばいいから。",
  ui_story_5051_50510101_84_dialog_content = "チャンスはこの先いくらでもあるよ！",
  ui_story_5051_50510101_85_dialog_content = "PlayerName…ありがとう！",
  ui_story_5051_50510101_86_dialog_content = "（不確かなことも多いけど…）",
  ui_story_5051_50510101_87_dialog_content = "（ミヤがカレンを気にしてるのは本当だ。\n少なくとも2人を会わせてあげるぐらいは手伝ってあげよう。）",
  ui_story_5051_50510101_88_dialog_content = "（でも、どうして会いたいのはカレンだけなんだろう？\nお父さんの方には会いたいって言ってない…）",
  ui_story_5051_50510101_89_dialog_content = "<size=45>ごめんなさい、遅れました！</size>",
  ui_story_5051_50510101_90_dialog_content = "えっ！？",
  ui_story_5051_50510101_91_dialog_content = "だ、誰？",
  ui_story_5051_50510101_92_dialog_content = "はぁ～、影ノ街って本当に面白いものがたくさんあるんですね！",
  ui_story_5051_50510101_93_dialog_content = "いえ、北境を出てからずっと、\n見るもの触れるものすべて面白いと言った方があってますね！",
  ui_story_5051_50510101_94_dialog_content = "おかげで夢中になってつい…道に迷っちゃいました。アハハ！",
  ui_story_5051_50510101_95_dialog_content = "でも大丈夫です！だって私には、可愛い水晶玉がついてますもん！\nすぐに正しい道を見つけちゃいます！",
  ui_story_5051_50510101_96_dialog_content = "たま～に、ガケなんかに突き当たることもありますけど…",
  ui_story_5051_50510101_97_dialog_content = "旅行っていうものはハプニングがあってこそ刺激的なんですよね！\nイェリア先生がそう言ってました！",
  ui_story_5051_50510101_98_dialog_content = "で、何を話してたんですっけ？あ、そうそう、影ノ街です！",
  ui_story_5051_50510101_99_dialog_content = "影ノ街は道が複雑に入り組んでますけど、「位置」にはすごくこだわってるんですよね。",
  ui_story_5051_50510101_X99_dialog_content = "ちゃ～んと分かってる人はみんな、お店を金運抜群の場所に開くんです！",
  ui_story_5051_50510101_100_dialog_content = "あ、そうそう、「位置」にこだわるってことは、道中出会った旅人さんに聞いたんです。",
  ui_story_5051_50510101_101_dialog_content = "今度ぜひ深く掘り下げて学んでみたいものですね…\nえっ！？この飛んでるモノ、なんですか？",
  ui_story_5051_50510101_102_dialog_content = "あの…",
  ui_story_5051_50510101_103_dialog_content = "…誰？",
  ui_story_5051_50510101_104_dialog_content = "あ、すみません！自己紹介を忘れてました！",
  ui_story_5051_50510101_105_dialog_content = "<color=#FFB400>ジャキーニ</color>っていいます。\n北境の使いの者です！",
  ui_story_5051_50510101_106_dialog_content = "少し遅れちゃいましたが、主役は最後に登場するものだってよく言いますしね。",
  ui_story_5051_50510101_107_dialog_content = "<size=45>…少しって…遅れすぎでしょ！？</size>",
  ui_story_5051_50510101_X107_dialog_content = "えへ、えへへ…よく言うじゃないですか。主役は最後に登場するものだって。",
  ui_story_5051_50510101_X108_dialog_content = "オホン、皆様、こんばんは！",
  ui_story_5051_50510101_X109_dialog_content = "今夜、私たちは一堂に会し――",
  ui_story_5051_50510101_X110_dialog_content = "1年に1度の盛大なパーティーを開いています。",
  ui_story_5051_50510101_X111_dialog_content = "パーティーは美食の宝庫。",
  ui_story_5051_50510101_X112_dialog_content = "それでも食べ続ければ、いつか肉料理にも飽き――",
  ui_story_5051_50510101_X113_dialog_content = "美酒も尽きてしまうでしょう。",
  ui_story_5051_50510101_X114_dialog_content = "ならば、談笑しながら息抜きをしましょう。",
  ui_story_5051_50510101_X115_dialog_content = "余興を楽しむのも宴の醍醐味です。",
  ui_story_5051_50510101_108_dialog_content = "ご来賓の皆様。",
  ui_story_5051_50510101_109_dialog_content = "続いて、私たちキーティン聖歌隊より――",
  ui_story_5051_50510101_110_dialog_content = "歌を披露させていただきます。",
  ui_story_5051_50510101_111_dialog_content = "曲目は『白夜城に捧ぐ叙事詩』。",
  ui_story_5051_50510101_112_dialog_content = "どうぞお楽しみください！",
  ui_story_5051_50510101_113_dialog_content = "太陽が星たちと共に空へと昇る♪",
  ui_story_5051_50510101_114_dialog_content = "崇高なる王座を余光が照らさん♪",
  ui_story_5051_50510101_115_dialog_content = "己の身は盾♪",
  ui_story_5051_50510101_116_dialog_content = "己を矛とする♪",
  ui_story_5051_50510101_117_dialog_content = "貴き栄光こそ信仰の証なれ♪",
  ui_story_5051_50510101_118_dialog_content = "響鳴する輝きよ、暗闇を払いたまえ♪",
  ui_story_5051_50510101_119_dialog_content = "天にまします、永遠に輝く不落の城よ♪",
  ui_story_5051_50510101_120_dialog_content = "心に刻もう♪",
  ui_story_5051_50510101_121_dialog_content = "高らかに讃えよう♪",
  ui_story_5051_50510101_122_dialog_content = "影は過ぎ去り♪",
  ui_story_5051_50510101_123_dialog_content = "永久なる光が照らす♪",
  ui_story_5051_50510101_124_dialog_content = "白夜に捧ぐ。ありがとうございました。",
  ui_story_5051_50510101_125_dialog_content = "あら、なかなかね。いい曲じゃない。",
  ui_story_5051_50510101_X125_dialog_content = "あの子たち、本当に芸術の才能があるのね。",
  ui_story_5051_50510101_126_dialog_content = "あの子たちも、きちんとした場所ではきちんとパフォーマンスするんだね～！",
  ui_story_5051_50510101_127_dialog_content = "当たり前よ～。\nそうじゃなかったら、こんな大事な席に呼ばれたりしないわ。",
  ui_story_5051_50510101_128_dialog_content = "普段からこれぐらいいい子だと、助かるんだけどねぇ…",
  ui_story_5051_50510101_129_dialog_content = "…",
  ui_story_5051_50510101_130_dialog_content = "え？うんうん、ミカエルも同意だって！",
  ui_story_5051_50510101_131_dialog_content = "「響鳴する輝きが暗闇を払い、天にまします不落の城が永遠に輝く」",
  ui_story_5051_50510101_132_dialog_content = "――「暗潮の危機」ですか。",
  ui_story_5051_50510101_133_dialog_content = "あの悪夢のような大災厄も、ようやく一段落したと言えますね。",
  ui_story_5051_50510101_134_dialog_content = "「暗潮の危機」…パパ、ママ…",
  ui_story_5051_50510101_135_dialog_content = "ああ…ストップ！せっかくの楽しいパーティーなんだよ。\nあれこれ考えすぎちゃダメ！",
  ui_story_5051_50510101_136_dialog_content = "…",
  ui_story_5051_50510101_137_dialog_content = "ほら、ミカエルも賛成だってうなずいてる！",
  ui_story_5051_50510101_138_dialog_content = "ウリエル、申し訳ありません。私の失言です。",
  ui_story_5051_50510101_139_dialog_content = "気にしないで、慣れてるから。\nでも、こういう席はやっぱり、慣れないわ…",
  ui_story_5051_50510101_140_dialog_content = "そ、そうだね～！人がいっぱいで、ちょっと暑いかな～。",
  ui_story_5051_50510101_141_dialog_content = "ほらほら、アイスクリームでも食べに行こ！",
  ui_story_5051_50510101_142_dialog_content = "<size=30>ミカエル、ウリエルも連れてきて！</size>",
  ui_story_5051_50510101_143_dialog_content = "…",
  ui_story_5051_50510101_144_dialog_content = "あら、相変わらず元気な子たちねぇ。\nあっという間にいなくなっちゃったわ。",
  ui_story_5051_50510101_145_dialog_content = "しかし、人々の傷や痛みは、今でも鮮明に残ったままなのですね。",
  ui_story_5051_50510101_146_dialog_content = "あれを経験した者…いえ、生き残った者たちは…\n強大な四大天使でさえ、傷と痛みを乗り越えることはできないということでしょうか…",
  ui_story_5051_50510101_147_dialog_content = "あら、イルンティ。笑って笑って。",
  ui_story_5051_50510101_148_dialog_content = "今日はただでさえ余興が少ないもの。",
  ui_story_5051_50510101_149_dialog_content = "いま楽しんでおかないと、機会がないうちに終わっちゃうわよ～。",
  ui_story_5051_50510101_150_dialog_content = "もともとソルラド家の功績を記念した祝日ですからね。",
  ui_story_5051_50510101_151_dialog_content = "まさに<color=#FFB400>12年前</color>の今日、\n現城主様が一連の危機を制し、改めてソルラド家の実力を見せつけました。",
  ui_story_5051_50510101_152_dialog_content = "とはいえ暗潮の危機以降、祝典の規模は縮小される傾向ですね。",
  ui_story_5051_50510101_153_dialog_content = "以前はパレードや余興もずいぶん盛大に催されていたと思いますが…",
  ui_story_5051_50510101_154_dialog_content = "あら、そうだったかしら？よく覚えてないわ～。",
  ui_story_5051_50510101_155_dialog_content = "でも、毎年「記念日」の式典をなおざりにするべきじゃないって意見が出てくるのは確かねぇ。",
  ui_story_5051_50510101_156_dialog_content = "確か…あ、そうそう。",
  ui_story_5051_50510101_157_dialog_content = "「白夜城の若者や有能な人材が城主様に\n直接敬意と忠誠を表明する場を与えられるべきだ」とかなんとか。",
  ui_story_5051_50510101_158_dialog_content = "だからこそ今日のように簡単な宴を催し、\nそうした場を残しているということでしょう。",
  ui_story_5051_50510101_159_dialog_content = "私は簡素化の方針には賛成ですね。\n財政面や人員の労力を鑑みても、非常に妥当なお考えです。",
  ui_story_5051_50510101_160_dialog_content = "ただ、祝日が普段忙しく働く人々にとって休息の機会となることも確かです。",
  ui_story_5051_50510101_161_dialog_content = "それとうわさ話に花を咲かせる機会もね。",
  ui_story_5051_50510101_162_dialog_content = "そこは二の次です。",
  ui_story_5051_50510101_163_dialog_content = "…もう中に入っていいよね？",
  ui_story_5051_50510101_164_dialog_content = "もちろん、大丈夫に決まってます！",
  ui_story_5051_50510101_165_dialog_content = "そもそも、なんで中の歌が終わるまで、\n入口で待ってなきゃいけないんですか？",
  ui_story_5051_50510101_166_dialog_content = "会場がすごく静かだったでしょ。\nそんな所に突然入っていったら、目立っちゃうし、失礼だからね。",
  ui_story_5051_50510101_167_dialog_content = "え？そんな規則があるんですか？",
  ui_story_5051_50510101_168_dialog_content = "ええ、そうね。演奏中に音を出すのは失礼だわ…",
  ui_story_5051_50510101_169_dialog_content = "…う～ん…ミヤ。その服で「カレンの姉だ」って言われたら…",
  ui_story_5051_50510101_170_dialog_content = "たぶん、一切疑わずに100%君の言うことを信じてたよ。",
  ui_story_5051_50510101_171_dialog_content = "今の君なら、どこから見たって白夜城のお姫様だ！",
  ui_story_5051_50510101_172_dialog_content = "どこにでもある、普通のドレスよ。\nパーティーに出席するなら、それなりの格好をしなければいけないでしょう…",
  ui_story_5051_50510101_173_dialog_content = "1、2、3…その話、もう3回目ですよ！",
  ui_story_5051_50510101_174_dialog_content = "だいたい、女の子をジロジロみるものじゃありません。",
  ui_story_5051_50510101_175_dialog_content = "ぼ、僕はただ、本当にそう思ったから言ってるだけだよ。",
  ui_story_5051_50510101_176_dialog_content = "信じられませんね。\nさっきは巨像で紫の服を着た女の子をパーティーに連れて行くと約束してたでしょう？",
  ui_story_5051_50510101_177_dialog_content = "どうしてお相手が変わってるんですか？",
  ui_story_5051_50510101_178_dialog_content = "あのね…いま目の前にいる白いドレスのミヤが、\nさっき巨像で会った紫色のドレスを着た子だよ！",
  ui_story_5051_50510101_179_dialog_content = "ウソでしょう！？まったく別人に見えますよ！？\n特殊な光力術か何かですか？",
  ui_story_5051_50510101_180_dialog_content = "あの、どうして急にそんなに近づいてくるのかしら…？",
  ui_story_5051_50510101_181_dialog_content = "君も同じことしてるじゃない！？\nしかも来る途中ずっと一緒だったのに気づかないなんて！",
  ui_story_5051_50510101_182_dialog_content = "ア、アハハ…白夜城の景色に夢中だったんです。",
  ui_story_5051_50510101_183_dialog_content = "私たち、そろそろ中に入った方が…？",
  ui_story_5051_50510101_184_dialog_content = "オホン。そ、そうだったね。",
  ui_story_5051_50510101_185_dialog_content = "じゃあ、贈り物を準備して…もう一度確認するわ。\n贈り物はちゃんと持った？",
  ui_story_5051_50510101_186_dialog_content = "もちろんです！何しろ私は北境の女王陛下の使者ですから。\n唯一無二の贈り物を用意してきました！",
  ui_story_5051_50510101_187_dialog_content = "持ってきたには持ってきたけど…",
  ui_story_5051_50510101_188_dialog_content = "（タンポポのハチミツ1瓶なんてお粗末すぎるかな）",
  ui_story_5051_50510101_189_dialog_content = "（今年採れた中で一番いいものを選んできたけど、\nこんな立派な宮殿には明らかにふさわしくないよね）",
  ui_story_5051_50510101_190_dialog_content = "そのハチミツ、すごくおいしそうね。\nすぐにでも紅茶に入れてみたいわ。",
  ui_story_5051_50510101_191_dialog_content = "白夜城の貴族の間で流行るかもしれないわ。",
  ui_story_5051_50510101_192_dialog_content = "（ミヤ、僕の気持ちを察してくれたんだ！\nさりげなく慰めてくれるなんて！）",
  ui_story_5051_50510101_193_dialog_content = "ソ、ソルラドさんも気に入ってくれるといいな。\nさあ、準備もできたことだし、中に入ろう！",
  ui_story_5051_50510101_194_dialog_content = "「ソルラド家記念日」の宴にようこそいらっしゃいました。",
  ui_story_5051_50510101_195_dialog_content = "招待状を拝見いたします。\nそれから恐れ入りますが、こちらでお名前を頂戴いたします。",
  ui_story_5051_50510101_196_dialog_content = "ええっと、招待状…招待状…ありました！\nそれと…署名ですね！",
  ui_story_5051_50510101_197_dialog_content = "北境からお越しの使者の方でございましたか。",
  ui_story_5051_50510101_198_dialog_content = "恐れ入りますが、皆様に宴席をお楽しみいただくため、\nペットについてはお気を付け下さいませ。",
  ui_story_5051_50510101_199_dialog_content = "わかりました。ウィスパーはとても大人しいんです。ね？",
  ui_story_5051_50510101_200_dialog_content = "シューッ――",
  ui_story_5051_50510101_X200_dialog_content = "今夜はどうぞ存分にお楽しみください。",
  ui_story_5051_50510101_X201_dialog_content = "もちろんですよ～！ありがとうございます！",
  ui_story_5051_50510101_201_dialog_content = "招待状です。",
  ui_story_5051_50510101_202_dialog_content = "天空ノ谷のPlayerName様でいらっしゃいましたか。\nお名前はかねがねうかがっております。",
  ui_story_5051_50510101_203_dialog_content = "お忙しい中「ソルラド家記念日」の宴にご出席いただき感謝いたします。\n今夜はどうぞお楽しみください。",
  ui_story_5051_50510101_204_dialog_content = "何かご不便等ございましたら、会場内の者に遠慮なくお声がけください。\n力の及ぶ限り最上級のおもてなしをさせていただきます。",
  ui_story_5051_50510101_205_dialog_content = "ん？なんだか私よりも扱いがていねいですね…",
  ui_story_5051_50510101_206_dialog_content = "僕はこれでも世界でたった一人の空の末裔だからね！",
  ui_story_5051_50510101_207_dialog_content = "（ここまでの扱いをされるとは思ってなかったけど…！？）",
  ui_story_5051_50510101_208_dialog_content = "後ろの方はどなたでしょう？\n招待状を拝見いたします。",
  ui_story_5051_50510101_209_dialog_content = "！",
  ui_story_5051_50510101_210_dialog_content = "（ミヤは僕やジャキーニとは普通に話せるけど、\n知らない人に会うとすぐに隠れちゃうんだった）",
  ui_story_5051_50510101_211_dialog_content = "（特に宮殿に入ってからは、\nここの人たちをずっと怖がってるみたいだ…）",
  ui_story_5051_50510101_212_dialog_content = "ぼ、僕の友だちです！",
  ui_story_5051_50510101_213_dialog_content = "左様でございましたか。\nPlayerName様のご友人でしたら、結構です。",
  ui_story_5051_50510101_214_dialog_content = "お二人ともどうぞお入りください。",
  ui_story_5051_50510101_215_dialog_content = "（口がうまいというか何というか…これが社交界の言い回し？）",
  ui_story_5051_50510101_216_dialog_content = "ありがとう、PlayerName…",
  ui_story_5051_50510101_217_dialog_content = "大した事してないよ！僕がついてるから、安心してね。",
  ui_story_5051_50510101_218_dialog_content = "ずる～い…PlayerNameばかりちやほやされちゃって。\nなんで北境の使者の私がこんなに存在感薄いんです？",
  ui_story_5051_50510101_219_dialog_content = "あなたが北境の使者、ジャキーニさんですね？",
  ui_story_5051_50510101_220_dialog_content = "そうです！北境の女王ベツレヘム陛下の勅命を受けた、\n新任の北境の使者ジャキーニです！",
  ui_story_5051_50510101_221_dialog_content = "やはりそうでしたか。お噂にたがわず、美しい赤髪をしていらっしゃいます。\n前任の方とよく似ていらっしゃいますね。",
  ui_story_5051_50510101_222_dialog_content = "前任の使者を知ってるんですか？\n<color=#FFB400>ボアーズ</color>は私の母なんですよ。",
  ui_story_5051_50510101_223_dialog_content = "それはそれは…",
  ui_story_5051_50510101_224_dialog_content = "なんとも光栄なことです。僕は白夜城のカレブと申します。\nあなたと同様、ソルラド殿下に謁見するために来ました。",
  ui_story_5051_50510101_225_dialog_content = "いかがでしょう？今日のパーティー、ご一緒しませんか？",
  ui_story_5051_50510101_226_dialog_content = "それは……",
  ui_story_5051_50510101_227_dialog_content = "あなたのお母様のこともお話できますよ。",
  ui_story_5051_50510101_228_dialog_content = "本当ですか！？嬉しいです！",
  ui_story_5051_50510101_X225_dialog_content = "ご一緒しませんか、というのは…？\nもっとハッキリ言ってもらえません？",
  ui_story_5051_50510101_X226_dialog_content = "ハハハ…要するに、あなたをお迎えに上がるよう、城主様から申し付かっているのです。",
  ui_story_5051_50510101_X227_dialog_content = "城主様のお迎えですって！？",
  ui_story_5051_50510101_X228_dialog_content = "もう～、やっぱり私は北境の使者ですからね！\nそれ相応のもてなしを受けるってことですね！",
  ui_story_5051_50510101_X229_dialog_content = "ちょっと待っててくださいね。\n友だちに一言挨拶してから行きますから！",
  ui_story_5051_50510101_229_dialog_content = "えへへ…では、PlayerName。\n一緒に城主様に謁見してくれる人ができたので、また後で！",
  ui_story_5051_50510101_230_dialog_content = "え？どこ行くの？\n…あっという間にいなくなっちゃった。",
  ui_story_5051_50510101_231_dialog_content = "女王陛下から一緒に行くように言われてるのに、\n会場についた途端に他の人について行っちゃうなんて…",
  ui_story_5051_50510101_X231_dialog_content = "（まあいいか。もともと招待されたから来ただけのことだし）",
  ui_story_5051_50510101_X232_dialog_content = "（だけどミヤが家族と会えるかどうかは、僕にかかってる。\nミヤの信頼にこたえるためにも、今日はミヤ中心で動こう）",
  ui_story_5051_50510101_X233_dialog_content = "ミヤ、大丈夫？",
  ui_story_5051_50510101_232_dialog_content = "うう…私…",
  ui_story_5051_50510101_233_dialog_content = "（いけない、ここは白夜城の貴族だらけだから…\nミヤがもう限界みたいだ）",
  ui_story_5051_50510101_234_dialog_content = "どこか落ち着ける場所を探してひと休みしようか？",
  ui_story_5051_50510101_235_dialog_content = "でも、カレンが…カレンにまだ、会ってないわ…",
  ui_story_5051_50510101_236_dialog_content = "大丈夫だよ！先に休んでて。\n僕が必ずカレンを連れてくるから！",
  ui_story_5051_50510101_237_dialog_content = "PlayerName…",
  ui_story_5051_50510101_238_dialog_content = "扉を出て左側に、応接室があるわ…",
  ui_story_5051_50510101_239_dialog_content = "扉を出て左…あった！",
  ui_story_5051_50510101_240_dialog_content = "この扉は外開きなの。押しても開かない…",
  ui_story_5051_50510101_241_dialog_content = "よいしょ…開いた！",
  ui_story_5051_50510101_X238_dialog_content = "あっちに扉が3つあるわ。応接室の入口には…白い花瓶が2つ…",
  ui_story_5051_50510101_X239_dialog_content = "カレンが子どもの頃、扉の枠にキズをつけてしまったの…",
  ui_story_5051_50510101_X240_dialog_content = "扉を出て左、と。確かに扉が3つある。",
  ui_story_5051_50510101_X241_dialog_content = "白い花瓶が2つ置かれてるのは…一番左だね。",
  ui_story_5051_50510101_X242_dialog_content = "応接室で間違いないよ！",
  ui_story_5051_50510101_X243_dialog_content = "（扉の枠の内側に確かに目立たないキズがある。ミヤの言った通りだ）",
  ui_story_5051_50510101_242_dialog_content = "（ミヤは色々詳しいな。まるで前に来たことがあるみたいだ）",
  ui_story_5051_50510101_243_dialog_content = "（やっぱり、白夜城のお姫様だったというのは本当…？）",
  ui_story_5051_50510201_1_dialog_content = "式次第は『白夜城に捧げる叙事詩』まで順調に進んでおります。",
  ui_story_5051_50510201_2_dialog_content = "この後の余興は歌舞を中心としたもので、\n上流階級の才能あふれる青年たちが壇上にあがります。",
  ui_story_5051_50510201_3_dialog_content = "ご来賓の方々からも陛下にぜひ会場へお越しいただき、\n楽しんでいただきたいとの声が上がっております。",
  ui_story_5051_50510201_4_dialog_content = "次第の調整を望む声もいくらか上がっておりまして――",
  ui_story_5051_50510201_5_dialog_content = "「息子の独奏を最後から2番目にしてほしい」、\n「娘のダンスにはセットが必要だから後の方にしてほしい」といった声がありましたが…",
  ui_story_5051_50510201_6_dialog_content = "これらの要求については、私の方で「適切に」処理させていただきました。\nどうぞご確認くださいませ。",
  ui_story_5051_50510201_7_dialog_content = "必要ない。お主を信用しておる。",
  ui_story_5051_50510201_8_dialog_content = "カレンに代わっての宴の支度と警備の仕事、感謝する。",
  ui_story_5051_50510201_9_dialog_content = "…「記念日」の一切を取り仕切るのは、そもそもカレンの職務なのだが…",
  ui_story_5051_50510201_10_dialog_content = "ここ何年もの間、逃げ続けているのでな。",
  ui_story_5051_50510201_11_dialog_content = "私にとって、今日はお母様の命日でしかありません。",
  ui_story_5051_50510201_12_dialog_content = "お母様が亡くなった時、私はそばにいてあげられませんでした。\nですから、今日私が城内に留まることもありません。",
  ui_story_5051_50510201_13_dialog_content = "――毎年そう言って、独りで白夜城を離れるのだ。",
  ui_story_5051_50510201_14_dialog_content = "母親と共に過ごした時間は多くはない。\nだが、母を失った痛みは今だ引きずっておる。",
  ui_story_5051_50510201_15_dialog_content = "カレン殿下はまだ子供だとおっしゃりたいのですか？",
  ui_story_5051_50510201_16_dialog_content = "その反対だ。全ては、余が若き頃に犯した過ちが故。",
  ui_story_5051_50510201_17_dialog_content = "己で蒔いた種を己が食らうことになっただけだ。",
  ui_story_5051_50510201_18_dialog_content = "ご自分をお責めにならないでください。",
  ui_story_5051_50510201_19_dialog_content = "私たちは神でも聖人でもございません。\n城主様は人として、輝かしい至上の功績を残されました。",
  ui_story_5051_50510201_20_dialog_content = "過程に過ちがあったとしても、\nそれに勝る功績を残したことは今の白夜城を見れば明らかです。",
  ui_story_5051_50510201_21_dialog_content = "城主様がいらっしゃらなければ、どれほど素晴らしい観光案内人であろうと、\n白夜城の魅力を伝えることはできなかったでしょう。",
  ui_story_5051_50510201_22_dialog_content = "まったくもって、Ms.ブランの言う通りですな。",
  ui_story_5051_50510201_23_dialog_content = "いや、その装束なら「Ms.ロト」と呼ぶべきかな？",
  ui_story_5051_50510201_24_dialog_content = "オットー公爵、ごきげんよう。\n本日は城主様の功績を讃え祝う、宴の日でございます。",
  ui_story_5051_50510201_25_dialog_content = "私のようなつまらない者など、お好きなようにお呼びくださいませ。",
  ui_story_5051_50510201_26_dialog_content = "つまらない者？ハハハ、冗談がうまくなったな。\nナイトガーディアン、「Ms.ロト」？",
  ui_story_5051_50510201_27_dialog_content = "殿下、遅れて申し訳ない。\n昔話のお邪魔でしたかな？",
  ui_story_5051_50510201_28_dialog_content = "宴の夜に煩雑な礼儀など気にせずともよい。\n心ゆくまで楽しむがいい。",
  ui_story_5051_50510201_29_dialog_content = "そうは参りますまい。\n何しろ今夜は城主様の白夜城に対する偉大な貢献をたたえる宴。",
  ui_story_5051_50510201_30_dialog_content = "殿下の身近な者に理解されていない事だけは、\n歯がゆいところですがな。",
  ui_story_5051_50510201_31_dialog_content = "高き処こそは寒さに耐えず、とでも言うべきか。",
  ui_story_5051_50510201_32_dialog_content = "お主も同じであろう、オットー。",
  ui_story_5051_50510201_33_dialog_content = "トロイ家と元老院のため、\n長年大きな「犠牲」を払っている。",
  ui_story_5051_50510201_34_dialog_content = "とんでもない。\n殿下とは比べ物になりませんな。",
  ui_story_5051_50510201_35_dialog_content = "余興の後で、愚息が挨拶に立ちます。\n殿下にもお越しいただければ幸いです。",
  ui_story_5051_50510201_36_dialog_content = "それは実に残念だ。\nこの後は客人と会う約束がある。",
  ui_story_5051_50510201_37_dialog_content = "お主の養子の「出し物」とあらば、\n盛大な拍手が送られることであろう。",
  ui_story_5051_50510201_38_dialog_content = "余の拍手一つ、欠けたとて変わらぬ。",
  ui_story_5051_50510201_39_dialog_content = "城主様、従者より報告がございました。\n約束のお客様が会場に到着されたそうです。",
  ui_story_5051_50510201_40_dialog_content = "噂をすれば、か。ちょうど客人が来たようだ。\n今晩は存分に楽しむがよい、オットー公爵。",
  ui_story_5051_50510201_41_dialog_content = "恐れ入ります、殿下。",
  ui_story_5051_50510201_42_dialog_content = "…つまり、ドラゴンって本当に不思議な生物なんですよ。",
  ui_story_5051_50510201_43_dialog_content = "小さいのは手のひらサイズなのに、\n大きいものになると巨像くらいの大きさになるんです！",
  ui_story_5051_50510201_44_dialog_content = "そういえば、ドラゴンと巨像ってちょっと似てますよね。\nまさか何か関係あったりするんでしょうか？",
  ui_story_5051_50510201_45_dialog_content = "オホン…ジャキーニさん。",
  ui_story_5051_50510201_46_dialog_content = "はい？どうかしました？",
  ui_story_5051_50510201_47_dialog_content = "前任の使者であられたボアーズさんは偉大な占い師だったと聞きました。",
  ui_story_5051_50510201_48_dialog_content = "僕は北境の占術に大変興味があるのですが、\nあなたも占いの知識をお持ちでしょうか？",
  ui_story_5051_50510201_49_dialog_content = "もちろんですよ。知ってるどころか、私は腕のいい…",
  ui_story_5051_50510201_50_dialog_content = "うーん…とにかく私も占い師なんです！",
  ui_story_5051_50510201_51_dialog_content = "北境の女王陛下がわざわざ私を使者にしたのは、\n「<color=#FFB400>記憶の鏡晶</color>」に鏡湖の水を注ぐためですしね。",
  ui_story_5051_50510201_52_dialog_content = "「記憶の鏡晶」のことは僕も聞いたことがあります。",
  ui_story_5051_50510201_53_dialog_content = "ですが、なぜ「記憶の鏡晶」に鏡湖の水を注がねばならないのですか？",
  ui_story_5051_50510201_54_dialog_content = "記憶の鏡晶は光力を保存しておくものでは…？",
  ui_story_5051_50510201_55_dialog_content = "ごきげんよう、ジャキーニさん。ようやくお会いできました。",
  ui_story_5051_50510201_56_dialog_content = "あ、こんばんは！",
  ui_story_5051_50510201_57_dialog_content = "<size=30>カレブさん、この方は？</size>",
  ui_story_5051_50510201_58_dialog_content = "お久しぶりです、Ms.ブラン。",
  ui_story_5051_50510201_59_dialog_content = "こちらこそ。「ソルラド家記念日」の宴席でお会いするのは初めてですね。\nご出席、誠にありがとうございます。",
  ui_story_5051_50510201_60_dialog_content = "この方はMs.ブランです。\n城主殿下の…助手と言えばよいでしょうか。",
  ui_story_5051_50510201_61_dialog_content = "そうでしたか…",
  ui_story_5051_50510201_62_dialog_content = "城主様がすでに応接室でお待ちです。ご案内いたします。",
  ui_story_5051_50510201_63_dialog_content = "は、初めまして！\n北境の女王より新たに任命された北境の使者、ジャキーニと申します！",
  ui_story_5051_50510201_64_dialog_content = "北境の使者が最後に白夜城を訪れたのは12年前でした。",
  ui_story_5051_50510201_65_dialog_content = "この度は私が女王陛下の命を受け、\n「記憶の鏡晶」に<color=#FFB400>鏡湖の水</color>を注がせていただきます。",
  ui_story_5051_50510201_66_dialog_content = "大儀である、北境の使者よ。",
  ui_story_5051_50510201_67_dialog_content = "そのことについては、女王陛下からの手紙を受け取っている。\n使命のため遠き地から、よくぞ参った。",
  ui_story_5051_50510201_68_dialog_content = "とんでもありません！これが仕事ですから！",
  ui_story_5051_50510201_69_dialog_content = "Ms.ロト、「記憶の鏡晶」を。",
  ui_story_5051_50510201_70_dialog_content = "承知いたしました。",
  ui_story_5051_50510201_71_dialog_content = "…",
  ui_story_5051_50510201_72_dialog_content = "余は北境の使者を呼ぶよう、Ms.ロトに命じたはずだが。",
  ui_story_5051_50510201_73_dialog_content = "宴の席で北境の使者と友人になったとでも言うのか、カレブ？",
  ui_story_5051_50510201_74_dialog_content = "申し訳ございません、殿下。",
  ui_story_5051_50510201_75_dialog_content = "<color=#FFB400>姉の形見</color>のことでございますし、\n遺族の私が席を外す必要はないかと考えました。",
  ui_story_5051_50510201_76_dialog_content = "殿下にそこまで避けられているとは思っておりませんでしたから。",
  ui_story_5051_50510201_77_dialog_content = "（姉の形見？遺族？避けられている？…どうなってるんです？\nなんでこんな気まずい空気になってるんでしょう？）",
  ui_story_5051_50510201_78_dialog_content = "（PlayerName、ミヤ、私が間違ってました…）",
  ui_story_5051_50510201_X78_dialog_content = "（2人を置いて、私一人で使命を果たしに来るんじゃありませんでした。\n誰か助けてください！）",
  ui_story_5051_50510201_79_dialog_content = "殿下、カレブ様は私がお連れしました。",
  ui_story_5051_50510201_80_dialog_content = "殿下にお目にかかりたいとおっしゃっていたのですが、\nご予定が詰まっているので、私がご一緒にとお誘いしたのです。",
  ui_story_5051_50510201_81_dialog_content = "カレブ様はご親族ですので、\n殿下のご予定としても、優先すべきかと考えました。",
  ui_story_5051_50510201_82_dialog_content = "Ms.ロト…お主は時に気が利きすぎるな。",
  ui_story_5051_50510201_83_dialog_content = "お褒めに預かり光栄です。",
  ui_story_5051_50510201_84_dialog_content = "「記憶の鏡晶」はこちらです。よろしくお願いいたします。",
  ui_story_5051_50510201_85_dialog_content = "わかりました、任せてください！",
  ui_story_5051_50510201_86_dialog_content = "（た、助かりました！ありがとう、Ms. ブラン！）",
  ui_story_5051_50510201_87_dialog_content = "カレブ様、こちらは影ノ街の銘酒です。\nあるお客様からいただいたものです。",
  ui_story_5051_50510201_88_dialog_content = "気持ちを落ち着かせる作用があるそうです。\nどうぞお召し上がりください。",
  ui_story_5051_50510201_89_dialog_content = "…ありがとうございます。",
  ui_story_5051_50510201_90_dialog_content = "カレブ、用というのは「記憶の鏡晶」か？",
  ui_story_5051_50510201_91_dialog_content = "あれは北境の女王から我ら夫婦に贈られた<color=#FFB400>記録装置</color>だ。",
  ui_story_5051_50510201_92_dialog_content = "12年前に余の妻、つまりお主の姉が自らこの水晶を起動した。",
  ui_story_5051_50510201_93_dialog_content = "だが、中に保存されているのは当時の記憶にすぎぬ。",
  ui_story_5051_50510201_94_dialog_content = "余もあやつが逝ってから、代わりに保管していたにすぎん。\n決して独占するつもりで保有しているのではない。",
  ui_story_5051_50510201_95_dialog_content = "女王に返還を求められれば、\n余は何も言わずに返すであろう。",
  ui_story_5051_50510201_96_dialog_content = "…殿下にとって、家族との思い出など何の価値もないということですか？",
  ui_story_5051_50510201_97_dialog_content = "じょ、女王陛下は水晶を取り戻したいなどとは申しておりません！",
  ui_story_5051_50510201_98_dialog_content = "中の世界はもう、起動した者の光力によって動きだしています。\n女王陛下が今さら取り返したところで何の意味もありませんから！",
  ui_story_5051_50510201_99_dialog_content = "中の世界？",
  ui_story_5051_50510201_100_dialog_content = "そうですよ。「記憶の鏡晶」はただの記録装置じゃないんです。",
  ui_story_5051_50510201_101_dialog_content = "中には<color=#FFB400>本物の世界</color>が保存されているんです！",
  ui_story_5051_50510201_102_dialog_content = "いったいどういうことですか？",
  ui_story_5051_50510201_103_dialog_content = "うーん、カレブさんは「記憶の鏡晶」のこと、よく知らないみたいですね。",
  ui_story_5051_50510201_104_dialog_content = "だったら、私が教えてさしあげます！",
  ui_story_5051_50510201_105_dialog_content = "まず、「記憶の鏡晶」には十分な量の鏡湖の水が入っていなきゃいけません。",
  ui_story_5051_50510201_106_dialog_content = "それから、これを使おうとする者が自身の光力を注ぎ、\n「記憶の鏡晶」を起動するんです。",
  ui_story_5051_50510201_107_dialog_content = "そうすると「記憶の鏡晶」の一定範囲内で\n<color=#FFB400>その日一日に起こったすべての出来事</color>を自動で記録するんです。",
  ui_story_5051_50510201_108_dialog_content = "記録はすべて「記憶の鏡晶」の中に保存されて、\n復元された世界が繰り返し「再生」されます。",
  ui_story_5051_50510201_109_dialog_content = "最初に起動した者が再度光力を注ぐと、「記憶の鏡晶」の中に入ることができて、復元された世界を体験できるんです。",
  ui_story_5051_50510201_110_dialog_content = "それが「記憶の鏡晶」の中にある世界の秘密です。",
  ui_story_5051_50510201_111_dialog_content = "ただ、「記憶の鏡晶」はとってももろいので…",
  ui_story_5051_50510201_112_dialog_content = "中に入った人の姿は何もしなければ見えないようになりますし、\n中の世界の物や人と接触しちゃいけないんです。",
  ui_story_5051_50510201_113_dialog_content = "<size=42>うっかり過去を変えてしまったりしたら、\n想像を絶する災難を招きかねないですからね！</size>",
  ui_story_5051_50510201_114_dialog_content = "北境の術と言うものは不思議ですね…",
  ui_story_5051_50510201_115_dialog_content = "<size=30>なんと面倒なものなのでしょう…</size>",
  ui_story_5051_50510201_116_dialog_content = "よいしょっと…さあ、これで鏡湖の水は注ぎ終わりました！",
  ui_story_5051_50510201_117_dialog_content = "城主様、どうぞ。",
  ui_story_5051_50510201_118_dialog_content = "これでいつでも起動できますよ。",
  ui_story_5051_50510201_119_dialog_content = "ご苦労であった、北境の使者よ。",
  ui_story_5051_50510201_120_dialog_content = "…遺憾ながら、これを起動した者はすでに他界しておる。",
  ui_story_5051_50510201_121_dialog_content = "そも、生前でさえあの過去を顧みたいと望む者はいなかった。",
  ui_story_5051_50510201_122_dialog_content = "あやつが世を去った以上、余でもこれを用いることはできん。",
  ui_story_5051_50510201_123_dialog_content = "おそらく再びこれを起動できる者はおらぬだろう。",
  ui_story_5051_50510201_124_dialog_content = "え…",
  ui_story_5051_50510201_125_dialog_content = "し、心配いりません！\n北境の占い師の私がいるんです。きっと他の方法があります！",
  ui_story_5051_50510201_126_dialog_content = "ええと…使い方と呪文はっと…",
  ui_story_5051_50510201_127_dialog_content = "…",
  ui_story_5051_50510201_128_dialog_content = "使い方と呪文はどうだったかしら…",
  ui_story_5051_50510201_129_dialog_content = "ヨシュア、それの使い方は二人で覚えようと約束したではないか。",
  ui_story_5051_50510201_130_dialog_content = "お主が学びに貪欲なことはよく分かっているが、\nいつも先を越されてばかりでは、余も寂しくてかなわぬぞ。",
  ui_story_5051_50510201_131_dialog_content = "あら、あなたも寂しいなんて思うことがあるのね。",
  ui_story_5051_50510201_132_dialog_content = "寂しいのはいつもわたくしだけだと思っていたわ。",
  ui_story_5051_50510201_133_dialog_content = "すまぬ。まつりごとが忙しく、\nお主や子どもらをかまってやれないことは、申し訳なく思っている。",
  ui_story_5051_50510201_134_dialog_content = "ふふ、冗談よ。",
  ui_story_5051_50510201_135_dialog_content = "あなたが忙しくしているからこそ、\n皆がこうして平和な日々を送り、色々な思いを抱けるのよ。",
  ui_story_5051_50510201_136_dialog_content = "幸せも、楽しさも、喜びも…それから、寂しさも。",
  ui_story_5051_50510201_137_dialog_content = "でも、今は北境の女王陛下からいただいた贈り物があるわ。",
  ui_story_5051_50510201_138_dialog_content = "そういう時は「記憶の鏡晶」の世界に入れば、\nあなたに会えるでしょ。",
  ui_story_5051_50510201_139_dialog_content = "ヨシュア…",
  ui_story_5051_50510201_140_dialog_content = "だから、水晶はわたくしが起動するわ。いい？",
  ui_story_5051_50510201_141_dialog_content = "構わぬ。お主が喜ぶなら、それでよい。",
  ui_story_5051_50510201_142_dialog_content = "それはそうと、いつの日を記録するつもりなのだ？",
  ui_story_5051_50510201_143_dialog_content = "<color=#FFB400>ヴェロニカ</color>の誕生日か？\nカレンの演奏会か？それとも…",
  ui_story_5051_50510201_144_dialog_content = "今は秘密よ。",
  ui_story_5051_50510201_145_dialog_content = "もったいぶらずともよいではないか。\n大切な日に不始末がないようにせねばならん。",
  ui_story_5051_50510201_146_dialog_content = "あら、偉大な城主様が失敗なんてするのかしら？",
  ui_story_5051_50510201_147_dialog_content = "…以前にも不注意でカレンの玩具を壊してしまったことがあった。",
  ui_story_5051_50510201_148_dialog_content = "あの時はカレンが何の反応もせぬものだから気にしていなかったが、\nまさか後になって部屋で泣いていたとは…",
  ui_story_5051_50510201_149_dialog_content = "そうそう、あの時はあなたが新しいおもちゃを抱えて\n怖い顔で部屋の前をウロウロしていたから、召使たちがずいぶん怯えてたわね。",
  ui_story_5051_50510201_150_dialog_content = "他には？",
  ui_story_5051_50510201_151_dialog_content = "…他には、ヴェロニカがくれたバラの花のリースを応接間に置き忘れてしまった…",
  ui_story_5051_50510201_152_dialog_content = "あの時は来客の応対で手一杯だっただけなのだが、\nヴェロニカは余が気に入らなかったと誤解し、リースを捨ててしまった…",
  ui_story_5051_50510201_153_dialog_content = "それで後になって、わざわざバラの花畑を作ってあげたのよね。",
  ui_story_5051_50510201_154_dialog_content = "でも、その後すぐにあの子は訓練に打ち込むようになって、\n花のリースを作るようなこともしなくなったわ…",
  ui_story_5051_50510201_155_dialog_content = "はぁ…",
  ui_story_5051_50510201_156_dialog_content = "ダニエル。それもこれも別に、不始末なんかじゃないわ。",
  ui_story_5051_50510201_157_dialog_content = "この世界はとても複雑なの。\nそれに引き換え、わたくしたちができることや見えることには限りがある。",
  ui_story_5051_50510201_158_dialog_content = "だから、「記憶の鏡晶」はとてもいい機会だと思うの…\n全部を余すことなく記録できるから。",
  ui_story_5051_50510201_159_dialog_content = "思い出はいつだってどこか欠けているものよ。\nでも、この水晶なら、ありのままのわたくしたちを永遠に保存できる。",
  ui_story_5051_50510201_160_dialog_content = "いいことも、悪いことも、正しいことも、過ちも…\nいつか、わたくしたちや子どもたちが迷ってしまった時――",
  ui_story_5051_50510201_161_dialog_content = "水晶の中の世界できっと、<color=#FFB400>本当の答え</color>を見つけられるはず。",
  ui_story_5051_50510201_162_dialog_content = "<color=#e8d9bb>ガチャン！</color>",
  ui_story_5051_50510201_163_dialog_content = "…",
  ui_story_5051_50510201_164_dialog_content = "何者だ？姿を見せるがいい。",
  ui_story_5051_50510201_165_dialog_content = "あ、あの、僕です！\nPlayerNameです。申し訳ありません…",
  ui_story_5051_50510201_166_dialog_content = "――つまり、こういうことですね。",
  ui_story_5051_50510201_167_dialog_content = "あなたは城主殿下に贈り物を渡そうと探していたところ、\n意図せず応接室に入ってしまい――",
  ui_story_5051_50510201_168_dialog_content = "そこに我々一行が突然現れたので、\n反射的に身を隠し、そのまま出て来る機会を逃してしまった。",
  ui_story_5051_50510201_169_dialog_content = "そしてカーテンの裏に隠れたまま、\n今まで盗み聞きしていた、と。",
  ui_story_5051_50510201_170_dialog_content = "これで間違いありませんか？",
  ui_story_5051_50510201_171_dialog_content = "はい、その通りです。申し訳ありません…",
  ui_story_5051_50510201_172_dialog_content = "（正確にはミヤが反射的に隠れたから、\n僕もつられて隠れたんだけど…）",
  ui_story_5051_50510201_173_dialog_content = "（まだ混乱してるミヤをいきなり会わせるのはまずい気がする）",
  ui_story_5051_50510201_174_dialog_content = "ひとまず、お主の好意には感謝しよう。",
  ui_story_5051_50510201_175_dialog_content = "だが、盗み聞きは感心せぬ。",
  ui_story_5051_50510201_176_dialog_content = "次は許さぬぞ。",
  ui_story_5051_50510201_177_dialog_content = "はい、分かりました。ありがとうございます…",
  ui_story_5051_50510201_178_dialog_content = "では、今一つお主に尋ねるとしよう…",
  ui_story_5051_50510201_179_dialog_content = "テーブルの下に隠れている者は、お主の友人か？",
  ui_story_5051_50510201_180_dialog_content = "そうでないのなら、手加減させる理由もないが。",
  ui_story_5051_50510201_X177_dialog_content = "では、もう一つお尋ねしたいのですが…",
  ui_story_5051_50510201_X178_dialog_content = "テーブルの下に隠れている方は、お友だちでいらっしゃいますか？",
  ui_story_5051_50510201_X179_dialog_content = "もしそうでないのなら、片付けさせていただきますが。",
  ui_story_5051_50510201_181_dialog_content = "あ、と、ととと、友だちです！",
  ui_story_5051_50510201_182_dialog_content = "出てきて…ミヤ。大丈夫だよ。\n皆いい人だから。怖がることないよ。",
  ui_story_5051_50510201_183_dialog_content = "ちょ、ちょっと待って。ベールが…見当たらないの…",
  ui_story_5051_50510201_184_dialog_content = "白夜城の貴族のご令嬢でしたか？\nしかし、その面立ち…",
  ui_story_5051_50510201_185_dialog_content = "これは…",
  ui_story_5051_50510201_186_dialog_content = "…",
  ui_story_5051_50510201_187_dialog_content = "Ms.ロト、これもお主が用意した「サプライズ」か？",
  ui_story_5051_50510201_188_dialog_content = "いや、よい。それよりもまず、余の予定だ。",
  ui_story_5051_50510201_189_dialog_content = "気が回らず誠に申し訳ございません。\nこの後のご予定はすべて取り消して参ります。",
  ui_story_5051_50510201_190_dialog_content = "任せたぞ。",
  ui_story_5051_50510201_191_dialog_content = "これとこれを…合わせれば…分かりました！",
  ui_story_5051_50510201_192_dialog_content = "分かりましたよ！呪文が分かりました！",
  ui_story_5051_50510201_193_dialog_content = "北境の使者よ、もうよい。\nお主はPlayerNameと共に宴を楽しまれよ。",
  ui_story_5051_50510201_194_dialog_content = "我ら3人で少々、話をせねばならぬのでな…",
  ui_story_5051_50510201_195_dialog_content = "ええと…ジャキーニ、とりあえず席を外そう…ジャキーニ？",
  ui_story_5051_50510201_196_dialog_content = "アド・プラエテリトゥム～、アド・プラエテリトゥム～、アド・プラエテリトゥム！",
  ui_story_5051_50510201_197_dialog_content = "我らを過去のあの日へと導きたまえ！",
  ui_story_5051_50510201_198_dialog_content = "<size=45>アブラハダブラ！</size>",
  ui_story_5051_50510201_199_dialog_content = "な…！？",
  ui_story_5051_50510201_200_dialog_content = "<size=45>な、何が起こったの！？</size>",
  ui_story_5051_50510201_201_dialog_content = "PlayerName…助けて…",
  ui_story_5051_50510201_202_dialog_content = "ミヤ！僕の手をつかんで！",
  ui_story_5051_50510201_203_dialog_content = "うん…！",
  ui_story_5051_50510201_204_dialog_content = "うう…あれ…？",
  ui_story_5051_50510201_205_dialog_content = "…ここはどこだろう…？",
  ui_story_5051_50510201_206_dialog_content = "よ、よかった…ようやく気が付いたのね！",
  ui_story_5051_50510201_207_dialog_content = "ミヤ、ここはどこ？",
  ui_story_5051_50510201_208_dialog_content = "私にもわからないの…！\nそれより早く逃げましょう、暗鬼が来たわ！",
  ui_story_5051_50510201_209_dialog_content = "――！！",
  ui_story_5051_50510201_210_dialog_content = "暗鬼！？",
  ui_story_5051_50510201_211_dialog_content = "ミヤ、僕につかまって！こっちだ！",
  ui_story_5051_50510201_212_dialog_content = "PlayerName、そ、そっちにもいるわ…",
  ui_story_5051_50510201_213_dialog_content = "――！！",
  ui_story_5051_50510201_214_dialog_content = "取り囲まれた！？",
  ui_story_5051_50510201_215_dialog_content = "バ、バーバ・ヤーガ！バーバ・ヤーガ！助けて！",
  ui_story_5051_50510201_216_dialog_content = "お願いよ…どうして答えてくれないの…？",
  ui_story_5051_50510201_217_dialog_content = "くっ…ミヤ、僕から絶対に離れないでね！",
  ui_story_5051_50510201_218_dialog_content = "暗鬼め！こうなったら僕が相手だ！！",
  ui_story_5051_50510201_219_dialog_content = "<size=45>グォオオ――！！</size>",
  ui_story_5051_50510201_220_dialog_content = "ダメ…",
  ui_story_5051_50510201_221_dialog_content = "やめて…",
  ui_story_5051_50510201_222_dialog_content = "<size=45>PlayerNameを傷つけないで！！</size>",
  ui_story_5051_50510201_223_dialog_content = "グア！？",
  ui_story_5051_50510201_224_dialog_content = "ミ、ミヤ…？",
  ui_story_5051_50510201_225_dialog_content = "はぁ…はぁ…はぁ…",
  ui_story_5051_50510201_226_dialog_content = "私がやったの…？これは…光力術…？",
  ui_story_5051_50510201_227_dialog_content = "ミヤ、やっぱり光力術を使えるんだね！",
  ui_story_5051_50510201_228_dialog_content = "昔は使えていたの。\nただ、ずっと使えなくなっていて…",
  ui_story_5051_50510201_229_dialog_content = "――！！",
  ui_story_5051_50510201_230_dialog_content = "まだ来る！？いったいどれだけいるの！？",
  ui_story_5051_50510201_231_dialog_content = "まだ戦える？",
  ui_story_5051_50510201_232_dialog_content = "わ、わからないわ…",
  ui_story_5051_50510201_233_dialog_content = "でも…戦わないと、PlayerNameが危ないわ。",
  ui_story_5051_50510201_234_dialog_content = "私はPlayerNameを守りたい！",
  ui_story_5051_50510201_235_dialog_content = "ミヤ、君ならきっと大丈夫だよ！",
  ui_story_5051_50510201_236_dialog_content = "光力術を使えるなら、\nあとは僕が力を引き出してあげられる。",
  ui_story_5051_50510201_237_dialog_content = "僕を信じて！自分のことも！",
  ui_story_5051_50510201_238_dialog_content = "あなたを信じる…私自身のことも…",
  ui_story_5051_50510201_239_dialog_content = "わかったわ、やってみる！",
  ui_story_5051_50510301_1_dialog_content = "ミヤ、大丈夫？",
  ui_story_5051_50510301_2_dialog_content = "私は大丈夫。まだ少しドキドキしてるけど…",
  ui_story_5051_50510301_3_dialog_content = "少し自信がついた気がするわ！",
  ui_story_5051_50510301_4_dialog_content = "PlayerName、さっきの戦いでケガはしてない？",
  ui_story_5051_50510301_5_dialog_content = "まったく何ともないよ。心配しないで！",
  ui_story_5051_50510301_6_dialog_content = "それにしても、ミヤはすごいよ。\n1人でこんなにたくさんの暗鬼を倒しちゃうんだから。",
  ui_story_5051_50510301_7_dialog_content = "そ、そうかしら？全部あなたのおかげだと思うわ。",
  ui_story_5051_50510301_8_dialog_content = "空の末裔の力って、本当に不思議ね…",
  ui_story_5051_50510301_9_dialog_content = "そう言えば、気が付いてからずっと、\n他の皆のことを感知できてないんだ。",
  ui_story_5051_50510301_10_dialog_content = "どこに行っちゃったのかな…\nそもそも、ここは一体どこ！？",
  ui_story_5051_50510301_11_dialog_content = "あれを見て。遠くの方に<color=#FFB400>白夜城</color>が見えるわ。",
  ui_story_5051_50510301_12_dialog_content = "つまり、ここは<color=#FFB400>白夜城の郊外</color>ってこと？",
  ui_story_5051_50510301_13_dialog_content = "どうして突然こんな所に…",
  ui_story_5051_50510301_14_dialog_content = "もしかして、ここは「<color=#FFB400>記憶の鏡晶</color>」の中の世界じゃないかしら？",
  ui_story_5051_50510301_15_dialog_content = "確かにその可能性は高いね！",
  ui_story_5051_50510301_16_dialog_content = "アド・プラエテリトゥム～、アド・プラエテリトゥム～、アド・プラエテリトゥム！",
  ui_story_5051_50510301_17_dialog_content = "我らを過去のあの日へと導きたまえ！",
  ui_story_5051_50510301_18_dialog_content = "アブラハダブラ！",
  ui_story_5051_50510301_19_dialog_content = "思い出した…ジャキーニ、本当にすごい占い師だったんだね。",
  ui_story_5051_50510301_20_dialog_content = "人の話を聞かないことが多いけど…",
  ui_story_5051_50510301_21_dialog_content = "そうね…",
  ui_story_5051_50510301_22_dialog_content = "確か、ジャキーニが言っていたわ。",
  ui_story_5051_50510301_23_dialog_content = "「中に入った人の姿は何もしなければ見えないようになる、\n中の世界の物や人と接触しちゃいけない」",
  ui_story_5051_50510301_24_dialog_content = "「うっかり過去を変えてしまったら、\n想像を絶する災難を招きかねない」…",
  ui_story_5051_50510301_25_dialog_content = "でも、さっき暗鬼には僕たちが見えてたよね。",
  ui_story_5051_50510301_26_dialog_content = "どうなってるんだろう…？",
  ui_story_5051_50510301_27_dialog_content = "<size=45>うわああ！！</size>",
  ui_story_5051_50510301_28_dialog_content = "ひ、悲鳴だわ！",
  ui_story_5051_50510301_29_dialog_content = "あれは…",
  ui_story_5051_50510301_30_dialog_content = "隊長！暗鬼の数が多すぎます。私たちではもう…",
  ui_story_5051_50510301_31_dialog_content = "集中しろ！たとえ周りの仲間が倒れようとも、武器を捨ててはならん！",
  ui_story_5051_50510301_32_dialog_content = "くそっ！！！",
  ui_story_5051_50510301_33_dialog_content = "荷車と…白夜城の兵士のいでたち…輸送隊が暗鬼に襲われているんだわ！",
  ui_story_5051_50510301_34_dialog_content = "白夜城のすぐ外にどうしてこんなにたくさん暗鬼がいるの？\nいったい何があったんだろう？",
  ui_story_5051_50510301_35_dialog_content = "た、助けに行かないと！",
  ui_story_5051_50510301_36_dialog_content = "待って！ジャキーニが言ってたでしょ。\n「記憶の鏡晶」の中の世界に干渉しちゃいけないって。",
  ui_story_5051_50510301_37_dialog_content = "ここで暗鬼と戦ったら、\nもっと大変なことになるかもしれない。",
  ui_story_5051_50510301_38_dialog_content = "でも…",
  ui_story_5051_50510301_39_dialog_content = "「迎え撃て！墓場へ行く前に！」",
  ui_story_5051_50510301_40_dialog_content = "――！？",
  ui_story_5051_50510301_41_dialog_content = "ボス、白夜城の兵士は大事ないようです。\n俺たちは引き上げましょう。",
  ui_story_5051_50510301_42_dialog_content = "ただ、ソルラドの野郎は俺たちのことを平気で見殺しにしたようなヤツですよ？\nなんだってそんな奴の手下を助けなきゃならないんです？",
  ui_story_5051_50510301_43_dialog_content = "祝いの日だっていうのに、食事も宿も用意しないどころか、\n受け取るもんだけ受け取って、さっさと俺たちを追い返したじゃありませんか。",
  ui_story_5051_50510301_44_dialog_content = "それだけじゃない…",
  ui_story_5051_50510301_45_dialog_content = "目の前の小さい利益に気をとられるな。\n機が熟せば、答えはおのずと浮かびあがる。",
  ui_story_5051_50510301_46_dialog_content = "<color=#FFB400>イスタバン</color>お父様…！",
  ui_story_5051_50510301_47_dialog_content = "あれがイスタバンさん！？若いなぁ！",
  ui_story_5051_50510301_48_dialog_content = "むっ…",
  ui_story_5051_50510301_49_dialog_content = "<color=#e8d9bb>ゴロゴロ――ピカッ！</color>",
  ui_story_5051_50510301_50_dialog_content = "（雷？よく晴れてるのに、雨でも降るの？）",
  ui_story_5051_50510301_51_dialog_content = "PlayerName！危ない！",
  ui_story_5051_50510301_52_dialog_content = "どうしてまた暗鬼が！？",
  ui_story_5051_50510301_53_dialog_content = "いったいどれだけ…",
  ui_story_5051_50510302_1_dialog_content = "はぁ…はぁ…はぁ…",
  ui_story_5051_50510302_2_dialog_content = "これで、もう終わりよね？私…もう限界…",
  ui_story_5051_50510302_3_dialog_content = "<color=#FFB400>ヴェロニカ</color>殿下、無事だったか？",
  ui_story_5051_50510302_4_dialog_content = "ヴェロニカ殿下…？おお、本当に殿下ではありませんか！",
  ui_story_5051_50510302_5_dialog_content = "なぜこのような所に！？",
  ui_story_5051_50510302_6_dialog_content = "うう…私は、なんともありません。",
  ui_story_5051_50510302_7_dialog_content = "それならよかった。",
  ui_story_5051_50510302_8_dialog_content = "先程の勇姿、普段とは大違いだったな。",
  ui_story_5051_50510302_9_dialog_content = "最初は人違いかと思い、声を掛けなかったが…\nどうやら今まで殿下の実力を見誤っていたようだ。",
  ui_story_5051_50510302_10_dialog_content = "いいえ、そんな風におっしゃらないで！",
  ui_story_5051_50510302_11_dialog_content = "今日は少し、状況が特別なだけです。",
  ui_story_5051_50510302_12_dialog_content = "（え？ミヤが僕のこと見てるけど、どういう意味？）",
  ui_story_5051_50510302_13_dialog_content = "今日は大切な日ではなかったのか？\nなぜこんな所にいる？",
  ui_story_5051_50510302_14_dialog_content = "まあ、構わんさ…俺が気にすることでもない。\nただ、外に出る時は十分気を付けることだ。",
  ui_story_5051_50510302_15_dialog_content = "あ、ありがとうございます。",
  ui_story_5051_50510302_16_dialog_content = "先程城主殿下に会ってきたのだが、忙しいようでな。\n王妃殿下とも話せなかった。",
  ui_story_5051_50510302_17_dialog_content = "どうかよろしく伝えてくれ。",
  ui_story_5051_50510302_18_dialog_content = "それから、できれば城主殿下には\n早く回答が欲しいと伝えてもらえるとありがたい。",
  ui_story_5051_50510302_19_dialog_content = "わかりました…かならず伝えておきます。\nいつも色々とありがとうございます。",
  ui_story_5051_50510302_20_dialog_content = "なに、やるべきことをやっているまでさ。",
  ui_story_5051_50510302_21_dialog_content = "（ミヤって本当にお姫様だったんだ！）",
  ui_story_5051_50510302_22_dialog_content = "それと、そこの少年。",
  ui_story_5051_50510302_23_dialog_content = "え、僕ですか？",
  ui_story_5051_50510302_24_dialog_content = "そうだ。殿下の大切なご友人と見える。",
  ui_story_5051_50510302_25_dialog_content = "殿下に直接守られるなどという光栄は、\nめったに受けられるものではないからな。",
  ui_story_5051_50510302_26_dialog_content = "男なら、己の手で立ち向かうことだ。",
  ui_story_5051_50510302_27_dialog_content = "いつも他人の後ろに立っていられるとは限らんぞ。",
  ui_story_5051_50510302_28_dialog_content = "は、はい…",
  ui_story_5051_50510302_29_dialog_content = "あの、僕たち前にどこかで会いましたか？",
  ui_story_5051_50510302_30_dialog_content = "ハハハ…！ずいぶん陳腐な口説き方だな。\nもう10年以上は聞いていなかったぞ。",
  ui_story_5051_50510302_31_dialog_content = "答えは「ノー」だ。",
  ui_story_5051_50510302_32_dialog_content = "面白い小僧だ。\nもしまた俺に会いたくなったら、影ノ街に訪ねてくるといい。",
  ui_story_5051_50510302_33_dialog_content = "あそこはもうすぐ影の帝国になる。",
  ui_story_5051_50510302_34_dialog_content = "影はすべてを受け入れる。\nだが、その中で生きていけるかどうかは己の力次第だ。",
  ui_story_5051_50510302_35_dialog_content = "すべてを受け入れる…確かにそうですね。",
  ui_story_5051_50510302_36_dialog_content = "イスタバン…おじさまの影ノ街はきっと、素晴らしい所になるでしょう。",
  ui_story_5051_50510302_37_dialog_content = "殿下にそう言ってもらえるなら、光栄の至りだ。",
  ui_story_5051_50510302_38_dialog_content = "さて、もう遅い。俺たちは引き上げるとしよう。",
  ui_story_5051_50510302_39_dialog_content = "ヴェロニカ殿下、それと面白い小僧も、また。",
  ui_story_5051_50510302_40_dialog_content = "はい…\n…今のイスタバンさん、僕の知ってるイスタバンさんよりずっと明るいね。",
  ui_story_5051_50510302_41_dialog_content = "なんだか不思議な気分だ。",
  ui_story_5051_50510302_42_dialog_content = "ええ。昔はイスタバンお父様も、今よりずっと元気だったの。",
  ui_story_5051_50510302_43_dialog_content = "後にいろんなことがあったから…みんな少しずつ変わっていったのね。",
  ui_story_5051_50510302_44_dialog_content = "ミヤ、「ヴェロニカ」殿下っていうのが君？",
  ui_story_5051_50510302_45_dialog_content = "イスタバンさんとも自然と会話できてたし、\nいつもの恥ずかしがり屋で引っ込み思案なミヤとは別人みたいだったよ。",
  ui_story_5051_50510302_46_dialog_content = "そ、そうかしら？",
  ui_story_5051_50510302_47_dialog_content = "今はまだ過去を切れ切れに思い出せるくらいよ。\n完全な記憶にはなっていないわ。",
  ui_story_5051_50510302_48_dialog_content = "でもなぜか、若い頃のイスタバンお父様を見たら…",
  ui_story_5051_50510302_49_dialog_content = "頭よりも先に、身体が礼儀や言葉遣いを思い出したみたい。",
  ui_story_5051_50510302_50_dialog_content = "ごめんなさい…自分でもうまく説明できないの。",
  ui_story_5051_50510302_51_dialog_content = "別にいいんだよ。もともと君の過去を探るために来たんだ。\n途中で色々あったし、うまく考えがまとまらなくて当然だよ。",
  ui_story_5051_50510302_52_dialog_content = "ねえ、ミヤ。\n「ヴェロニカ」姫のこと、君の覚えてる限りで話してくれる？",
  ui_story_5051_50510302_53_dialog_content = "ええ、いいわ。",
  ui_story_5051_50510302_54_dialog_content = "ヴェロニカは白夜城の<color=#FFB400>姫</color>。\nソルラド家の<color=#FFB400>長女</color>で――",
  ui_story_5051_50510302_55_dialog_content = "でも何年も前に、白夜城はその姫が<color=#FFB400>亡くなった</color>と発表している…",
  ui_story_5051_50510302_56_dialog_content = "亡くなった？どうして？",
  ui_story_5051_50510302_57_dialog_content = "姫がソルラド家の名誉を汚したからよ。",
  ui_story_5051_50510302_58_dialog_content = "つまり、不吉な存在であるヴェロニカには、\nもう生き続ける資格がないということ。",
  ui_story_5051_50510302_59_dialog_content = "名誉？不吉？どう関係あるの…？",
  ui_story_5051_50510302_60_dialog_content = "貴族というのはそういうものよ。\n体面が何よりも大事…",
  ui_story_5051_50510302_61_dialog_content = "PlayerName、光力で「<color=#FFB400>何らかの存在を呼び出せる</color>」ことは知ってるでしょ？",
  ui_story_5051_50510302_62_dialog_content = "私の記憶では、バーバ・ヤーガ以外に…\n「ヒポカ」という恐ろしい友だちがいたの。",
  ui_story_5051_50510302_63_dialog_content = "「ヒポカ」は私が召喚したの。\n小さい頃の私は強くなろうとして、一生懸命鍛錬に励んで…",
  ui_story_5051_50510302_64_dialog_content = "その結果として「ヒポカ」が出てきたの。",
  ui_story_5051_50510302_65_dialog_content = "ただ、みんなヒポカの見た目を嫌がって…\n頭が馬で身体がクモだったから、怪物だって言われたわ。",
  ui_story_5051_50510302_66_dialog_content = "あの人…私の父は特に嫌がっていたわ。\n「ヒポカ」は私たち家族にいわれのない批判を呼び込むと言われたの。",
  ui_story_5051_50510302_67_dialog_content = "「ヒポカ」は不吉、「ヒポカ」は存在すべきじゃない…\nそう言われ続けているうちに、私まで恐怖を抱くようになったわ。",
  ui_story_5051_50510302_68_dialog_content = "私自身の本質が体現したものなのに、\n他人から悪く言われたものだから、あの子を拒むようになって…",
  ui_story_5051_50510302_69_dialog_content = "結局、光力術を使えなくなってしまったの。",
  ui_story_5051_50510302_70_dialog_content = "代わりに「ヒポカ」によく似たバーバ・ヤーガが出てきて、\n「ヒポカ」の全部を引き継いだわ。",
  ui_story_5051_50510302_71_dialog_content = "…考えてみれば、全部自業自得ね。",
  ui_story_5051_50510302_72_dialog_content = "かわいそうに…",
  ui_story_5051_50510302_73_dialog_content = "でも、ここの人たちは君のことをヴェロニカって呼んでたよね。\nということは…",
  ui_story_5051_50510302_74_dialog_content = "殿下！先程はお助けくださりありがとうございました！",
  ui_story_5051_50510302_75_dialog_content = "いいえ、た、大したことじゃないわ。",
  ui_story_5051_50510302_76_dialog_content = "皆さんは無事？",
  ui_story_5051_50510302_77_dialog_content = "どうぞご安心ください。皆かすり傷ですので、すぐに出発できます。",
  ui_story_5051_50510302_78_dialog_content = "よろしければ、城内まで同行させていただきます。",
  ui_story_5051_50510302_79_dialog_content = "それは助かるわ。",
  ui_story_5051_50510302_80_dialog_content = "あの、聞いていいですか？\n今年って何年ですか？",
  ui_story_5051_50510302_81_dialog_content = "何年、ですか？\n<color=#FFB400>晨光歴1988年</color>ですが、どうかしましたか？",
  ui_story_5051_50510302_82_dialog_content = "（1988年…ということは<color=#FFB400>12年前</color>だ！）",
  ui_story_5051_50510302_83_dialog_content = "（12年前だとすると、天空ノ谷はもう滅亡してる）",
  ui_story_5051_50510302_84_dialog_content = "（ということは、この「記憶の鏡晶」の世界でも\n僕は自分の一族に会うことはできないのか…）",
  ui_story_5051_50510302_85_dialog_content = "PlayerName、どうしたの…？",
  ui_story_5051_50510302_86_dialog_content = "なんでもないよ。ミヤ、ちょっといいかな？",
  ui_story_5051_50510302_87_dialog_content = "ど、どうしたの？",
  ui_story_5051_50510302_88_dialog_content = "どうやら「記憶の鏡晶」の中の世界は\n「<color=#FFB400>12年前の白夜城</color>」みたいなんだ。",
  ui_story_5051_50510302_89_dialog_content = "僕の推測が間違ってなければ、\n応接室にいた他の皆も入ってきてるはず。",
  ui_story_5051_50510302_90_dialog_content = "ジャキーニは「記憶の鏡晶」の中の世界に干渉しちゃいけないって言ってたけど――",
  ui_story_5051_50510302_91_dialog_content = "今は状況が特殊みたいだ。僕たちの姿が隠れてないんだから。\n感知能力でも皆の反応がない。",
  ui_story_5051_50510302_92_dialog_content = "ならいっそ、君がお姫様っていう立場を利用して、\n一刻も早く皆を見つけて、一緒にこの世界から出る方法を探さない？",
  ui_story_5051_50510302_93_dialog_content = "…",
  ui_story_5051_50510302_94_dialog_content = "ミヤ、どうしたの？",
  ui_story_5051_50510302_95_dialog_content = "あの…PlayerName。",
  ui_story_5051_50510302_96_dialog_content = "そ、その…この世界を離れる前に、お母様に会ってもいいかしら？",
  ui_story_5051_50510302_97_dialog_content = "さっきテーブルの下で聞いたわ。\nお母様は私がいない間に亡くなられたって。",
  ui_story_5051_50510302_98_dialog_content = "本当は白夜城に戻ったら妹とお母様に会って、\nいろんなお話をたくさんしたいと思っていたの。",
  ui_story_5051_50510302_99_dialog_content = "「私、もう大きくなって、昔より勇気を持てるようになった」とか、\n「外の世界でたくさんのお友だちができた」とか…",
  ui_story_5051_50510302_100_dialog_content = "それから「ずっとお母様に会いたかった」って…",
  ui_story_5051_50510302_101_dialog_content = "でも、もう…叶わないのね。",
  ui_story_5051_50510302_102_dialog_content = "…ミヤのお母さんってことは、ソルラドさんの奥さんだよね。",
  ui_story_5051_50510302_103_dialog_content = "もし手を貸してもらえれば、きっと早く皆を見つけられるよ！",
  ui_story_5051_50510302_104_dialog_content = "だから、君のお母さんに会いに行くことは皆のためにもなる。\nそうじゃない？",
  ui_story_5051_50510302_105_dialog_content = "PlayerName、そんな言い方、ずるいわ…",
  ui_story_5051_50510302_106_dialog_content = "あはは、たまにはずるがしこくならないとね。",
  ui_story_5051_50510302_107_dialog_content = "巨像の仲間たちから学んだ処世術だよ…",
  ui_story_5051_50510302_108_dialog_content = "そうね…じゃあ、私も見習うことにするわ。",
  ui_story_5051_50510302_109_dialog_content = "はは…な、なんだかミヤに悪い事を教えてる気がしてきた…",
  ui_story_5051_50510302_110_dialog_content = "あの…お二人とも、そろそろよろしいですか？\nこれ以上遅れてしまうと…",
  ui_story_5051_50510302_111_dialog_content = "あ、すみません、もう行けます！",
  ui_story_5051_50510302_112_dialog_content = "何だか急いでるみたいですね。\n急ぎの用でもあるんですか？",
  ui_story_5051_50510302_113_dialog_content = "至急というほどではありませんが、\n物資をできるだけ早く送り届けなければならないのです。つまり…",
  ui_story_5051_50510302_114_dialog_content = "「<color=#FFB400>ソルラド家記念日</color>」の祝典に間に合わせないといけませんので。",
  ui_story_5051_50510302_115_dialog_content = "（「ソルラド家記念日」？偶然にしては…）",
  ui_story_5051_50510302_116_dialog_content = "<color=#e8d9bb>ゴロゴロ――</color>",
  ui_story_5051_50510302_117_dialog_content = "また雷だ…",
  ui_story_5051_50510302_118_dialog_content = "どうされましたか？",
  ui_story_5051_50510302_119_dialog_content = "なんでもありません。雨に降られる前に急いで出発しましょう。",
  ui_story_5051_50510302_120_dialog_content = "雨？こんな日にですか？\n…とにかく、準備ができたのなら出発しましょう。",
  ui_story_5051_50510302_121_dialog_content = "<anim type=Shake><size=32>…ソル…</size></anim>",
  ui_story_5051_50510302_122_dialog_content = "<anim type=Shake><size=32>…ラド…</size></anim>",
  ui_story_5051_50510302_123_dialog_content = "<anim type=Shake><size=32>…</size></anim>",
  ui_story_5051_50510402_1_dialog_content = "…",
  ui_story_5051_50510402_2_dialog_content = "ふぅ…どうしてこんな所に暗鬼が隠れていたのでしょう。",
  ui_story_5051_50510402_3_dialog_content = "白夜城はいつから暗鬼の巣窟になったのですか？",
  ui_story_5051_50510402_4_dialog_content = "わぁ、助かりました！",
  ui_story_5051_50510402_5_dialog_content = "カレブさんがちょうどいい時に現れてくれなかったら、\n私、暗鬼の夕食になるところでしたよ…",
  ui_story_5051_50510402_6_dialog_content = "いや、今は昼間みたいなので昼食ですね。",
  ui_story_5051_50510402_7_dialog_content = "その点は僕も疑問に思っていました。",
  ui_story_5051_50510402_8_dialog_content = "ジャキーニさん、先ほどまで、\n僕たちが白夜城の宮殿にいた時は夜でしたよね。",
  ui_story_5051_50510402_9_dialog_content = "それがなぜ、屋外の森の中にいるのでしょう？\nしかも昼間の。",
  ui_story_5051_50510402_10_dialog_content = "まさか、ここは「記憶の鏡晶」の世界ですか？",
  ui_story_5051_50510402_11_dialog_content = "その通りです！\nとりあえずでつなぎ合わせた呪文が本当に成功するなんて思ってもいませんでしたよ。",
  ui_story_5051_50510402_12_dialog_content = "私ってもしかして天才…？",
  ui_story_5051_50510402_13_dialog_content = "（ある意味、本当に「天才」ですよ…）",
  ui_story_5051_50510402_14_dialog_content = "近くの建物の様式から見るに、ここは白夜城ダウンタウンの郊外ですね。",
  ui_story_5051_50510402_15_dialog_content = "先程ジャキーニさんが座って、うっかり壊してしまったその箱も――",
  ui_story_5051_50510402_16_dialog_content = "紋章を見るかぎり、「ソルラド家記念日」を祝うために準備された物のようです。",
  ui_story_5051_50510402_17_dialog_content = "さっきは本当にびっくりしましたよ！",
  ui_story_5051_50510402_18_dialog_content = "見た目は丈夫そうなのに、ちょっと座っただけでつぶれちゃうなんて！",
  ui_story_5051_50510402_19_dialog_content = "しかも中から暗鬼がたくさん飛び出してくるなんて！",
  ui_story_5051_50510402_20_dialog_content = "いったいどうなってるんです？\nまさか白夜城の人たちには暗鬼を飼う趣味があるなんて言わないでくださいよ！？",
  ui_story_5051_50510402_21_dialog_content = "安心してください。\n意志疎通のできない敵対種族を飼って喜ぶほど、白夜城も腐ってはいませんから。",
  ui_story_5051_50510402_22_dialog_content = "「ソルラド家記念日」に暗鬼…なるほど、ここは12年前の白夜城というわけですね。",
  ui_story_5051_50510402_23_dialog_content = "大量の物資が行き来する機会を利用し、暗鬼を中に忍ばせるとは、\nこの混乱の首謀者はなかなか思い切ったことを考えるものですね。",
  ui_story_5051_50510402_24_dialog_content = "ってことは…12年前暗鬼が白夜城に侵入したってことですか？",
  ui_story_5051_50510402_25_dialog_content = "そうです。外の世界の人たちがあの壮大な浮空城をどう評価しているかは知りませんが――",
  ui_story_5051_50510402_26_dialog_content = "実際にはそこまで堅固でもないのです。",
  ui_story_5051_50510402_27_dialog_content = "あの、カレブさん…",
  ui_story_5051_50510402_28_dialog_content = "私に会う前にほかの人に会いました？",
  ui_story_5051_50510402_29_dialog_content = "いいえ。実を言うと、気が付いて少しもしないうちにあなたに出くわしました。",
  ui_story_5051_50510402_30_dialog_content = "ア、アハハ…普通なら転送後も一緒のはずなんですが…",
  ui_story_5051_50510402_31_dialog_content = "暗鬼に見つかることもないはずなんですよね…",
  ui_story_5051_50510402_32_dialog_content = "やっぱり、何か小さなミスがあったみたいです。",
  ui_story_5051_50510402_33_dialog_content = "…ジャキーニさん、1つお聞きしたいことがあります。",
  ui_story_5051_50510402_34_dialog_content = "コホン、心配いりませんって！\nちゃんと私が責任もって、みなさんを無傷で元の世界に帰しますから！",
  ui_story_5051_50510402_35_dialog_content = "僕が聞きたいのはそのことではありません。",
  ui_story_5051_50510402_36_dialog_content = "僕が聞きたいのは\n「記憶の鏡晶」を起動した者の光力はこの世界に保存されているのか、ということです。",
  ui_story_5051_50510402_37_dialog_content = "はい、その通りですよ！",
  ui_story_5051_50510402_38_dialog_content = "では、具体的にどこに保存されているのですか？",
  ui_story_5051_50510402_39_dialog_content = "ぐ、具体的に…どこか、ですか？ええと…",
  ui_story_5051_50510402_40_dialog_content = "「『記憶の鏡晶』を起動するには光力を注入しなければならない。\n光力はこの世界を動かす大事なエネルギー源である」",
  ui_story_5051_50510402_41_dialog_content = "<size=30>なんでこれしか書いてないんです！？</size>",
  ui_story_5051_50510402_42_dialog_content = "オ、オホン。光力が「記憶の鏡晶」の重要なエネルギー源なら、\nきっと最も重要な所に保存されてるはずですよ！",
  ui_story_5051_50510402_43_dialog_content = "「記憶の鏡晶」の中で最も重要なのはもちろん――",
  ui_story_5051_50510402_44_dialog_content = "この世界にある「記憶の鏡晶」です！",
  ui_story_5051_50510402_45_dialog_content = "確かに一理ありますね…",
  ui_story_5051_50510402_46_dialog_content = "もう1つ質問なのですが、光力をエネルギー源としているのなら、\n当然いつかはエネルギーが尽きる時がくるのですよね？",
  ui_story_5051_50510402_47_dialog_content = "12年の年月が経ち、今の「記憶の鏡晶」の光力はあとどれ程残っているのでしょう？",
  ui_story_5051_50510402_48_dialog_content = "あ、そのことは心配いりませんよ。",
  ui_story_5051_50510402_49_dialog_content = "鏡湖の水でさえ12年に1度の補充で大丈夫なんです。光力は当然もっと長持ちしますよ！",
  ui_story_5051_50510402_50_dialog_content = "ただ、もしこの世界の秩序が乱されるようなことがあれば、\n光力の消耗を速めることになるでしょうね。",
  ui_story_5051_50510402_51_dialog_content = "極端な場合、突然光力が尽きてしまうってことも有り得るんです。",
  ui_story_5051_50510402_52_dialog_content = "そうなれば、私たちの命も危ないですね。",
  ui_story_5051_50510402_53_dialog_content = "それが前に言っていた「想像を絶する大災難」ですか？",
  ui_story_5051_50510402_54_dialog_content = "ええ、そんなところです。もちろん予想外の状況だって考えられますけど…",
  ui_story_5051_50510402_55_dialog_content = "とにかく、一刻も早くほかのみなさんを探しましょう！",
  ui_story_5051_50510402_56_dialog_content = "姿を隠せていない状況で長居するのは危険です。",
  ui_story_5051_50510402_57_dialog_content = "その通りですね。\nでは、その任務はこの事態をまねいた張本人であるジャキーニさんにお任せします。",
  ui_story_5051_50510402_58_dialog_content = "僕は他にやることがあるので失礼します。",
  ui_story_5051_50510402_59_dialog_content = "ええっ！？私1人に押し付けて逃げるんですか！？",
  ui_story_5051_50510402_60_dialog_content = "それに今言ったでしょう？勝手に動き回っちゃダメですって！\n万が一中の世界を変えてしまったら大変です！",
  ui_story_5051_50510402_61_dialog_content = "分かっていますよ。決まりはきちんと守ります。\nあなたも他の皆さんを大人しくしているよう説得してくださいね。",
  ui_story_5051_50510402_62_dialog_content = "もともと残り少ない光力だというのに、過度に消耗してしまっては大変ですから。",
  ui_story_5051_50510402_63_dialog_content = "ちょっと！言っときますが、ここは白夜城ですよ。\n万が一過去の自分に会ったらどうするつもりです？",
  ui_story_5051_50510402_64_dialog_content = "安心してください。当時の今日私は騎士団に付いて影ノ街へ行った姪に\n会いに行っていましたから。城内にはいなかったのです。",
  ui_story_5051_50510402_65_dialog_content = "「記憶の鏡晶」といえども、そんな遠い所のことまで記録できないでしょう？",
  ui_story_5051_50510402_66_dialog_content = "確かにそうですけど…",
  ui_story_5051_50510402_67_dialog_content = "賓客と偽って城内に紛れ込み、会いたい人に会ったら、きちんと戻ってきます。",
  ui_story_5051_50510402_68_dialog_content = "命の危険を冒してでも、その人に会いたいんですか？",
  ui_story_5051_50510402_69_dialog_content = "もちろんです。普通なら過去に戻ることはできません。それがこうして\nやり直す機会に恵まれたのです。こんな機会もう二度とないかもしれませんから。",
  ui_story_5051_50510402_70_dialog_content = "どうか一刻も早く他の皆さんを見つけてくださいね。それでは。",
  ui_story_5051_50510402_71_dialog_content = "ちょっと待ってくださいって！まだどこで落ち合うか決めてませんよ！",
  ui_story_5051_50510402_72_dialog_content = "なんて足の速い…あっという間に姿が見えなくなってしまいました…",
  ui_story_5051_50510402_73_dialog_content = "まったく…ちょっと前まであの人、上品で礼儀正しかったたのに…見せかけだったんですね！",
  ui_story_5051_50510402_74_dialog_content = "肝心な時に自分勝手で無情なふるまいをするなんて、とんでもないヤツです！",
  ui_story_5051_50510402_75_dialog_content = "あ～あ、腹が立つ！",
  ui_story_5051_50510402_76_dialog_content = "はぁ…「やり直す機会」ですか…",
  ui_story_5051_50510402_77_dialog_content = "私にもそんな機会あるんでしょうか？",
  ui_story_5051_50510402_78_dialog_content = "ママは12年前「記憶の鏡晶」を白夜城の城主様に渡すと、北境に戻ってきました。",
  ui_story_5051_50510402_79_dialog_content = "パパはママのことを理解しがたい人だって言ってました。\n修行のためなら家族を放ったまま、一言も告げずに山にこもってしまう…",
  ui_story_5051_50510402_80_dialog_content = "でも、陛下はママのことを世俗離れした偉大な修行者とおっしゃいました…\nどうやら私…ママとちっとも似てないみたいですね。",
  ui_story_5051_50510402_81_dialog_content = "もし今ママがここにいたら、私になんて言葉をかけてくれるんでしょう？",
  ui_story_5051_50510402_82_dialog_content = "…もうっ！私ったら何を考えてるんです！？",
  ui_story_5051_50510402_83_dialog_content = "ジャキーニ、集中するんです！あなたは今北境の使者なんですよ！",
  ui_story_5051_50510402_84_dialog_content = "ほかの人たちが頼りなくても、自分は頼りがいのある存在じゃなきゃいけません。\n絶対に責任をもってみなさんを連れ出します！",
  ui_story_5051_50510402_85_dialog_content = "…すーっ…ふぅ…",
  ui_story_5051_50510402_86_dialog_content = "よ～しっ！北境の使者ジャキーニ、出発！",
  ui_story_5051_50510501_1_dialog_content = "（ソルラドの奴が「記憶の鏡晶」を隠せる場所は多くないはず…\nおそらくこの屋敷のどこかでしょう）",
  ui_story_5051_50510501_2_dialog_content = "（あの年の「記念日」は大規模に催されたので、\n守衛のほとんどが会場の警備に回されていたはず…）",
  ui_story_5051_50510501_3_dialog_content = "（祝典が始まりさえすれば、警備の薄い所から入り込めるはずです）",
  ui_story_5051_50510501_4_dialog_content = "（それまでは守衛の視界に入らないように、大人しく待っていることにしましょう）",
  ui_story_5051_50510501_5_dialog_content = "（確か庭園の方には人がいなかったはずですよね…）",
  ui_story_5051_50510501_6_dialog_content = "（アヤメの花言葉は…「朗報」、「思い」）",
  ui_story_5051_50510501_7_dialog_content = "（姉さんは確か上の娘のためにアヤメを植えたんでしたね）",
  ui_story_5051_50510501_8_dialog_content = "…分かっているわ。もうすぐ花の時期が過ぎてしまうのよね。",
  ui_story_5051_50510501_9_dialog_content = "でも、もう少し頑張ってくれないかしら？",
  ui_story_5051_50510501_10_dialog_content = "娘がもうすぐ帰ってくるの。あなたたちの姿を見せてあげたいのよ。",
  ui_story_5051_50510501_11_dialog_content = "あの子は昔からお花が大好きだったのよ。\nあなたたちを見たらきっと、また笑顔を取り戻してくれるわ。",
  ui_story_5051_50510501_12_dialog_content = "あ、あなたは…",
  ui_story_5051_50510501_13_dialog_content = "<color=#FFB400>姉さん</color>…？",
  ui_story_5051_50510501_14_dialog_content = "あら。",
  ui_story_5051_50510501_15_dialog_content = "ごきげんよう、見知らぬお方。",
  ui_story_5051_50510501_16_dialog_content = "こんな美しい午後にお1人でどうかされたの？",
  ui_story_5051_50510501_17_dialog_content = "うーん…ごめんなさい、唐突だけど1つ聞いてもいいかしら？",
  ui_story_5051_50510501_18_dialog_content = "前にお会いしたことある？",
  ui_story_5051_50510501_19_dialog_content = "…いいえ、私はしがない貴族です。そのような光栄を賜ったことはありません。",
  ui_story_5051_50510501_20_dialog_content = "初めてお目にかかります、ヨシュア夫人。",
  ui_story_5051_50510501_21_dialog_content = "そう？",
  ui_story_5051_50510501_22_dialog_content = "でも何だか…よしましょう。きっとわたくしの勘違いね。",
  ui_story_5051_50510501_23_dialog_content = "（姉さん…）",
  ui_story_5051_50510501_24_dialog_content = "（会いたい人がいると言ったのは、\n北境の占い師さんを振り切るためのウソだったのですが…）",
  ui_story_5051_50510501_25_dialog_content = "（本当に会えるとは思っていませんでした）",
  ui_story_5051_50510501_26_dialog_content = "（12年…12年経って…ようやくまた姉さんと話せたというのに…）",
  ui_story_5051_50510501_27_dialog_content = "（こうして見知らぬ人のふりをしなければならないとは…）",
  ui_story_5051_50510501_28_dialog_content = "（僕がこの世界に来たのは、姉さんが残した光力を取り戻すため…）",
  ui_story_5051_50510501_29_dialog_content = "（干渉してはいけない、留まってはいけない…\nこれは北境の秘術が創り出した幻影にすぎないのですから）",
  ui_story_5051_50510501_30_dialog_content = "（さっさとお芝居を終わらせましょう…！）",
  ui_story_5051_50510501_31_dialog_content = "大丈夫？何だかつらそうなご様子だけど…",
  ui_story_5051_50510501_32_dialog_content = "申し訳ございません。",
  ui_story_5051_50510501_33_dialog_content = "あなたのような高貴な方とお話するのは初めてだったもので、\n少し気が動転してしまいました。",
  ui_story_5051_50510501_34_dialog_content = "ふふ、嘘ばっかり。",
  ui_story_5051_50510501_35_dialog_content = "目が潤んでいるわ。ケガでもしたのかしら？それとも悩み事かしら？",
  ui_story_5051_50510501_36_dialog_content = "強がらなくていいのよ。",
  ui_story_5051_50510501_37_dialog_content = "…",
  ui_story_5051_50510501_38_dialog_content = "そ、そんなことありません！",
  ui_story_5051_50510501_39_dialog_content = "目にゴミが入っただけです！",
  ui_story_5051_50510501_40_dialog_content = "…学院の石頭たちや寝ぼけた学生たちに何が分かるって言うんです！",
  ui_story_5051_50510501_41_dialog_content = "「カレブは賢いが、両親の教育が行き届いておらず、\nいつも傲慢な態度をとっている」なんて…",
  ui_story_5051_50510501_42_dialog_content = "<size=30>両親がいないのが何だっていうんです？\n僕には姉さんがいれば十分です…</size>",
  ui_story_5051_50510501_43_dialog_content = "今に見ていてください！いつか必ず僕がこの世のすべてを変えてみせます！",
  ui_story_5051_50510501_44_dialog_content = "ええ、あなたを信じてるわ。",
  ui_story_5051_50510501_45_dialog_content = "わたくしのかわいい天才君は嘘なんてつかないもの。\n言ったことは必ずやり遂げてくれるのよね。",
  ui_story_5051_50510501_46_dialog_content = "姉さん、本当に信じてくれるんですか？",
  ui_story_5051_50510501_47_dialog_content = "ええ、もちろんよ。",
  ui_story_5051_50510501_48_dialog_content = "姉さん…いつの日か人々が食べ物に困らず、危険におびえることもなくなったら――",
  ui_story_5051_50510501_49_dialog_content = "姉さんも毎日ダニエルとかいう奴の補佐をしなくて済むようになるんですか？",
  ui_story_5051_50510501_50_dialog_content = "そうね。そんな日が来たら、きっと政務も減るわね。\nでもわたくしは妻としてダニエルのそばにいるわ。",
  ui_story_5051_50510501_51_dialog_content = "…",
  ui_story_5051_50510501_52_dialog_content = "ただ、その時にはあなたの研究にも付き合ってあげるわ。\n学会には必ず出席してあげる。それでいい？",
  ui_story_5051_50510501_53_dialog_content = "本当ですか？",
  ui_story_5051_50510501_54_dialog_content = "ええ、本当よ。",
  ui_story_5051_50510501_55_dialog_content = "だったら…僕は世界じゅうの学術発表会に出ます！",
  ui_story_5051_50510501_56_dialog_content = "姉さんは昔世界じゅうを旅行したいって言ってましたよね。\nでも結婚してからはそんなこと言わなくなりました。",
  ui_story_5051_50510501_57_dialog_content = "だったら僕がその夢を実現してあげます。",
  ui_story_5051_50510501_58_dialog_content = "あら、あなたって子はもう…また姉さんをうまく乗せたのね？",
  ui_story_5051_50510501_59_dialog_content = "でも、もう約束してくれましたよ。必ず来てくださいね！",
  ui_story_5051_50510501_60_dialog_content = "分かったわ。約束よ。",
  ui_story_5051_50510501_61_dialog_content = "…目に、ゴミが…入っただけです。",
  ui_story_5051_50510501_62_dialog_content = "あらあら、顔をしかめちゃって、明らかに辛いのを我慢しているのでしょう？",
  ui_story_5051_50510501_63_dialog_content = "弟にそっくり…",
  ui_story_5051_50510501_64_dialog_content = "わたくしの弟は年齢をはるかに超える頭脳をもっているのに、\nそれ以外のことでは、いつまでも子どもみたいなの。",
  ui_story_5051_50510501_65_dialog_content = "いつも「目にゴミが入った」なんていう明らかな嘘で、\n泣いているのをごまかしたりするのよ。",
  ui_story_5051_50510501_66_dialog_content = "…あら、ごめんなさい。",
  ui_story_5051_50510501_67_dialog_content = "弟に似ていたものだから、つい親しげに話してしまったわ。",
  ui_story_5051_50510501_68_dialog_content = "失礼を許してね。",
  ui_story_5051_50510501_69_dialog_content = "いえ、そんな滅相もない…",
  ui_story_5051_50510501_70_dialog_content = "でも、本当に不思議ね。あなたと弟ではずいぶん年が離れているのに…",
  ui_story_5051_50510501_71_dialog_content = "あの子の面影が浮かんでくるわ…",
  ui_story_5051_50510501_72_dialog_content = "お詫びに今日のパーティーの貴賓席を用意させて。",
  ui_story_5051_50510501_73_dialog_content = "何か不便でもあれば、わたくしの名前を言ってくれればいいわ。",
  ui_story_5051_50510501_74_dialog_content = "困ったことがあれば、何でも言ってね。",
  ui_story_5051_50510501_75_dialog_content = "独りで抱え込んではダメよ。",
  ui_story_5051_50510501_76_dialog_content = "ご厚意痛み入ります。ですが、私は用事の途中通りかかったにすぎません。\n祝典に参加しにきたわけではございません。",
  ui_story_5051_50510501_77_dialog_content = "この花を見ていたら懐かしくなり、つい足を止めて見入ってしまったのです。\nお邪魔して申し訳ございませんでした。",
  ui_story_5051_50510501_78_dialog_content = "では、私はこれで…どうぞお体をお大事に。",
  ui_story_5051_50510501_79_dialog_content = "あら、そんなに急がなくても…",
  ui_story_5051_50510501_80_dialog_content = "お名前だけでもお聞きしたかったのに。",
  ui_story_5051_50510501_81_dialog_content = "皆、僕の知っている様子とは違うけど…",
  ui_story_5051_50510501_82_dialog_content = "白夜城だけは今とまったく変わらないね。",
  ui_story_5051_50510501_83_dialog_content = "そうね。この神聖かつ堅固な城壁は白夜城の象徴であり、人々の信仰の証でもあるの。",
  ui_story_5051_50510501_84_dialog_content = "だから、長い間みんな白夜城の純潔を守るため、いかなる代償も惜しまなかった…\nすべての犠牲に価値があったのね。",
  ui_story_5051_50510501_85_dialog_content = "入城許可証をお見せください。ちょっと、そこのあなたですよ。",
  ui_story_5051_50510501_86_dialog_content = "え、僕…？",
  ui_story_5051_50510501_87_dialog_content = "あ、彼は私の友人よ。",
  ui_story_5051_50510501_88_dialog_content = "ヴェ、ヴェロニカ殿下！",
  ui_story_5051_50510501_89_dialog_content = "どうぞお入りください。先程の失礼をどうかお許しください！",
  ui_story_5051_50510501_90_dialog_content = "構わないわ。祝日だというのにお仕事ご苦労様…引き続き励んでください。",
  ui_story_5051_50510501_91_dialog_content = "はっ！仰せのままに！",
  ui_story_5051_50510501_92_dialog_content = "はぁ…よかった。お姫様って便利だね。",
  ui_story_5051_50510501_93_dialog_content = "前に門衛に呼び止められた時も、カレンのおかげで助かったんだっけ…",
  ui_story_5051_50510501_94_dialog_content = "PlayerNameはいい人だから、みんな喜んで手助けするのよ。",
  ui_story_5051_50510501_95_dialog_content = "そうなの？あはは、なんか照れちゃうな。",
  ui_story_5051_50510501_96_dialog_content = "あ、そうだ。ちょっと待って。",
  ui_story_5051_50510501_97_dialog_content = "あの…「威厳ある白髪の独眼の男性」か、「金髪に紫の目をした貴族の青年」…",
  ui_story_5051_50510501_98_dialog_content = "あるいは「赤い髪の北境の占い師」が今日白夜城に来ませんでしたか？",
  ui_story_5051_50510501_99_dialog_content = "初めのお2人は見かけませんでしたが…",
  ui_story_5051_50510501_100_dialog_content = "昨日謁見に来られた北境の使者は今おっしゃったような方でした。",
  ui_story_5051_50510501_101_dialog_content = "（昨日謁見に来た北境の使者ってことは…たぶん前任の使者だね）",
  ui_story_5051_50510501_102_dialog_content = "分かりました。ありがとうございます。",
  ui_story_5051_50510501_103_dialog_content = "PlayerName、どうかしたの？",
  ui_story_5051_50510501_104_dialog_content = "門衛さんが皆のことを見かけたか聞きたかったんだけど、見てないみたいだった。",
  ui_story_5051_50510501_105_dialog_content = "やっぱり僕たちで探すしかなさそうだね。",
  ui_story_5051_50510501_106_dialog_content = "――！！",
  ui_story_5051_50510501_107_dialog_content = "暗鬼！なぜ荷物の中に暗鬼がいるんだ！？",
  ui_story_5051_50510501_108_dialog_content = "こっちにもいるよ！？",
  ui_story_5051_50510501_109_dialog_content = "だ、大丈夫、私が倒すわ…！",
  ui_story_5051_50510502_1_dialog_content = "何があったのですか！？",
  ui_story_5051_50510502_2_dialog_content = "<color=#FFB400>マイム</color>騎士団長、ご報告いたします！\n先程、荷物の中に紛れ込んだ暗鬼に隊が突然襲われました。",
  ui_story_5051_50510502_3_dialog_content = "荷物を輸送してきた商人はすでに我々が押さえています。死傷者は出ておりません。",
  ui_story_5051_50510502_4_dialog_content = "「記念日」の祝典が行われる日になぜこのような事件がおこったのですか。",
  ui_story_5051_50510502_5_dialog_content = "容疑者は私に引き渡してください。\n重大な罪を犯したからには、私自ら法廷に押送しましょう。",
  ui_story_5051_50510502_6_dialog_content = "はっ！仰せのままに！",
  ui_story_5051_50510502_7_dialog_content = "ところで暗鬼はどうしたのです？あなたたちが倒したのですか？",
  ui_story_5051_50510502_8_dialog_content = "1匹残らず倒しました。",
  ui_story_5051_50510502_9_dialog_content = "すべてヴェロニカ殿下のおかげです！",
  ui_story_5051_50510502_10_dialog_content = "お姫様は本当にお強い！",
  ui_story_5051_50510502_11_dialog_content = "白夜城の勇敢でお強いお姫様といえば…まさかカレン殿下ですか？",
  ui_story_5051_50510502_12_dialog_content = "いやいや、あれはヴェロニカ殿下だ。",
  ui_story_5051_50510502_13_dialog_content = "まさかヴェロニカ殿下までこんなにお強いとは…ソルラド家はまさに人材の宝庫ですね…",
  ui_story_5051_50510502_14_dialog_content = "<size=30>ううっ、PlayerName。みんなが私を見てるわ。\nなんだかヘンな気分よ…</size>",
  ui_story_5051_50510502_15_dialog_content = "さっきのミヤの戦いぶりがすばらしかったからだよ！",
  ui_story_5051_50510502_16_dialog_content = "暗鬼を全部あっという間に倒した姿は百戦錬磨の戦士みたいだった。",
  ui_story_5051_50510502_17_dialog_content = "私の戦いぶりが…素晴らしかった？",
  ui_story_5051_50510502_18_dialog_content = "もちろん、そうだよ！",
  ui_story_5051_50510502_19_dialog_content = "あ、そ、そう…ありがとう…",
  ui_story_5051_50510502_20_dialog_content = "容疑者は私たちが処理する。ご苦労だった。",
  ui_story_5051_50510502_21_dialog_content = "承知いたしました。よろしくお願いします。",
  ui_story_5051_50510502_22_dialog_content = "（今のは…）",
  ui_story_5051_50510502_23_dialog_content = "（<color=#FFB400>キシローナさん</color>！？）",
  ui_story_5051_50510502_24_dialog_content = "何者だ！？なぜ私を見る？",
  ui_story_5051_50510502_25_dialog_content = "何か頼み事でもあるのなら言うがいい。\n騎士予備兵相手でも、私は必ず誓いを守り、力を尽くして助けてやる。",
  ui_story_5051_50510502_26_dialog_content = "だが、何も用がないのならば、大人しく自身のやるべきことに集中せよ。",
  ui_story_5051_50510502_27_dialog_content = "（大変だ、見つかっちゃった！何とかしてごまかして接触を避けなきゃ！）",
  ui_story_5051_50510502_28_dialog_content = "（でも…12年前キシローナさんってまだ14歳だよね？\n若い時から、こんな風に厳しかったんだ…）",
  ui_story_5051_50510502_29_dialog_content = "すみませんでした、何でもありません。ただちょっと縁を感じて。",
  ui_story_5051_50510502_30_dialog_content = "縁だと？訳の分からないことを言うな。",
  ui_story_5051_50510502_31_dialog_content = "そういう古臭い陳腐な言葉はその辺の子どもをあやすのに使うといい。",
  ui_story_5051_50510502_32_dialog_content = "あははは…邪魔してすみませんでした。",
  ui_story_5051_50510502_33_dialog_content = "本当に縁があるのなら、また会うこともあるだろう。",
  ui_story_5051_50510502_34_dialog_content = "天にでも祈っておけ。",
  ui_story_5051_50510502_35_dialog_content = "祈る必要はありませんよ。必ず再会しますから！",
  ui_story_5051_50510502_36_dialog_content = "（だって、将来僕たちは仲間になるんだから）",
  ui_story_5051_50510502_37_dialog_content = "なんと口のうまい…",
  ui_story_5051_50510502_38_dialog_content = "おい、見たか。キシローナが巡回中におしゃべりしてるぞ！",
  ui_story_5051_50510502_39_dialog_content = "あいつだってまだ子どもなんだ。遊びたい年頃だ。",
  ui_story_5051_50510502_40_dialog_content = "その通りだ。普段の大人びた様子は見てるこっちが辛くなる。",
  ui_story_5051_50510502_41_dialog_content = "はぁ…パレードか…見に行きたいもんだな…",
  ui_story_5051_50510502_42_dialog_content = "<size=45>そこの騎士ども！</size>",
  ui_story_5051_50510502_43_dialog_content = "今日は白夜城を挙げて祝いが催される日だ。\n我がカルティマ家は光栄にも民の安全を守るという重責を任された。",
  ui_story_5051_50510502_44_dialog_content = "厳粛に任に当たり、その使命に恥じることなく務めを果たせ。",
  ui_story_5051_50510502_45_dialog_content = "…",
  ui_story_5051_50510502_46_dialog_content = "（あははは…キシローナさん、昔からずっと変わらないんだなぁ）",
  ui_story_5051_50510502_47_dialog_content = "あの…PlayerName。マイムさんがお母様のいる宮殿へ連れて行ってくれるって。",
  ui_story_5051_50510502_48_dialog_content = "女の子とのおしゃべりは…それくらいにして、行きましょう。",
  ui_story_5051_50510502_49_dialog_content = "（あ、祝日の雰囲気にのまれて、僕までちょっと浮ついてたみたいだ…）",
  ui_story_5051_50510502_50_dialog_content = "（僕たちは今危険な状況にいるんだよね。気を緩めちゃいけない）",
  ui_story_5051_50510502_51_dialog_content = "ごめん、僕がうかつだったよ。これからは簡単に人と話さないよ。",
  ui_story_5051_50510502_52_dialog_content = "そういうことじゃないの…ううん、この気持ち、なんて言ったらいいのかしら？",
  ui_story_5051_50510502_53_dialog_content = "胸が苦しくて、痛いの。",
  ui_story_5051_50510502_54_dialog_content = "どうしたの？うーん…感知能力が使えればいいんだけどな。",
  ui_story_5051_50510502_55_dialog_content = "そうすれば、君の心の中を感知できるのに…",
  ui_story_5051_50510502_56_dialog_content = "そ、その必要はないわ！私の心の中はのぞかないで…",
  ui_story_5051_50510502_57_dialog_content = "PlayerNameって普段は賢いのに、時どきすごく鈍いのね。",
  ui_story_5051_50510502_58_dialog_content = "そ、それは良かった。あ、そうだ！\n騎士団の人に頼みたいことがあったんだ。ちょっと待ってて！",
  ui_story_5051_50510502_59_dialog_content = "え？PlayerName？",
  ui_story_5051_50510502_60_dialog_content = "こんにちは。マイムさんですよね？",
  ui_story_5051_50510502_61_dialog_content = "はい。何か御用ですか？",
  ui_story_5051_50510502_62_dialog_content = "友人3人と途中ではぐれてしまったんですが、全員ヴェロニカ殿下の客人なんです。",
  ui_story_5051_50510502_63_dialog_content = "できたら、今から言う特徴の3人を探してもらえませんか…？",
  ui_story_5051_50510502_64_dialog_content = "では、これから私は城主様に謁見しなければならないので、ここで失礼します。",
  ui_story_5051_50510502_65_dialog_content = "ありがとう、マイムさん。",
  ui_story_5051_50510502_66_dialog_content = "あの…後でお父様に会ったら、私と友人のことには触れないでいてくれますか…？",
  ui_story_5051_50510502_67_dialog_content = "ただ「触れない」だけでよければ、殿下の顔を立て、そういたしましょう。",
  ui_story_5051_50510502_68_dialog_content = "今日は私の騎士団が警備巡回を担当します。\n殿下とご友人の方も私を困らせるようなことはなさらないようお願いいたします。",
  ui_story_5051_50510502_69_dialog_content = "わかりました。決してご迷惑はかけません。",
  ui_story_5051_50510502_70_dialog_content = "ミヤ、話は終わった？",
  ui_story_5051_50510502_71_dialog_content = "ええ、マイムさんにお父様の前では私たちのことに触れないようお願いしたわ。",
  ui_story_5051_50510502_72_dialog_content = "何しろ私はこの年の今日、とても身勝手な事をしたの。\nお父様に会えば、きっとお怒りになるわ…",
  ui_story_5051_50510502_73_dialog_content = "ヴェロニカ？",
  ui_story_5051_50510502_74_dialog_content = "お母様…？",
  ui_story_5051_50510502_75_dialog_content = "お母様！",
  ui_story_5051_50510502_76_dialog_content = "あらあら、ヴェロニカったらどうしたの？",
  ui_story_5051_50510502_77_dialog_content = "お母様…本当にお母様なの…？ずっと…会いたかった…",
  ui_story_5051_50510502_78_dialog_content = "いい子ね。わたくしはここにいるわよ。",
  ui_story_5051_50510502_79_dialog_content = "さあ、顔をみせてちょうだい。騎士団でケガでもしたのかしら？",
  ui_story_5051_50510502_80_dialog_content = "それとも、お友だちとケンカしたの？",
  ui_story_5051_50510502_81_dialog_content = "（え！？僕の方を見てる…！？ち、ちちち、違うよ。\n僕じゃない！ミヤのお母さん、誤解しないで！）",
  ui_story_5051_50510502_82_dialog_content = "お母様、PlayerNameがここまで連れてきてくれたの…",
  ui_story_5051_50510502_83_dialog_content = "そうだったの。いいお友だちができたのね。",
  ui_story_5051_50510502_84_dialog_content = "まあ、その膝はどうしたの？関節の所にある痕はいったい…",
  ui_story_5051_50510502_85_dialog_content = "大丈夫よ、お母様。私は大丈夫…",
  ui_story_5051_50510502_86_dialog_content = "私はもう、勇敢になったから。",
  ui_story_5051_50510502_87_dialog_content = "だから、大丈夫よ…！",
  ui_story_5051_50510502_88_dialog_content = "そうかしら？そんな泣き顔で言ったって、説得力ないわよ。",
  ui_story_5051_50510502_89_dialog_content = "さあ、顔を洗いに行くのよ。ゆっくり座って話しましょう。",
  ui_story_5051_50510601_1_dialog_content = "（2人とも中に入っていった…）",
  ui_story_5051_50510601_2_dialog_content = "（立ち去る時、ミヤのお母さんが笑いかけてきたけど、\nたぶんここで待ってろってことだよね）",
  ui_story_5051_50510601_3_dialog_content = "（「レディの身支度をのぞいてはいけない」ってよく言うよね。\nひとまず僕は外してよう）",
  ui_story_5051_50510601_4_dialog_content = "（ここに来るまでに会ったイスタバンさんも、キシローナさんも、ミヤのお母さんも…）",
  ui_story_5051_50510601_5_dialog_content = "（みんな本物みたいに普通に会話できた）",
  ui_story_5051_50510601_6_dialog_content = "（「記憶の鏡晶」って本当にすごいな…）",
  ui_story_5051_50510601_7_dialog_content = "（でも、その用途からいうと、僕たちはここの人たちと交流しちゃいけないんだよね）",
  ui_story_5051_50510601_8_dialog_content = "（こんな風に接触してたら、きっと「記憶の鏡晶」に負荷をかけちゃう）",
  ui_story_5051_50510601_9_dialog_content = "（ああ、今のこの状況…良し悪しの判断が難しいな。\n早くジャキーニたちを見つけられればいいんだけど…）",
  ui_story_5051_50510601_10_dialog_content = "そこのあなた。",
  ui_story_5051_50510601_11_dialog_content = "ここはソルラド家の私有地よ。",
  ui_story_5051_50510601_12_dialog_content = "さっきから怪しい動きをしているわね。どうやって入ってきたの？",
  ui_story_5051_50510601_13_dialog_content = "え？誰が僕に話しかけてるの？",
  ui_story_5051_50510601_14_dialog_content = "なんて無礼なの！カレンはここにいるじゃない！",
  ui_story_5051_50510601_15_dialog_content = "<size=45>カレン！？</size>",
  ui_story_5051_50510601_16_dialog_content = "私を呼び捨てにするの？",
  ui_story_5051_50510601_17_dialog_content = "貴族の傲慢な態度は私も嫌いだけど、\nここでカレンを軽視することは「ソルラド」を軽視するも同然なの。",
  ui_story_5051_50510601_18_dialog_content = "「ソルラド家記念日」に我が家の敷地内に入り込み…",
  ui_story_5051_50510601_19_dialog_content = "かつ不遜な言動で、ソルラドの名を汚せば、どうなるか分かっているでしょ？",
  ui_story_5051_50510601_20_dialog_content = "待って！すぐに反応できなかっただけなんだ！",
  ui_story_5051_50510601_21_dialog_content = "カレン殿下、まずは話を聞いて！",
  ui_story_5051_50510601_22_dialog_content = "だ～れだ？",
  ui_story_5051_50510601_23_dialog_content = "<size=45>わあ！？</size>",
  ui_story_5051_50510601_24_dialog_content = "な、何をするの！？",
  ui_story_5051_50510601_25_dialog_content = "卑怯だわ！仲間を連れて来ていたの！？",
  ui_story_5051_50510601_26_dialog_content = "えっ？ええと…",
  ui_story_5051_50510601_27_dialog_content = "そうよ、私たちは仲間なの。カレンを捕まえに来たのよ～！",
  ui_story_5051_50510601_28_dialog_content = "ひ、卑怯者！カレンのランスはどこ！？ううっ、放して！カレンのランスはどこなの！？",
  ui_story_5051_50510601_29_dialog_content = "…あ、待って。この声は…もしかしてお姉様？",
  ui_story_5051_50510601_30_dialog_content = "オホホホ～、ハズレ。ヴェロニカじゃないわ～。",
  ui_story_5051_50510601_31_dialog_content = "そんな声真似してもカレンはだまされないわ！カ、カレンはもう子どもじゃないもん！",
  ui_story_5051_50510601_32_dialog_content = "あら、本当～？",
  ui_story_5051_50510601_33_dialog_content = "ふふふ…カレンったらいつもは大人っぽくしているのに、\n目隠しされると途端に慌てちゃうのよね。",
  ui_story_5051_50510601_34_dialog_content = "お母様？お母様もいらっしゃるの？お母様！お姉様にカレンを放すように言って！",
  ui_story_5051_50510601_35_dialog_content = "ダメよ～。またお母様って呼んだわね～？ママって呼ばなければ助けてあげないわ。",
  ui_story_5051_50510601_36_dialog_content = "ひ、ひどいわ！",
  ui_story_5051_50510601_37_dialog_content = "お客様にいきなり強く当たったのはどこの誰かしら？",
  ui_story_5051_50510601_38_dialog_content = "初対面の人に強く当たるなんて、よくないわ。",
  ui_story_5051_50510601_39_dialog_content = "全部あなたのせいだったのね！卑怯者！どうやってお姉様とお母様を丸め込んだの！？",
  ui_story_5051_50510601_40_dialog_content = "違うよ、僕は何もしてないよ。",
  ui_story_5051_50510601_41_dialog_content = "ふふ、カレンったら、あとどれくらい頑張れるかしら？",
  ui_story_5051_50510601_42_dialog_content = "うう…カレン、もうきつく当たったりしない！だからお姉様、お母様、カレンを放して…",
  ui_story_5051_50510601_43_dialog_content = "ふふ、カレンとこんな風に遊ぶの久しぶりね。可笑しくてお腹が痛くなっちゃった…",
  ui_story_5051_50510601_44_dialog_content = "うう…お姉様ったらひどい…",
  ui_story_5051_50510601_45_dialog_content = "それでいいのよ。ヴェロニカはやっぱり笑っている時が一番かわいいわ。",
  ui_story_5051_50510601_46_dialog_content = "カレンは笑ってないわね…なら、くすぐっちゃおうかしら？",
  ui_story_5051_50510601_47_dialog_content = "だ、大丈夫よ！",
  ui_story_5051_50510601_48_dialog_content = "家族ってやっぱりいいわ。ダニエルも一緒なら、もっといいのだけれど…",
  ui_story_5051_50510601_49_dialog_content = "ごめんなさいね、変な所見せてしまって。",
  ui_story_5051_50510601_50_dialog_content = "ヴェロニカから聞いたわ。\nPlayerNameとおっしゃるのね。わたくしもそう呼んでいいかしら？",
  ui_story_5051_50510601_51_dialog_content = "もちろんです。どんな呼び方でも構いません。",
  ui_story_5051_50510601_52_dialog_content = "あなたがヴェロニカのことを「ミヤ」と呼ぶみたいに？",
  ui_story_5051_50510601_53_dialog_content = "え？それは…",
  ui_story_5051_50510601_54_dialog_content = "（ミヤと話してたの聞こえてたんだ！）",
  ui_story_5051_50510601_X54_dialog_content = "お母様、あの…実は…\nPlayerNameは影ノ街で出来た友だちなの。PlayerNameは…",
  ui_story_5051_50510601_56_dialog_content = "ふふ、いいのよ。私も若い頃はよく偽名を使って遊んでいたわ。",
  ui_story_5051_50510601_57_dialog_content = "誰にだって善意の嘘くらい、つくものよね。分かっているわ。",
  ui_story_5051_50510601_58_dialog_content = "お母様…ありがとう。",
  ui_story_5051_50510601_59_dialog_content = "あら、そういうことだったの。\nどうやらこちらのお友だちは「ミヤ」の勇敢な騎士さんだったのね。",
  ui_story_5051_50510601_60_dialog_content = "彼さえいれば、お姫様は道に迷っても家に帰ってこられる、そういうことね？",
  ui_story_5051_50510601_61_dialog_content = "うう…お母様ったら…",
  ui_story_5051_50510601_62_dialog_content = "あなた、お姉様の護衛だったの？やせ細っているし、\n度胸もないようだけど、本当にお姉様を守れるの？",
  ui_story_5051_50510601_63_dialog_content = "カレン、違うわ。護衛ではなく、「白馬の王子」でしょ？",
  ui_story_5051_50510601_64_dialog_content = "わああああ！お、お母様！PlayerNameは影ノ街で知り合った、普通のお友だちよ！",
  ui_story_5051_50510601_65_dialog_content = "優しくて、辛抱強いの。だから、いつも色々助けてくれて…た、ただ、それだけよ…",
  ui_story_5051_50510601_66_dialog_content = "善意のウソ？カレンには分からないわ…",
  ui_story_5051_50510601_67_dialog_content = "卑怯な侵入者！早くウソを明かしなさい！",
  ui_story_5051_50510601_68_dialog_content = "あの…僕にはPlayerNameって名前があるんだけど…",
  ui_story_5051_50510601_69_dialog_content = "（カレン…僕の足を踏みつけてる…）",
  ui_story_5051_50510601_70_dialog_content = "（この頃のカレンも真面目で、実際の年よりも大人びてるけど、\n表情が豊かで活発な雰囲気だな）",
  ui_story_5051_50510601_71_dialog_content = "（お母さんが亡くなって、お姉さんも姿を消して…\nお父さんとの関係も…カレンもたくさん辛い経験をしたんだね）",
  ui_story_5051_50510601_72_dialog_content = "（そんな経験がなかったら、今のカレンももっと笑う女の子になってたのかな）",
  ui_story_5051_50510601_73_dialog_content = "（怒ると足を踏みつけたりしてたのかも…）",
  ui_story_5051_50510601_74_dialog_content = "どうしてじっと見るの？また足を踏みつけられたいの？",
  ui_story_5051_50510601_75_dialog_content = "いいえ、どうかお許しください、カレン様。",
  ui_story_5051_50510601_76_dialog_content = "ごめんなさい。カレンはいつも融通の利かないお堅い感じなの。\nでも、気持ちを表すのがヘタなだけで悪意はないのよ。",
  ui_story_5051_50510601_77_dialog_content = "ミヤ…いや、ヴェロニカ…家族のこと…全部思い出したの？",
  ui_story_5051_50510601_78_dialog_content = "ええ。お母様とカレンと一緒にいたら、記憶が全部突然息を吹き返すように戻ったの。",
  ui_story_5051_50510601_79_dialog_content = "私もカレンも、庭のブランコで遊ぶのが一番好きで…",
  ui_story_5051_50510601_80_dialog_content = "「私は誰？」も飽きずによく遊んでたわ…",
  ui_story_5051_50510601_81_dialog_content = "そんな記憶も、感情も、感じた幸せも…全部、本当だったのね…",
  ui_story_5051_50510601_82_dialog_content = "思い出せて、本当によかったね！",
  ui_story_5051_50510601_83_dialog_content = "（でも…ミヤはまったくお父さんのことに触れない…\nさっき応接室で会った時もなんか重苦しい空気だった）",
  ui_story_5051_50510601_84_dialog_content = "（もしかしてミヤもカレンと同じように、お父さんとの関係がよくないのかな？）",
  ui_story_5051_50510601_85_dialog_content = "遊ぶのに夢中なのもいいけど、のどは乾いていない？お腹は？ホールにお菓子があるわ。",
  ui_story_5051_50510601_86_dialog_content = "お姉様、行きましょ。一緒にお菓子を食べましょ。",
  ui_story_5051_50510601_87_dialog_content = "あ、そんな、引っ張らないで…",
  ui_story_5051_50510601_88_dialog_content = "PlayerName、あなたもぼんやりせずに一緒にどうぞ。",
  ui_story_5051_50510601_89_dialog_content = "いや、せっかくの家族水入らずですし…僕は遠慮しときます。",
  ui_story_5051_50510601_90_dialog_content = "あら、いいのよ。",
  ui_story_5051_50510601_91_dialog_content = "…あなたのその目、よく知っているわ。",
  ui_story_5051_50510601_92_dialog_content = "意志は強そうだけれど、迷子のような孤独感も浮かんでいる…",
  ui_story_5051_50510601_93_dialog_content = "影ノ街の暮らしで何か困ったことでもあったのかしら？",
  ui_story_5051_50510601_94_dialog_content = "いいえ！実は僕影ノ街の者じゃないんです。僕は…",
  ui_story_5051_50510601_95_dialog_content = "（ほ、本当のことはいえない。空の末裔は外と交流を持たない種族だし、\n外の人たちも僕たちの事はよく知らない）",
  ui_story_5051_50510601_96_dialog_content = "（「僕は空の末裔だ」なんて言ったら、きっと「記憶の鏡晶」に負担かけちゃう）",
  ui_story_5051_50510601_97_dialog_content = "僕は取るに足らない者です。",
  ui_story_5051_50510601_98_dialog_content = "家族もいないので、大好きな旅をしながらあちこちを回って、\nたくさん友だちができたんです。",
  ui_story_5051_50510601_99_dialog_content = "旅…わたくしも旅が好きよ。でも残念なことに、\nあちこち旅して回る機会には恵まれなかったわ。",
  ui_story_5051_50510601_100_dialog_content = "ねえ、今の暮らしは幸せ？",
  ui_story_5051_50510601_101_dialog_content = "はい、幸せです。",
  ui_story_5051_50510601_102_dialog_content = "それならよかったわ。",
  ui_story_5051_50510601_103_dialog_content = "あなたはヴェロニカのお友だちで、心のきれいないい子ね。",
  ui_story_5051_50510601_104_dialog_content = "ここにいる間はこの家を自分の家だと思ってちょうだい。",
  ui_story_5051_50510601_105_dialog_content = "城主夫人、ありがとうございます…",
  ui_story_5051_50510601_106_dialog_content = "わたくしの名前はヨシュア。好きなように呼んでちょうだい。",
  ui_story_5051_50510601_107_dialog_content = "は、ははは。ヨシュア夫人と呼ぶことにします。",
  ui_story_5051_50510601_108_dialog_content = "お姉様ったら、こっそり騎士団に付いて影ノ街の任務に行ってたの！？",
  ui_story_5051_50510601_109_dialog_content = "どんな任務？騎士団はどうやって戦うの？話してくださる？",
  ui_story_5051_50510601_110_dialog_content = "それは……",
  ui_story_5051_50510601_111_dialog_content = "そうだな、ヴェロニカ。余にも説明してもらおうか？",
  ui_story_5051_50510601_112_dialog_content = "<size=45>お、お父様！</size>",
  ui_story_5051_50510601_113_dialog_content = "お前に戦士としての武勇があるのなら、自ら願い出て戦場に出ようと反対はせぬ。",
  ui_story_5051_50510601_114_dialog_content = "だが、お前はまた目の前の戦いから逃げ、\nそれにも関わらず堂々と宮殿に逃げ込み、祝日を楽しんでおる。",
  ui_story_5051_50510601_115_dialog_content = "一族の記念日にこのような失態をさらし、どう収めるつもりか？",
  ui_story_5051_50510601_116_dialog_content = "…",
  ui_story_5051_50510601_117_dialog_content = "ダニエル、わたくしがヴェロニカを呼び戻したの。",
  ui_story_5051_50510601_118_dialog_content = "今日はソルラド家の家族がそろって過ごす日でしょう？ヴェロニカも一緒に祝うべきだわ。",
  ui_story_5051_50510601_119_dialog_content = "…ヨシュア、「ソルラド」は「一族」であり、「家族」ではない。",
  ui_story_5051_50510601_120_dialog_content = "ソルラド家には子を甘やかした先例はないのだ。むろん今後もあり得ぬ。",
  ui_story_5051_50510601_121_dialog_content = "ええ、その通りよ。わたくしたちは「一族」である前に「家族」だわ。",
  ui_story_5051_50510601_122_dialog_content = "最も身近な者の心もつかめずに、どうして一族をまとめられるの？",
  ui_story_5051_50510601_123_dialog_content = "（この人がソルラドさん…？）",
  ui_story_5051_50510601_124_dialog_content = "（漂う威厳は変わらないけど、今と全く違う…\nソルラドさん、ここ数年の間にずいぶん老けちゃったんだな…）",
  ui_story_5051_50510601_125_dialog_content = "（すごく気まずい空気だな…ミヤもひどい顔色だ…\nこんな時に限って感知能力が使えないなんて！）",
  ui_story_5051_50510601_126_dialog_content = "申し訳ございません、失礼いたします。",
  ui_story_5051_50510601_127_dialog_content = "（Ms.ブラン！さっきと同じ礼服を着てる…\n12年前もソルラドさんの助手をやってたのか）",
  ui_story_5051_50510601_128_dialog_content = "お主は何者か？",
  ui_story_5051_50510601_129_dialog_content = "ぼ、僕ですか？…ヴェロニカの友だちです…",
  ui_story_5051_50510601_130_dialog_content = "友だち？",
  ui_story_5051_50510601_131_dialog_content = "ダニエル。",
  ui_story_5051_50510601_132_dialog_content = "Ms.ロト、この者を賓客としてもてなすように。",
  ui_story_5051_50510601_133_dialog_content = "承知いたしました。",
  ui_story_5051_50510601_134_dialog_content = "殿下、元老院の皆様がお待ちです。",
  ui_story_5051_50510601_135_dialog_content = "ヨシュア、ヴェロニカを呼び戻したのはお主だ。責任をもって見ているのだぞ。",
  ui_story_5051_50510601_136_dialog_content = "ヴェロニカと友人が騒ぎを起こさぬようにな。",
  ui_story_5051_50510601_137_dialog_content = "分かったわ。きちんと見ているわ。",
  ui_story_5051_50510601_138_dialog_content = "だから、そんなにきつく当たらないでやって。",
  ui_story_5051_50510601_139_dialog_content = "…よかろう。",
  ui_story_5051_50510601_140_dialog_content = "パレードがまもなく始まる。子どもたちを連れて、急いで準備するがよい。",
  ui_story_5051_50510601_141_dialog_content = "はぁ…",
  ui_story_5051_50510601_142_dialog_content = "ヴェロニカ、大丈夫？",
  ui_story_5051_50510601_143_dialog_content = "お父様は今日とてもお忙しいの。あなたに腹を立てていたわけじゃないわ。",
  ui_story_5051_50510601_144_dialog_content = "わ…私は…",
  ui_story_5051_50510601_145_dialog_content = "さあ、いい子ね。怖がることないわ。",
  ui_story_5051_50510601_146_dialog_content = "お姉様…",
  ui_story_5051_50510601_147_dialog_content = "城主夫人、パレードまでまだお時間がございます。\nご家族とゆっくりお話なさっていてください。準備は私に任せていただければ結構です。",
  ui_story_5051_50510601_148_dialog_content = "ありがとう、Ms.ロト。",
  ui_story_5051_50510601_149_dialog_content = "いいえ、当然のことをしているまでです。",
  ui_story_5051_50510601_150_dialog_content = "あなたはお手数ですが、私と一緒にパレードの流れの確認と準備をしてください。",
  ui_story_5051_50510601_151_dialog_content = "ご安心ください。夫人は人をなだめるのが得意でいらっしゃいますから、\nご心配には及びません。",
  ui_story_5051_50510601_152_dialog_content = "分かりました…じゃあ、お願いします、Ms.ブラン。",
  ui_story_5051_50510601_153_dialog_content = "Ms.ブラン？あら、ここでそのように呼ばれるとは思いませんでした。",
  ui_story_5051_50510601_154_dialog_content = "それに、どうしてその名をご存じなのですか？",
  ui_story_5051_50510601_155_dialog_content = "（Ms.ブランって12年前はこの名前じゃなかったの？）",
  ui_story_5051_50510601_156_dialog_content = "（そういえば今日現実でもソルラドさんがMs.ブランのこと\n「Ms.ロト」って呼んでたな）",
  ui_story_5051_50510601_157_dialog_content = "（…ってことは、ソルラドさんの助手をする時は「Ms.ロト」って名前を使ってるんだ。\nどうやってごまかそう…？）",
  ui_story_5051_50510601_158_dialog_content = "そうお困りになることはありません。私に秘密があるように、\nあなたにも秘密があるのはごく自然なことです。",
  ui_story_5051_50510601_159_dialog_content = "城主様が直々にあなたをもてなすよう私に申し付けたのです。\n今日一日素晴らしい時間を過ごしていただくのが私の務めです。",
  ui_story_5051_50510601_160_dialog_content = "ただ、仕事をやりやすくするために、「Ms.ロト」と呼んでくださいませんか？",
  ui_story_5051_50510601_161_dialog_content = "分かりました、「Ms.ロト」。ご迷惑は掛けません。",
  ui_story_5051_50510601_162_dialog_content = "ご協力に感謝いたします。それでは、こちらへ。",
  ui_story_5051_50510701_1_dialog_content = "インヴェニレエウム～、インヴェニレエウム～、インヴェニレエウム。",
  ui_story_5051_50510701_2_dialog_content = "どうか教えてください。私の思う人は今どこにいるんですか？",
  ui_story_5051_50510701_3_dialog_content = "<size=45>アブラハダブラ！</size>",
  ui_story_5051_50510701_4_dialog_content = "おおおっ…！正面のこっちですか！",
  ui_story_5051_50510701_5_dialog_content = "また別の騎士団が影ノ街に派遣されるって聞いたぞ。",
  ui_story_5051_50510701_6_dialog_content = "ああ？影ノ街に何しに行くんだ？",
  ui_story_5051_50510701_7_dialog_content = "暗鬼の侵入に立ち向かうんだろ？影ノ街も白夜城の防衛線の一つだからな。",
  ui_story_5051_50510701_8_dialog_content = "だったら、どうして俺たちじゃないんだ？",
  ui_story_5051_50510701_9_dialog_content = "なにバカなことを言ってる！？俺たちは<color=#FFB400>カルティマ</color>家の騎士団だぞ。\nあんなみすぼらしい街に行って、どうするんだ！？",
  ui_story_5051_50510701_10_dialog_content = "シーッ！声が大きい！キシローナにまたサボってるとこ見つかったら大変だろ。",
  ui_story_5051_50510701_11_dialog_content = "やっぱカルティマ家はいいな。城主と肩を並べるくらいの発言権があるんだからな。",
  ui_story_5051_50510701_12_dialog_content = "そういうことだったのか…",
  ui_story_5051_50510701_13_dialog_content = "そういうことでしたか…",
  ui_story_5051_50510701_14_dialog_content = "おい！誰だ、お前！？",
  ui_story_5051_50510701_15_dialog_content = "不審者だ、捕まえろ！",
  ui_story_5051_50510701_16_dialog_content = "すみません、道を間違えたみたいです。さようなら～。",
  ui_story_5051_50510701_17_dialog_content = "アブラハダブラ！",
  ui_story_5051_50510701_18_dialog_content = "今度はどこでしょう？",
  ui_story_5051_50510701_19_dialog_content = "今学期も成績一位はまたイルンティか…",
  ui_story_5051_50510701_20_dialog_content = "イルンティ先輩はきれいなだけじゃなく、頭も良くて、\n黎明学院の先生方の前でも堂々としてるわ。",
  ui_story_5051_50510701_21_dialog_content = "憧れちゃう。",
  ui_story_5051_50510701_22_dialog_content = "はぁ…もしかしたら飛び級でそのまま卒業するかもな。",
  ui_story_5051_50510701_23_dialog_content = "完璧すぎる人って、本当にいるんだな。",
  ui_story_5051_50510701_24_dialog_content = "イルンティ？誰のことでしょう？",
  ui_story_5051_50510701_25_dialog_content = "あの変わった異族の格好をした少女は誰かしら？赤毛がきれいね。",
  ui_story_5051_50510701_26_dialog_content = "なんという格好をしてるんだ…恥さらしにも程がある！法廷に訴える！",
  ui_story_5051_50510701_27_dialog_content = "また道を間違えたみたいです。すみませんでしたっ！",
  ui_story_5051_50510701_28_dialog_content = "アブラ…ハダブラ…",
  ui_story_5051_50510701_29_dialog_content = "ここは…レストランですか？",
  ui_story_5051_50510701_30_dialog_content = "でも、人がいませんね。",
  ui_story_5051_50510701_31_dialog_content = "<color=#e8d9bb>グゥ――</color>",
  ui_story_5051_50510701_32_dialog_content = "水晶ったら、私がお腹空かしてるのを知って、ここへ連れてきてくれたんですか？",
  ui_story_5051_50510701_33_dialog_content = "ああ…でも、人探しが先決です！\nそれに「記憶の鏡晶」の中で食べても意味ないですよね！",
  ui_story_5051_50510701_34_dialog_content = "もう一回行きますよ！",
  ui_story_5051_50510701_35_dialog_content = "インヴェニレエウム～、インヴェニレエウム～、インヴェニレエウム。",
  ui_story_5051_50510701_36_dialog_content = "どうか教えてください。私の思う人は今どこにいるんですか？",
  ui_story_5051_50510701_37_dialog_content = "アブラハダブラ！",
  ui_story_5051_50510701_38_dialog_content = "<size=45>ハハハハハハ！！</size>",
  ui_story_5051_50510701_39_dialog_content = "だ、誰です！？急に大声で笑って、何なんです！びっくりしたじゃないですか…",
  ui_story_5051_50510701_40_dialog_content = "お嬢ちゃん…あなたの…ゲプッ…占い…全然なってないわね。",
  ui_story_5051_50510701_41_dialog_content = "私の占いがダメだって言うんですか！？",
  ui_story_5051_50510701_42_dialog_content = "私はママから占いを教わったんです！ママは凄腕の占い師なんですよ！",
  ui_story_5051_50510701_43_dialog_content = "北境の占い師「<color=#FFB400>ボアーズ</color>」です！\nまさか聞いたことないなんて言わせませんよ！",
  ui_story_5051_50510701_44_dialog_content = "「ポアーズ」？なんか…聞き覚えあるわね…ゲプッ。",
  ui_story_5051_50510701_45_dialog_content = "でも…だから何だっていうの！？\n間違いは間違い、お嬢ちゃん、大人しく負けを認めなさ～い。",
  ui_story_5051_50510701_46_dialog_content = "ふんっ…なんて失礼な人でしょう。目にもの見せてやります！",
  ui_story_5051_50510701_47_dialog_content = "ゲプッ…腕はないのに…口だけは達者みたいね。",
  ui_story_5051_50510701_48_dialog_content = "どう？こうしない？私と占い勝負しましょ。見事当たった方が勝ち。",
  ui_story_5051_50510701_49_dialog_content = "受けて立とうじゃありませんか！",
  ui_story_5051_50510701_50_dialog_content = "そこのお客様、お支払いをお願いします。",
  ui_story_5051_50510701_51_dialog_content = "ええ？ああ…あら、お金、持ってないわ…ゲプッ。",
  ui_story_5051_50510701_52_dialog_content = "では、そちらの方は？",
  ui_story_5051_50510701_53_dialog_content = "わ、私？その人とは知り合いでも何でもないのに、なんで私が払うんです…？",
  ui_story_5051_50510701_54_dialog_content = "お二人ともお支払いいただけないというなら、ここで衛兵をお持ちください。",
  ui_story_5051_50510701_55_dialog_content = "ええ！？だ、ダメですよ！私には重要な用があるんです！",
  ui_story_5051_50510701_56_dialog_content = "黙ってないで何とか言ってください！",
  ui_story_5051_50510701_57_dialog_content = "すぅ…",
  ui_story_5051_50510701_58_dialog_content = "寝ちゃいました…",
  ui_story_5051_50510701_59_dialog_content = "お支払いいただくか、衛兵に連行されるか、どちらかお選びください。",
  ui_story_5051_50510701_60_dialog_content = "わかりました…いくらです？",
  ui_story_5051_50510701_61_dialog_content = "127938白夜コインです。",
  ui_story_5051_50510701_62_dialog_content = "<size=45>い、いくらですって！？</size>",
  ui_story_5051_50510701_63_dialog_content = "この方はうちが大切に収蔵していた銘酒を何本も空けてしまったのです。\nこれでも祝日の特別価格ですよ。",
  ui_story_5051_50510701_64_dialog_content = "なんてこと…私の旅費が…へそくりが…",
  ui_story_5051_50510701_65_dialog_content = "（でも「記憶の鏡晶」の中で起こったことは現実じゃありませんし、\n水晶の中から出さえすれば、お金はちゃんと戻りますよね）",
  ui_story_5051_50510701_66_dialog_content = "どうぞ…",
  ui_story_5051_50510701_67_dialog_content = "ありがとうございます。",
  ui_story_5051_50510701_68_dialog_content = "ちょっと、あなたの代わりにお酒代払ったんですから、もう逃げる口実はありませんよ。",
  ui_story_5051_50510701_69_dialog_content = "ママの名誉にかけて、戦ってやります！",
  ui_story_5051_50510701_70_dialog_content = "…あれ、どこに行ったんです？",
  ui_story_5051_50510701_71_dialog_content = "ふふ～ん、こっちよ～…ゲプッ。",
  ui_story_5051_50510701_72_dialog_content = "ちょっと！待ってください！待ちなさいってば！",
  ui_story_5051_50510701_73_dialog_content = "人混みに紛れて逃げようとしても、そうはいきません！",
  ui_story_5051_50510701_74_dialog_content = "よし、ここだわ…",
  ui_story_5051_50510701_75_dialog_content = "つかまえました！",
  ui_story_5051_50510701_76_dialog_content = "代わりにお酒代を出させただけじゃなく、スキを見て逃げ出すなんて…",
  ui_story_5051_50510701_77_dialog_content = "今度こそ逃がしませんよ！",
  ui_story_5051_50510701_78_dialog_content = "え？逃げるって何が？ほら…あなたの探してる人、そこにいるわよ。",
  ui_story_5051_50510701_79_dialog_content = "私の探してる人って…？",
  ui_story_5051_50510701_80_dialog_content = "見て見て！パレードが来たよ！",
  ui_story_5051_50510701_81_dialog_content = "城主様はなんと勇ましいお姿なんだ！",
  ui_story_5051_50510701_82_dialog_content = "カレン様とヴェロニカ様もいるよ！",
  ui_story_5051_50510701_83_dialog_content = "ヨシュア夫人だわ――",
  ui_story_5051_50510701_84_dialog_content = "ソルラド家、万歳！",
  ui_story_5051_50510701_85_dialog_content = "ヴェロニカ、顔を上げなさい。みんながあなたにあいさつしているわ。",
  ui_story_5051_50510701_86_dialog_content = "う…うん。",
  ui_story_5051_50510701_87_dialog_content = "緊張しなくていいのよ。さあ、わたくしの手を握って。",
  ui_story_5051_50510701_88_dialog_content = "（ミヤ、やっぱり緊張してるみたいだ）",
  ui_story_5051_50510701_89_dialog_content = "（パレードはもう少し続くけど、頑張れるかな…？）",
  ui_story_5051_50510701_90_dialog_content = "（それにしても…昔の「ソルラド家記念日」って、こんなに盛大だったんだね）",
  ui_story_5051_50510701_91_dialog_content = "（今のパーティーも十分華やかだけど、\n12年前の祝典の催し物とは比べ物にならないな）",
  ui_story_5051_50510701_92_dialog_content = "（12年でどうしてこんなに変わっちゃったんだろう？）",
  ui_story_5051_50510701_93_dialog_content = "（それに、今日城門で出くわした暗鬼は\n明らかに荷物に偶然紛れ込んでいたようなものじゃない）",
  ui_story_5051_50510701_94_dialog_content = "（12年前の今日、誰かが祝日に乗じて、こっそり暗鬼を白夜城に送り込んでたんだ）",
  ui_story_5051_50510701_95_dialog_content = "（騎士団で対応しきれるのかな？それとも、もっと大きな騒動になるのかな…）",
  ui_story_5051_50510701_96_dialog_content = "（はぁ…皆に危険が及ばなければいいけど）",
  ui_story_5051_50510701_97_dialog_content = "（…ん？誰かにずっと見られてる気がする）",
  ui_story_5051_50510701_98_dialog_content = "（そんなはずないよね。僕なんて見たって仕方ない。ただの付き添いの従者だし）",
  ui_story_5051_50510701_99_dialog_content = "（でも、Ms.ロトからパレード中はキョロキョロよそ見をして、\n列を乱さないようにって言われた…）",
  ui_story_5051_50510701_100_dialog_content = "（考えすぎないようにしよう！）",
  ui_story_5051_50510701_101_dialog_content = "ねえ、ちょっと――PlayerName！ミヤ！",
  ui_story_5051_50510701_102_dialog_content = "もうっ、人が多すぎます！うるさくて、全然声が届きません！",
  ui_story_5051_50510701_103_dialog_content = "よいしょっと…ムダよ。",
  ui_story_5051_50510701_104_dialog_content = "声が届いたところで、あの2人がパレードから抜けることなんてできないでしょ。",
  ui_story_5051_50510701_105_dialog_content = "確かにそうですね…",
  ui_story_5051_50510701_106_dialog_content = "それはそうと、なんで私が人を探してるってわかったんです？",
  ui_story_5051_50510701_107_dialog_content = "しかも、なんでその人物がここにいるってわかったんです？",
  ui_story_5051_50510701_108_dialog_content = "占い勝負するって言ったでしょ？",
  ui_story_5051_50510701_109_dialog_content = "私の勝ちね～。",
  ui_story_5051_50510701_110_dialog_content = "…",
  ui_story_5051_50510701_111_dialog_content = "<size=45>素晴らしいです！</size>",
  ui_story_5051_50510701_112_dialog_content = "<size=45>弟子にしてください！！</size>",
  ui_story_5051_50510701_113_dialog_content = "まぁ…そんな大きな声出さないで。頭が痛くなるわ…",
  ui_story_5051_50510701_114_dialog_content = "私ね、弟子はとらないの。ここに来たのは頼まれた仕事をして、お酒代を稼ぐため。",
  ui_story_5051_50510701_115_dialog_content = "今夜…いえ、明日…もしくは、明後日？好きなだけ飲んで飽きたら、家に帰るわ。",
  ui_story_5051_50510701_116_dialog_content = "だったら、せめて名前だけでも教えてください！",
  ui_story_5051_50510701_117_dialog_content = "（そうすれば、「記憶の鏡晶」から出た後、訪ねに行けますから！）",
  ui_story_5051_50510701_118_dialog_content = "分かったわ。さっきはお酒代、払ってくれたし…",
  ui_story_5051_50510701_119_dialog_content = "「ボアーズ」っていうの。",
  ui_story_5051_50510701_120_dialog_content = "え…？",
  ui_story_5051_50510701_121_dialog_content = "<color=#FFB400>ママ</color>？",
  ui_story_5051_50510701_122_dialog_content = "白夜城じゅうの民が会し、今日という特別な日を共に祝ってくれることに感謝する。",
  ui_story_5051_50510701_123_dialog_content = "ソルラド家は白夜城の主の冠を戴く者であり、同時にまた使命を託された一族でもある。",
  ui_story_5051_50510701_124_dialog_content = "我らはこの手で人々を守り続けよう。\nだが、民を守るために我らが握る剣は皆から託されたもの。",
  ui_story_5051_50510701_125_dialog_content = "今日ここで「ソルラド」家の美徳と白夜城の民の美徳を讃えよう。",
  ui_story_5051_50510701_126_dialog_content = "「ソルラド家記念日」の式典開催を宣言する！",
  ui_story_5051_50510701_127_dialog_content = "続いて「決闘の儀式」を行う。",
  ui_story_5051_50510701_128_dialog_content = "実に素晴らしい開幕の挨拶でしたな、殿下。",
  ui_story_5051_50510701_129_dialog_content = "…",
  ui_story_5051_50510701_130_dialog_content = "ご覧ください、この賑わいを。これこそまさに我々白夜城の力の体現ですぞ。",
  ui_story_5051_50510701_131_dialog_content = "この栄光に浴するにふさわしいのは、ソルラド家だけではありませんかな。",
  ui_story_5051_50510701_132_dialog_content = "今日ヴェロニカ殿下が城内に潜入しようとした暗鬼を\n城門で撃破したと聞き及びましたぞ。",
  ui_story_5051_50510701_133_dialog_content = "見習い騎士でありながら、\nその颯爽とした勇姿は一人前の騎士にも見劣りしなかったそうですな。",
  ui_story_5051_50510701_134_dialog_content = "祝典のため特別配備した護衛隊が現場に駆け付けた時には、\n暗鬼は1匹残らず倒されていたとか。",
  ui_story_5051_50510701_135_dialog_content = "警備を任されていた護衛隊は確かカルティマ家でしたかな？\nまったくカルティマときたら…",
  ui_story_5051_50510701_136_dialog_content = "…ささいなことだ。騒ぎ立てることではない。",
  ui_story_5051_50510701_137_dialog_content = "おそらくヴェロニカもその道理をわきまえておるがゆえに、\n自ら手柄を報告せずにいたのであろう。",
  ui_story_5051_50510701_138_dialog_content = "…",
  ui_story_5051_50510701_139_dialog_content = "そう謙遜なさるな。",
  ui_story_5051_50510701_140_dialog_content = "この件はすでに城内に知れ渡っておりますぞ。",
  ui_story_5051_50510701_141_dialog_content = "「ヴェロニカ殿下は鷹の爪を隠していたのだ。\n殿下があっという間に暗鬼を倒し、危機を脱した」と。",
  ui_story_5051_50510701_142_dialog_content = "おそらく多くの者が殿下の勇姿をこの目で見てみたいと思っておるでしょうな。",
  ui_story_5051_50510701_143_dialog_content = "不平不正を正し、弱きを助けるは讃えるべき美徳である。",
  ui_story_5051_50510701_144_dialog_content = "だが、若いうちから、やたらに腕をひけらかし、\n表に出たがる習慣を付けてはならぬ。",
  ui_story_5051_50510701_145_dialog_content = "小手先の技を磨いたところで、大成せぬからな。",
  ui_story_5051_50510701_146_dialog_content = "そのようなこと、おっしゃってはなりませんぞ！",
  ui_story_5051_50510701_147_dialog_content = "ヴェロニカ殿下は控えめなために、名声が広がっていないだけのこと。",
  ui_story_5051_50510701_148_dialog_content = "一方のカレン殿下は幼い頃から帝王学の奇才とまで讃えられていらっしゃる。",
  ui_story_5051_50510701_149_dialog_content = "あと何年かすれば、カレン殿下はますます頭角を現すことでしょう。\nそうなれば、ヴェロニカ殿下の長女としての威厳は…",
  ui_story_5051_50510701_150_dialog_content = "トロイ公爵！後々のことなど、我々が口をはさむことではなかろう。",
  ui_story_5051_50510701_151_dialog_content = "城主様は才能を見抜く優れた目をお持ちだ。人材も大切になさる。",
  ui_story_5051_50510701_152_dialog_content = "この度殿下を前線から呼び戻されたのもお考えがあっての事であろう。",
  ui_story_5051_50510701_153_dialog_content = "ハハハ、もっともだ。才能の使い道はそれぞれ違うもの。\nヴェロニカ殿下は城内にいる方が才を発揮できるでしょうな。",
  ui_story_5051_50510701_154_dialog_content = "殿下、無礼をお許しください。",
  ui_story_5051_50510701_155_dialog_content = "お父様、私は…",
  ui_story_5051_50510701_156_dialog_content = "ヴェロニカ、準備せよ。",
  ui_story_5051_50510701_157_dialog_content = "え、準備ですか？",
  ui_story_5051_50510701_158_dialog_content = "「予定では」、まもなくお前の番であろう。",
  ui_story_5051_50510701_159_dialog_content = "民を待たせるでない。",
  ui_story_5051_50510701_160_dialog_content = "はい…わかりました！",
  ui_story_5051_50510701_161_dialog_content = "お主ら2人は長年余のそばにおっただけあって、\n余の考えていることなどお見通しのようだな。",
  ui_story_5051_50510701_162_dialog_content = "ヴェロニカを儀式の後半で登場させ、\n開幕式でソルラド家新世代の力を披露しようと考えていたのだが――",
  ui_story_5051_50510701_163_dialog_content = "お主らに見抜かれていたとは。",
  ui_story_5051_50510701_164_dialog_content = "ハハハ…老いぼれのたわごとでございますよ。",
  ui_story_5051_50510701_165_dialog_content = "ヴェロニカ殿下の初お披露目、実に楽しみですな！",
  ui_story_5051_50510701_166_dialog_content = "ミヤ、本当にやるの？",
  ui_story_5051_50510701_167_dialog_content = "…",
  ui_story_5051_50510701_168_dialog_content = "今こそ逃げるにはもってこいのチャンスだと思うよ。",
  ui_story_5051_50510701_169_dialog_content = "もともとヨシュア夫人に会いたかっただけで、\n突然ソルラドさんが現れたから、ここまで来ちゃったけど…",
  ui_story_5051_50510701_X169_dialog_content = "夫人に皆を探すのを手伝ってくれるように頼めないとしたって、\nこれ以上この世界に干渉するわけにはいかない。",
  ui_story_5051_50510701_170_dialog_content = "そ、その通りね…私たち、ここを離れるべきよね…",
  ui_story_5051_50510701_171_dialog_content = "壇上にいるあの人はただの幻影、お父様じゃない…\n断ってもいいのよね…怒られないわ…",
  ui_story_5051_50510701_X171_dialog_content = "ヴェロニカ、何度言ったら分かるのだ？\nお前には才能がないのだ、練習などせんでよい。",
  ui_story_5051_50510701_X172_dialog_content = "ヴェロニカ、なぜ挨拶せぬのだ？もう10歳になるのだぞ、子どもではないのだ。",
  ui_story_5051_50510701_X173_dialog_content = "騎士団に入りたいと？ヴェロニカ、余はお前が人より抜きんでることなど望んでおらぬ。\nただ母上にだけは心配をかけるな。",
  ui_story_5051_50510701_172_dialog_content = "ミヤ…？",
  ui_story_5051_50510701_173_dialog_content = "（どうして急に震え出したんだろう？\nお父さんに言われたことに逆らうのがこわいのかな？）",
  ui_story_5051_50510701_174_dialog_content = "（もしそうだとしたら、今無理やりここを離れても、ミヤにストレスを与えるだけだ…）",
  ui_story_5051_50510701_175_dialog_content = "（やっと病気が良くなってきたのに！）",
  ui_story_5051_50510701_176_dialog_content = "…そうね。",
  ui_story_5051_50510701_177_dialog_content = "ミヤ、決闘に参加したい？",
  ui_story_5051_50510701_178_dialog_content = "わ、私に聞いてるの？私は…どっちでもいいの。\nPlayerNameは…参加するべきだと思う？",
  ui_story_5051_50510701_179_dialog_content = "決闘に参加して震えが止まるなら、行くといいよ。",
  ui_story_5051_50510701_180_dialog_content = "え？震えてる…？あ…また病気が…",
  ui_story_5051_50510701_181_dialog_content = "ミヤの手、冷たいな。",
  ui_story_5051_50510701_182_dialog_content = "そうなの。この身体になってから、ずっと手が冷たいの。",
  ui_story_5051_50510701_183_dialog_content = "PlayerNameの手は…あったかいのね。",
  ui_story_5051_50510701_184_dialog_content = "あなたの手の温度を感じてたら、なんだか安心してきたわ…",
  ui_story_5051_50510701_185_dialog_content = "ありがとう、もう怖くないわ。",
  ui_story_5051_50510701_X180_dialog_content = "ごめんなさい、迷惑をかけて。",
  ui_story_5051_50510701_X181_dialog_content = "そんな風に言わないで。家族を探すの手伝うって約束したのも、\nパーティーに君を連れてきたのも僕なんだよ。ミヤの面倒を見るのは当然だ。",
  ui_story_5051_50510701_X182_dialog_content = "決闘に参加して君の中にわだかまってるものが解けるなら、行くといいよ！",
  ui_story_5051_50510701_X183_dialog_content = "責任は全部僕が負うから！",
  ui_story_5051_50510701_X184_dialog_content = "（いざとなったら、決闘が終わってから逃げればいいんだ…！）",
  ui_story_5051_50510701_X185_dialog_content = "PlayerName…あなたは優しい、いい人よ。でも、どうして私のために…",
  ui_story_5051_50510701_X186_dialog_content = "僕たちは友達だからだよ。",
  ui_story_5051_50510701_X187_dialog_content = "え…？友だち？",
  ui_story_5051_50510701_X188_dialog_content = "友だちならお互いに助け合うのも、\n相手に健康で楽しく過ごしてほしいって思うのは当然でしょ？",
  ui_story_5051_50510701_X189_dialog_content = "……",
  ui_story_5051_50510701_X190_dialog_content = "な、何か…ヘンなこと言っちゃった？",
  ui_story_5051_50510701_X191_dialog_content = "ふふ…少しだけ。",
  ui_story_5051_50510701_X192_dialog_content = "ど、どこがヘンだったんだろう…？",
  ui_story_5051_50510701_X193_dialog_content = "だってバーバ・ヤーガ以外に、友だち扱いしてくれた人はいなかったから。",
  ui_story_5051_50510701_X194_dialog_content = "みんな私のことを「お姫様」か、「かわいそうなミヤ」としか思ってなかったから…",
  ui_story_5051_50510701_X195_dialog_content = "PlayerName、私…本当に決闘に出てもいいの？",
  ui_story_5051_50510701_X196_dialog_content = "うん、もちろんだよ。",
  ui_story_5051_50510701_X197_dialog_content = "ありがとう…きっとあなたの信頼に応えてみせるわ。",
  ui_story_5051_50510701_X198_dialog_content = "…そうだわ。決闘中は周囲の人の視線が壇上に集まるわ。",
  ui_story_5051_50510701_X199_dialog_content = "その間PlayerNameは壇上から人混みの中にお父様たちがいないか探してみて。",
  ui_story_5051_50510701_X200_dialog_content = "そうすれば、お母様の助けがなくても、自分たちでみんなを見つけられる。",
  ui_story_5051_50510701_X201_dialog_content = "決闘に参加するのも、あながち間違った選択とは言えなかったみたい…",
  ui_story_5051_50510701_X202_dialog_content = "その通りだよ、ミヤ！僕の底抜けの楽観主義が君にもうつったみたいだね！",
  ui_story_5051_50510701_X203_dialog_content = "ヴェロニカ殿下、決闘がまもなく始まります。こちらへどうぞ。",
  ui_story_5051_50510701_X204_dialog_content = "ええ、今行くわ。",
  ui_story_5051_50510701_X205_dialog_content = "じゃあ…行ってくるわね！",
  ui_story_5051_50510701_X206_dialog_content = "ミヤ、頑張ってね！",
  ui_story_5051_50510701_186_dialog_content = "ミヤ、頑張ってね。もし本当に勝てそうになかったら…",
  ui_story_5051_50510701_187_dialog_content = "万が一殿下が劣勢に立たれた場合は、こちらが手加減いたします。",
  ui_story_5051_50510701_188_dialog_content = "え？あなたは…",
  ui_story_5051_50510701_189_dialog_content = "ヴェロニカ殿下、ごきげんよう。私はこの後殿下と決闘をする衛兵でございます。",
  ui_story_5051_50510701_190_dialog_content = "城主様より殿下の安全を第一としたうえで、手合わせするよう申し付かりました。",
  ui_story_5051_50510701_191_dialog_content = "武器もこちらにある剣にお取替えください。\n練習用なので、ケガをなさることもありません。",
  ui_story_5051_50510701_192_dialog_content = "それに今日は「ソルラド家記念日」の開幕式ですから、\n当然殿下に恥をかかせるようなことはいたしませんよ。",
  ui_story_5051_50510701_193_dialog_content = "試合では、互いに動きを合わせ、私を倒したふりをなさってくだされば結構です。",
  ui_story_5051_50510701_194_dialog_content = "倒した…ふり…？",
  ui_story_5051_50510701_195_dialog_content = "つまり、本当の試合ではないということ…？",
  ui_story_5051_50510701_196_dialog_content = "パーティーでの接待のように、ただやりすごせばいいというの…？",
  ui_story_5051_50510701_197_dialog_content = "ヴェロニカ、何度言ったら分かるのだ？\nお前には才能がないのだ、練習などせんでよい。",
  ui_story_5051_50510701_198_dialog_content = "ヴェロニカ、なぜ挨拶せぬのだ？もう10歳になるのだぞ、子どもではないのだ。",
  ui_story_5051_50510701_199_dialog_content = "騎士団に入りたいと？ヴェロニカ、余はお前が人より抜きんでることなど望んでおらぬ。\nただ母上にだけは心配をかけるな。",
  ui_story_5051_50510701_200_dialog_content = "ミヤ！しっかりして！",
  ui_story_5051_50510701_201_dialog_content = "PlayerName…",
  ui_story_5051_50510701_202_dialog_content = "ミヤ、お父さんが歩みよってくれるのを待つ必要なんてない。\n自分から自分を証明してみせればいいんだよ。",
  ui_story_5051_50510701_203_dialog_content = "城主の権力は大きいかもしれないけど、君のすべてに干渉できるわけじゃない。",
  ui_story_5051_50510701_204_dialog_content = "何を思い出したのかは分からないけど…",
  ui_story_5051_50510701_205_dialog_content = "今の君はもう、12年前の君じゃないんだ。",
  ui_story_5051_50510701_206_dialog_content = "私…",
  ui_story_5051_50510701_207_dialog_content = "仕組まれた「勝利」は受け入れられないんだよね。",
  ui_story_5051_50510701_208_dialog_content = "だったら、実力で皆に示せばいい。\n君は自分の力で本物の「勝利」を手に入れることができるんだって。",
  ui_story_5051_50510701_209_dialog_content = "でも、相手は…",
  ui_story_5051_50510701_210_dialog_content = "相手が本気を出したがらないなら、追い込んで本気を出させればいいんだよ！",
  ui_story_5051_50510701_211_dialog_content = "追い込む？うう…全力を出すまで追い込むなんて…私にできるかしら？",
  ui_story_5051_50510701_212_dialog_content = "もちろん出来るよ！さっきあの人たちが話してたでしょ。\n騎士団が駆け付ける前に君が暗鬼を倒したことは白夜城じゅうに知れ渡ってるんだ。",
  ui_story_5051_50510701_213_dialog_content = "平の衛兵なんてミヤの相手じゃないよ。",
  ui_story_5051_50510701_214_dialog_content = "オホン。あの…お二人とも…私はここにおるのですが…",
  ui_story_5051_50510701_215_dialog_content = "あ、すみません。あははは…",
  ui_story_5051_50510701_216_dialog_content = "聞かれてしまったのなら、この際ハッキリ言います。",
  ui_story_5051_50510701_217_dialog_content = "ミヤ、準備はできた？",
  ui_story_5051_50510701_218_dialog_content = "私…私のこと、PlayerNameがこんなに信じてくれるなんて…\n私の力を信じてくれた人は初めてよ。",
  ui_story_5051_50510701_219_dialog_content = "準備できたわ！",
  ui_story_5051_50510701_220_dialog_content = "じゃあ――",
  ui_story_5051_50510701_221_dialog_content = "「白夜に捧ぐ、勇敢なる戦士よ。決闘を申し出る！」",
  ui_story_5051_50510701_222_dialog_content = "「剣を握るか、己の尊厳を捨てるか」",
  ui_story_5051_50510701_223_dialog_content = "「挑戦を受けるのならば、\nたとえ命を落とそうとも一切恨み言をいわないとお互いに約束しよう」",
  ui_story_5051_50510701_224_dialog_content = "「命を落とそうとも」はちょっと大げさなんじゃ…",
  ui_story_5051_50510701_225_dialog_content = "その通りです。どうかお許しください。私にはとても…",
  ui_story_5051_50510701_226_dialog_content = "しょ、小説の中で、そういうセリフがあったから、適当に言ってみただけなの…",
  ui_story_5051_50510701_227_dialog_content = "はぁ…分かりました。簡単には死んだふりや降参はしないとお約束しましょう。",
  ui_story_5051_50510701_228_dialog_content = "ただ、本当に殿下が私に勝てない時には、城主様のお申し付け通り、\n大人しく降参いたします。命令に背くことはできませんから。",
  ui_story_5051_50510701_229_dialog_content = "よかった、ありがとう！",
  ui_story_5051_50510701_230_dialog_content = "じゃあ、この剣は…",
  ui_story_5051_50510701_231_dialog_content = "その剣は持って行きなよ。",
  ui_story_5051_50510701_232_dialog_content = "ええ、その通りです。ご自身を傷つけることがあってはなりません。",
  ui_story_5051_50510701_233_dialog_content = "僕はあなたがケガをしないかと心配して言ったんです！",
  ui_story_5051_50510701_234_dialog_content = "え？",
  ui_story_5051_50510701_235_dialog_content = "そうね。",
  ui_story_5051_50510701_236_dialog_content = "さっきから殿下を「ミヤ」と呼んでらっしゃいますが…",
  ui_story_5051_50510701_237_dialog_content = "今目の前にいるムチャがお好きなお嬢様は、本当にあの弱々しいヴェロニカ殿下ですか？",
  ui_story_5051_50510701_238_dialog_content = "も、もちろんです！「ミヤ」っていうのは…",
  ui_story_5051_50510701_239_dialog_content = "僕たち2人だけのあだ名なんです！",
  ui_story_5051_50510701_240_dialog_content = "そ、そうですか…",
  ui_story_5051_50510701_241_dialog_content = "では、そろそろお時間です。では殿下、後ほど会場でお会いしましょう。",
  ui_story_5051_50510701_242_dialog_content = "わかったわ。悔いを残さないよう、最後まで全力で戦ってね…！",
  ui_story_5051_50510701_243_dialog_content = "しょ、承知いたしました…",
  ui_story_5051_50510701_244_dialog_content = "（上から申し付かった任務を果たしに来ただけなんですが…\n何だか無理やり青春恋愛劇を見せられた気分です…）",
  ui_story_5051_50510802_1_dialog_content = "（この押し寄せる波のような歓声、どこかで聞きましたね）",
  ui_story_5051_50510802_2_dialog_content = "（どうやら式典が始まったようです）",
  ui_story_5051_50510802_3_dialog_content = "（さてと…「記憶の鏡晶」を取りに行きましょうか…）",
  ui_story_5051_50510802_4_dialog_content = "おい、そこの者、止まれ。",
  ui_story_5051_50510802_5_dialog_content = "（チッ、どうしてまだ守衛がここに！）",
  ui_story_5051_50510802_6_dialog_content = "名を名乗れ。",
  ui_story_5051_50510802_7_dialog_content = "名乗れ、ですと？僕はナイト・カレブ・マグヌスです。名乗る必要がありますか？",
  ui_story_5051_50510802_8_dialog_content = "ナイト・カレブ・マグヌス…！？",
  ui_story_5051_50510802_9_dialog_content = "そんなはずはない。数日前ナイトがヨシュア夫人を訪ねてきたが――",
  ui_story_5051_50510802_10_dialog_content = "確かに似ているものの…髪もそんなに長くなく、体型も違っていた！",
  ui_story_5051_50510802_11_dialog_content = "くせ者め！大人しく…",
  ui_story_5051_50510802_12_dialog_content = "大声を出さないでくださいよ。他の兵士まで駆け付けては困ります。",
  ui_story_5051_50510802_13_dialog_content = "（余計な出来事はこれで2回目ですね…\n今日はどうしてこんなにうまく行かないのでしょう）",
  ui_story_5051_50510802_14_dialog_content = "（光力が尽きてしまうまえに、「記憶の鏡晶」を盗み出さなくては…）",
  ui_story_5051_50510802_15_dialog_content = "飲み物、買ってきました！",
  ui_story_5051_50510802_16_dialog_content = "あら、お帰りなさい。",
  ui_story_5051_50510802_17_dialog_content = "あら？どうして酔い覚ましのお茶なの？",
  ui_story_5051_50510802_18_dialog_content = "だって今、あなたは酔っぱらってて、ちゃんと話してくれないじゃないですか…",
  ui_story_5051_50510802_19_dialog_content = "あなたが急に泣きながら抱きついてきたせいで、服が鼻水だらけよ。",
  ui_story_5051_50510802_20_dialog_content = "とにかく～、お酒をちょうだ～い。",
  ui_story_5051_50510802_21_dialog_content = "わかりましたって…お酒もちゃんと買いましたよ、はい。",
  ui_story_5051_50510802_22_dialog_content = "ゴクゴクゴク…ぷっは～っ、おいしい！やっぱりこれでなくちゃね！",
  ui_story_5051_50510802_23_dialog_content = "お酒は十分飲みましたよね。そろそろ占いについて話してくれません？",
  ui_story_5051_50510802_24_dialog_content = "うーん…いいわよ。何が聞きたい？",
  ui_story_5051_50510802_25_dialog_content = "「記憶の鏡晶」の中に入る呪文について、どれくらい知ってます？",
  ui_story_5051_50510802_26_dialog_content = "呪文をとなえて入ってきたのに、姿を隠せず、\nしかも別々の場所に分散してしまってるのはなんででしょう…",
  ui_story_5051_50510802_27_dialog_content = "「記憶の」…「鏡晶」…？",
  ui_story_5051_50510802_28_dialog_content = "お嬢ちゃん、それは…あなたが知ってるはずのないことよ。",
  ui_story_5051_50510802_29_dialog_content = "あなた、いったい何者？",
  ui_story_5051_50510802_30_dialog_content = "だから言ったでしょう！？あなたの娘ですって！ジャキーニですよ！",
  ui_story_5051_50510802_31_dialog_content = "冗談よしてよ～、ジャキーニですって？",
  ui_story_5051_50510802_32_dialog_content = "確かに私はあまり家に帰らないけど…まだ歩けもしないジャキーニが…",
  ui_story_5051_50510802_33_dialog_content = "急にこんなに大きくなるわけないじゃない！",
  ui_story_5051_50510802_34_dialog_content = "ああ、今のこの状況こそ冗談であってほしいですよ！",
  ui_story_5051_50510802_35_dialog_content = "ママは…ママは神秘的で、偉大な、世俗に汚されない占い師じゃないんですか？",
  ui_story_5051_50510802_36_dialog_content = "これじゃただの大酒飲みじゃないですか！",
  ui_story_5051_50510802_37_dialog_content = "あなた…今、私を大酒飲みって言ったの？",
  ui_story_5051_50510802_38_dialog_content = "ダメダメ、ゲプッ…\n私のことは北風のごとくつかみどころのない女――ボアーズって呼んで！",
  ui_story_5051_50510802_39_dialog_content = "はぁ…それはまたいったい何なんですか…？",
  ui_story_5051_50510802_40_dialog_content = "本来ならこんなこと話すべきじゃないんですが、\nでも今となってはもう、あなたに頼るしかないんです。",
  ui_story_5051_50510802_41_dialog_content = "1度しか言わないので、しっかり聞いててくださいよ！",
  ui_story_5051_50510802_42_dialog_content = "んん？",
  ui_story_5051_50510802_43_dialog_content = "私の母、つまり、ボアーズさん、あなたは…",
  ui_story_5051_50510802_44_dialog_content = "「記憶の鏡晶」を作り、\nそして今私たちのいるここは「記憶の鏡晶」の中の世界なんです。",
  ui_story_5051_50510802_45_dialog_content = "12年後「記憶の鏡晶」を起動した方はもう他界していましたが――",
  ui_story_5051_50510802_46_dialog_content = "水晶の中の世界に入るため、\nあなたの残したノートに基づいて、私が呪文を作ったんです。",
  ui_story_5051_50510802_47_dialog_content = "でも、この世界に入ってきてみたら、\n姿を隠すこともできていないし、仲間ともはぐれてしまってたんです…",
  ui_story_5051_50510802_48_dialog_content = "どうすればいいんですか？",
  ui_story_5051_50510802_49_dialog_content = "…そうだったの。",
  ui_story_5051_50510802_50_dialog_content = "わかってくれました…？",
  ui_story_5051_50510802_51_dialog_content = "なるほど。あなたのお母さんと私は同姓同名で、しかも私の作品を盗作したのね！",
  ui_story_5051_50510802_52_dialog_content = "私の名前は幸運をもたらすって言われてるのに、\nあなたのママは…ふふ、ちょっと違ったみたいね～。",
  ui_story_5051_50510802_53_dialog_content = "ううっ…あなたって人は…",
  ui_story_5051_50510802_54_dialog_content = "この大酒飲み！もう好きに飲んでてください！",
  ui_story_5051_50510802_55_dialog_content = "何もかも忘れるほど飲んで！私とパパまで忘れるなんて！\n二度と帰ってこなくてもいいですよ！",
  ui_story_5051_50510802_56_dialog_content = "お嬢ちゃん、そんなひどいこと言わないでよ。",
  ui_story_5051_50510802_57_dialog_content = "さっきママのノートを元にして、「記憶の鏡晶」の呪文を作ったって言ったわね！？",
  ui_story_5051_50510802_58_dialog_content = "冗談でしょう？そんなこと私にだって出来ないわ。",
  ui_story_5051_50510802_59_dialog_content = "もしそんなことができたら、きっとその人、前代未聞の天才よ！",
  ui_story_5051_50510802_60_dialog_content = "て、天才…？",
  ui_story_5051_50510802_61_dialog_content = "私、前代未聞の天才だったんですか？",
  ui_story_5051_50510802_62_dialog_content = "ハハハハ、私があなたのママだったら、嬉しくって飛び跳ねちゃうわ！",
  ui_story_5051_50510802_63_dialog_content = "えへへ…そ、そうですか…",
  ui_story_5051_50510802_64_dialog_content = "いえ…そんなこと今は重要じゃありません！",
  ui_story_5051_50510802_65_dialog_content = "私はこれからどうしたらいいんでしょう？",
  ui_story_5051_50510802_66_dialog_content = "うーん…あなたが作ったっていう呪文を聞かせてちょうだい。",
  ui_story_5051_50510802_67_dialog_content = "あ、わかりました。",
  ui_story_5051_50510802_68_dialog_content = "アド・プラエテリトゥム～、アド・プラエテリトゥム～、アド・プラエテリトゥム！",
  ui_story_5051_50510802_69_dialog_content = "我らを過去のあの日へと導きたまえ！",
  ui_story_5051_50510802_70_dialog_content = "アブラハダブラ！",
  ui_story_5051_50510802_71_dialog_content = "…っとまぁ、こんな感じです…",
  ui_story_5051_50510802_72_dialog_content = "ええ？なるほど～、その呪文、間違ってるわよ。",
  ui_story_5051_50510802_73_dialog_content = "えっ？",
  ui_story_5051_50510802_74_dialog_content = "「アブラハダブラ」じゃなくて、「アブラカダブラ」よ。",
  ui_story_5051_50510802_75_dialog_content = "あなた大丈夫～？占い師がそんなヘマしちゃって。",
  ui_story_5051_50510802_76_dialog_content = "違いますよ、ママの残したノートにはそう書いてあるんです！ほら！",
  ui_story_5051_50510802_77_dialog_content = "どれどれ…ハハハハ、ずいぶん汚い字ね。",
  ui_story_5051_50510802_78_dialog_content = "ここなんて異世界の文字みたいじゃない。どうりで間違えるわけね。",
  ui_story_5051_50510802_79_dialog_content = "酔っぱらってる時に書いたんじゃないの？",
  ui_story_5051_50510802_80_dialog_content = "あなたが書いたんでしょう！",
  ui_story_5051_50510802_81_dialog_content = "アハハハ……",
  ui_story_5051_50510802_82_dialog_content = "この呪文でいいのよ～。",
  ui_story_5051_50510802_83_dialog_content = "ただ、実際に使う時には細かい注意事項があるの。",
  ui_story_5051_50510802_84_dialog_content = "中の世界に入る時、手はつないだ？",
  ui_story_5051_50510802_85_dialog_content = "いいえ…",
  ui_story_5051_50510802_86_dialog_content = "なるほど。それでバラバラになったのね。",
  ui_story_5051_50510802_87_dialog_content = "でも、みなさんには伝えました。この世界を変えるようなことはしちゃいけないって。",
  ui_story_5051_50510802_88_dialog_content = "だったら、そんなに問題はないですよね…？",
  ui_story_5051_50510802_89_dialog_content = "あらあら、そうじゃないわ。",
  ui_story_5051_50510802_90_dialog_content = "姿を隠せていないかぎり、ただ呼吸するだけでもこの世界を変えることにつながるわ。",
  ui_story_5051_50510802_91_dialog_content = "何ですって…？",
  ui_story_5051_50510802_92_dialog_content = "「記憶の鏡晶」の中の世界に気づかれた時点で、\nこの世界のすべてがあなたたちの存在に合わせるように調整されてしまうの。",
  ui_story_5051_50510802_93_dialog_content = "そして最後には…",
  ui_story_5051_50510802_94_dialog_content = "最後には…？",
  ui_story_5051_50510802_95_dialog_content = "この世界の一部となって、<color=#FFB400>永遠に出られなくなる</color>のよ。",
  ui_story_5051_50510802_96_dialog_content = "<size=45>えぇっ！？</size>",
  ui_story_5051_50510802_97_dialog_content = "まあ、大きな声を出さないで…",
  ui_story_5051_50510802_98_dialog_content = "じゃあ、今からでも何とかなります？あとどれくらいの時間が残ってるんです？",
  ui_story_5051_50510802_99_dialog_content = "うーん…「記憶の鏡晶」が保存できる時間はおよそ1日でしょ…",
  ui_story_5051_50510802_100_dialog_content = "今日1日が終わらない限り、まだ間に合うわ。たぶんね。",
  ui_story_5051_50510802_101_dialog_content = "それなら間に合います！急いでみなさんと合流して、外に出なければ！",
  ui_story_5051_50510802_102_dialog_content = "ありがとう、ママ！さようなら！いつか必ず家に連れ帰りますから！",
  ui_story_5051_50510802_103_dialog_content = "え？ちょっと待ってよ、どこ行くの？",
  ui_story_5051_50510802_104_dialog_content = "わぁ！？な、何するんです？もうお酒を買うお金なんて持ってませんよ！",
  ui_story_5051_50510802_105_dialog_content = "あなた、もう半日探し続けてるんでしょ？",
  ui_story_5051_50510802_106_dialog_content = "私が助けてあげなかったら…一人も見つけられなかったんじゃない？",
  ui_story_5051_50510802_107_dialog_content = "そうです…",
  ui_story_5051_50510802_108_dialog_content = "ほらね～。だから、あなたのママと同名のよしみで、助けてあげるわ。",
  ui_story_5051_50510802_109_dialog_content = "占術を教えてあげる。",
  ui_story_5051_50510802_110_dialog_content = "本当ですか！？",
  ui_story_5051_50510802_111_dialog_content = "本当よ…さあ、私の気が変わらないうちに始めましょ。",
  ui_story_5051_50510901_1_dialog_content = "<anim type=Shake><size=32>…</size></anim>",
  ui_story_5051_50510901_2_dialog_content = "<anim type=Shake><size=32>ダニエ…</size></anim>",
  ui_story_5051_50510901_3_dialog_content = "<anim type=Shake><size=32>ル…</size></anim>",
  ui_story_5051_50510901_4_dialog_content = "<anim type=Shake><size=32>ダニエル…</size></anim>",
  ui_story_5051_50510901_5_dialog_content = "<anim type=Shake><size=32>ヴェロニカ…カレン…</size></anim>",
  ui_story_5051_50510901_6_dialog_content = "<anim type=Shake><size=37>ダニエル…ヴェロニカ…カレン…</size></anim>",
  ui_story_5051_50510901_7_dialog_content = "<anim type=Shake><size=42>ダニエル！ヴェロニカ！カレン！</size></anim>",
  ui_story_5051_50510901_8_dialog_content = "<color=#e8d9bb>ゴロゴロゴロ――！</color>",
  ui_story_5051_50510901_9_dialog_content = "え！？",
  ui_story_5051_50510901_10_dialog_content = "PlayerName様、どうかしましたか？",
  ui_story_5051_50510901_11_dialog_content = "突然顔色が悪くなられたようですが？",
  ui_story_5051_50510901_12_dialog_content = "な、何でもありません。今の雷の音に驚いただけです。",
  ui_story_5051_50510901_13_dialog_content = "雷ですか？",
  ui_story_5051_50510901_14_dialog_content = "朝にも1度聞いたんですが、さっきのは朝よりもずっと大きかったので。",
  ui_story_5051_50510901_15_dialog_content = "たぶん大雨でも降るんですね。",
  ui_story_5051_50510901_16_dialog_content = "カレンには雷の音なんて聞こえなかったけど？",
  ui_story_5051_50510901_17_dialog_content = "え、今の雷すごく大きな音だったのに、聞こえなかったの？",
  ui_story_5051_50510901_18_dialog_content = "聞えたとしても、カレンは怖くないわ。",
  ui_story_5051_50510901_19_dialog_content = "あはは、カレンは…カレン殿下は本当に勇敢だね。",
  ui_story_5051_50510901_20_dialog_content = "カレンはもう子どもじゃないわ。",
  ui_story_5051_50510901_21_dialog_content = "…",
  ui_story_5051_50510901_22_dialog_content = "あ、カレン殿下？",
  ui_story_5051_50510901_23_dialog_content = "（またヨシュア夫人のところへ行っちゃった）",
  ui_story_5051_50510901_24_dialog_content = "（さっきの目…今とまったく変わらないな）",
  ui_story_5051_50510901_25_dialog_content = "カレン殿下はいつもあの様子なのですよ。子ども扱いするとむくれてしまうのです。",
  ui_story_5051_50510901_26_dialog_content = "ただ不思議ですね。カレン殿下が興味をお持ちになった方はあなたが初めてです。",
  ui_story_5051_50510901_27_dialog_content = "興味？",
  ui_story_5051_50510901_28_dialog_content = "お気づきになりませんでしたか？\nカレン殿下は先程からずっと近くで観察なさっていたんですよ。",
  ui_story_5051_50510901_29_dialog_content = "まだ僕のこと警戒してるのかな…",
  ui_story_5051_50510901_30_dialog_content = "…あ！ミヤ…ヴェロニカの試合中なのに、\n僕としたことが何を別のこと考えてるんだ！",
  ui_story_5051_50510901_31_dialog_content = "これが私の力よ！",
  ui_story_5051_50510901_32_dialog_content = "うっ…ゴホゴホッ。",
  ui_story_5051_50510901_33_dialog_content = "ヴェロニカ殿下はまだ全力を出しきっていないようですが、\nすでに優勢に立っておられますね。",
  ui_story_5051_50510901_34_dialog_content = "ほんのしばらくの間お会いしないうちに、\n殿下の剣術がこれ程まで進歩していたとは驚きです。",
  ui_story_5051_50510901_35_dialog_content = "実に不思議ですね。\nPlayerName様は殿下に何か不思議な薬でも差し上げたのですか？",
  ui_story_5051_50510901_36_dialog_content = "（ミヤはここに来るまでずっと、自分の力を信じようとしなかった）",
  ui_story_5051_50510901_37_dialog_content = "（それは昔のミヤが周りからずっと、戦闘が苦手だって思われてたからなのかな？）",
  ui_story_5051_50510901_38_dialog_content = "黙っていらっしゃるのですね。\nということは、私には教えられない秘密ということでしょうか。",
  ui_story_5051_50510901_39_dialog_content = "別に秘密というわけでもないんです。",
  ui_story_5051_50510901_40_dialog_content = "ヴェロニカはずっと前から強かったんです。\nただ、今まではそれに気づいてなかっただけです。",
  ui_story_5051_50510901_41_dialog_content = "あら？",
  ui_story_5051_50510901_42_dialog_content = "うわっ…危なかった。ヴェロニカ殿下の攻撃、もう少しで衛兵に命中するところだったぞ。",
  ui_story_5051_50510901_43_dialog_content = "2つの剣がぶつかり合って放つ火花が、\nここからでもはっきり見える…真剣勝負なのか！？",
  ui_story_5051_50510901_44_dialog_content = "ヴェロニカ殿下、皆応援してますよ！",
  ui_story_5051_50510901_45_dialog_content = "おお――！",
  ui_story_5051_50510901_46_dialog_content = "ヴェロニカ殿下の剣術に皆さんが歓声と拍手を送っていますね。",
  ui_story_5051_50510901_47_dialog_content = "そうそう、先程聞こえたという雷の音は拍手の音だったのではありませんか？",
  ui_story_5051_50510901_48_dialog_content = "そうでしょうか…",
  ui_story_5051_50510901_49_dialog_content = "（あれ、ちょっと待って！）",
  ui_story_5051_50510901_50_dialog_content = "（…何だろう？背後から何だか寒気が？）",
  ui_story_5051_50510901_51_dialog_content = "（誰かいる！誰か僕を見てる！）",
  ui_story_5051_50510901_52_dialog_content = "（カレンじゃない…娘の試合を観戦してるソルラドさんとヨシュア夫人でもない…）",
  ui_story_5051_50510901_53_dialog_content = "（この感じは、まさか…）",
  ui_story_5051_50510901_54_dialog_content = "PlayerName様、どちらへ？",
  ui_story_5051_50510901_55_dialog_content = "ちょ、ちょっとお手洗いに。",
  ui_story_5051_50510901_56_dialog_content = "でしたら、私がご案内いたしましょう。",
  ui_story_5051_50510901_57_dialog_content = "1人で大丈夫です！",
  ui_story_5051_50510901_58_dialog_content = "あら、PlayerName様ときたら…意外に足が速いのですね。",
  ui_story_5051_50510901_59_dialog_content = "ヴェロニカ殿下のご友人、ですか…とても面白い方ですね。",
  ui_story_5051_50510901_60_dialog_content = "あの視線はたぶん…この辺からだったと思うんだけど…",
  ui_story_5051_50510901_61_dialog_content = "オホン。",
  ui_story_5051_50510901_62_dialog_content = "ソルラドさん！やっぱりソルラドさんだったんですね！",
  ui_story_5051_50510901_63_dialog_content = "さすがPlayerNameだ。鋭い感覚を持っておる。",
  ui_story_5051_50510901_64_dialog_content = "どうやってここが分かったんですか？",
  ui_story_5051_50510901_65_dialog_content = "若者とはにぎやかな所を好むであろう？もしやと思い、来てみたのだ。",
  ui_story_5051_50510901_66_dialog_content = "だが、まさかお主がこうも早く<color=#FFB400>この世界の余</color>と会っているとは思わなんだ。",
  ui_story_5051_50510901_67_dialog_content = "それは…",
  ui_story_5051_50510901_68_dialog_content = "お主も気づいておろう。\n我々は記憶の鏡晶が記録していた歴史の中に吸い込まれてしまった。",
  ui_story_5051_50510901_69_dialog_content = "本来なら姿を見られることなく、\nこの世界の己を観察できるはずなのだが、今はここの者にも我々が見えている。",
  ui_story_5051_50510901_70_dialog_content = "僕も不思議だったんです。いったいどうしたんでしょう？",
  ui_story_5051_50510901_71_dialog_content = "若者よ。それを今考えたところで何にもならぬ。",
  ui_story_5051_50510901_72_dialog_content = "すでに起こってしまったことだ。\n今やるべきことはこれから起こり得る危機を逃れ、解決する術を探ることであろう。",
  ui_story_5051_50510901_73_dialog_content = "ジャキーニが申しておった。「記憶の鏡晶」の中の歴史を変えようとしてはならぬ、\nさもなければ、想像を超える危機が待っていると。",
  ui_story_5051_50510901_74_dialog_content = "この世界との深い関わりを避けるためにも、控えめに行動せねばならぬ。",
  ui_story_5051_50510901_75_dialog_content = "僕とミヤは城内で皆を探そうとして、それで仕方なく…",
  ui_story_5051_50510901_76_dialog_content = "…",
  ui_story_5051_50510901_77_dialog_content = "ソルラドさん？どうしてそんな顔をするんですか？",
  ui_story_5051_50510901_78_dialog_content = "ミヤも…彼らと会ったのか？",
  ui_story_5051_50510901_79_dialog_content = "「彼ら」とは…？",
  ui_story_5051_50510901_80_dialog_content = "お主は分かっているはずだ。",
  ui_story_5051_50510901_81_dialog_content = "コホン…ヨシュア夫人とカレン、\nそれからこの世界のソルラドさんのことを言ってるんでしたら…",
  ui_story_5051_50510901_82_dialog_content = "答えは「はい」です。皆ミヤを受け入れてくれて、ずっと「ヴェロニカ」と呼んでます。",
  ui_story_5051_50510901_83_dialog_content = "ミヤの今の容貌は当時と全く変わらぬのだ。",
  ui_story_5051_50510901_84_dialog_content = "ということは…認めるんですね？",
  ui_story_5051_50510901_85_dialog_content = "ミヤは「ヴェロニカ」殿下で、ソルラドさんの娘だと。",
  ui_story_5051_50510901_86_dialog_content = "…この世界はすでに我々の言動によって乱されてしまっておる。",
  ui_story_5051_50510901_87_dialog_content = "お主は何ゆえミヤに危険を冒してまで衛兵と勝負させたのだ？",
  ui_story_5051_50510901_88_dialog_content = "ケガをしたらどうするか、考えなかったか？",
  ui_story_5051_50510901_89_dialog_content = "ミヤは白夜城城主の娘なのに、気のおかしくなった病人として、\nずっと影ノ街に身を隠してました…",
  ui_story_5051_50510901_90_dialog_content = "ミヤのお父さんは考えなかったんでしょうか？\nミヤが影ノ街でケガをしたら、どうするか…",
  ui_story_5051_50510901_91_dialog_content = "若者よ、覚えておくがよい。",
  ui_story_5051_50510901_92_dialog_content = "事情を知らぬのなら、軽々しく評価の言葉を口にするでない。",
  ui_story_5051_50510901_93_dialog_content = "すみませんでした。僕は確かにあなたたち親子の間で何があったのか知りません。",
  ui_story_5051_50510901_94_dialog_content = "でも、ソルラドさんもミヤの本当の力を知りません。",
  ui_story_5051_50510901_95_dialog_content = "ほう？",
  ui_story_5051_50510901_96_dialog_content = "素晴らしい剣術だ！",
  ui_story_5051_50510901_97_dialog_content = "ヴェロニカ殿下！ヴェロニカ殿下！ヴェロニカ殿下！",
  ui_story_5051_50510901_98_dialog_content = "見てください。ミヤの戦いは会場全体から歓声を送られてます。",
  ui_story_5051_50510901_99_dialog_content = "かつてのミヤは戦闘が苦手であったが…",
  ui_story_5051_50510901_100_dialog_content = "今のミヤはこれ程までに強大な力をつけていたのか…",
  ui_story_5051_50510901_101_dialog_content = "ミヤはこの機会に自分はもっと色々なことができるんだって、\nソルラドさんに知ってもらいたいんです。",
  ui_story_5051_50510901_102_dialog_content = "だが、今はその時ではない。",
  ui_story_5051_50510901_103_dialog_content = "PlayerName、すぐにでもミヤのこの試合を終わらせるよう手を尽くせ。",
  ui_story_5051_50510901_104_dialog_content = "どうしてですか？僕には分かりません。だって、ミヤはもうすぐ勝ちますよ？",
  ui_story_5051_50510901_105_dialog_content = "ミヤのこと信じられないんですか？",
  ui_story_5051_50510901_106_dialog_content = "PlayerName、当時この儀式で何が起こったか、知っておるか？",
  ui_story_5051_50510901_107_dialog_content = "えっ？",
  ui_story_5051_50510901_108_dialog_content = "ヴェロニカ殿下、こうなっては私も全力を出させていただきます！",
  ui_story_5051_50510901_109_dialog_content = "ええ…手加減はしないで。",
  ui_story_5051_50510901_110_dialog_content = "はぁっ！",
  ui_story_5051_50510901_111_dialog_content = "<color=#e8d9bb>カンッ！</color>",
  ui_story_5051_50510901_112_dialog_content = "なんですと？これも受け止めますか？",
  ui_story_5051_50510901_113_dialog_content = "…危なかったわ。",
  ui_story_5051_50510901_114_dialog_content = "（今の攻撃はすごい力だった。ぎりぎりで受け止められたけど…）",
  ui_story_5051_50510901_115_dialog_content = "（PlayerNameは見てたかしら？）",
  ui_story_5051_50510901_116_dialog_content = "（あら、PlayerNameはどこに行ったの？）",
  ui_story_5051_50510901_117_dialog_content = "（いたわ！でも、そばにいるのって…）",
  ui_story_5051_50510901_118_dialog_content = "お姉様、危ない！",
  ui_story_5051_50510901_119_dialog_content = "はぁっ――！",
  ui_story_5051_50510901_120_dialog_content = "（どうすればいいの！？こ、これは…受け止めきれない）",
  ui_story_5051_50510901_121_dialog_content = "（逃げる？いえ、ダメよ。お父様が見てるんだもの、もし逃げたりしたら…）",
  ui_story_5051_50510901_122_dialog_content = "（そうよ、まだ時間はある。力を貯めて、反撃よ！）",
  ui_story_5051_50510901_123_dialog_content = "もしや<color=#FFB400>あれ</color>を出そうとしてるのではあるまいな？",
  ui_story_5051_50510901_124_dialog_content = "ヴェロニカ…",
  ui_story_5051_50510901_125_dialog_content = "（ダメよ！お父様は私がヒポカを召喚するのを嫌っていた。どうして忘れてたの？）",
  ui_story_5051_50510901_126_dialog_content = "（でも、今の貯めきった力じゃ…衛兵を傷つけてしまうわ）",
  ui_story_5051_50510901_127_dialog_content = "（どうしよう？どうしたらいいの？）",
  ui_story_5051_50510901_128_dialog_content = "（あっちに置いてある木箱は何かしら？\nあの箱なら、私のこの力を受け止められるかも？）",
  ui_story_5051_50510901_129_dialog_content = "どうしたんだろう？ミヤはどうして端に向かっていくの？",
  ui_story_5051_50510901_130_dialog_content = "あと少しで、召喚物を出せるところだったのに！",
  ui_story_5051_50510901_131_dialog_content = "…",
  ui_story_5051_50510901_132_dialog_content = "ヴェロニカ、この先二度と怪物を召喚するでない。",
  ui_story_5051_50510901_133_dialog_content = "ヒポカは…ヒポカは怪物ではありません。",
  ui_story_5051_50510901_134_dialog_content = "馬の頭をしたクモに名前まで付けていたのか？",
  ui_story_5051_50510901_135_dialog_content = "カレンにも白馬がいるではありませんか。",
  ui_story_5051_50510901_136_dialog_content = "ヴェロニカ、お前は戦いの才に恵まれておらぬ。これ以上の執着は無用だ。",
  ui_story_5051_50510901_137_dialog_content = "えっ…",
  ui_story_5051_50510901_138_dialog_content = "どうやら…覚えていたようだな。",
  ui_story_5051_50510901_139_dialog_content = "ミヤが木箱にぶつかっていく！",
  ui_story_5051_50510901_140_dialog_content = "なに！？",
  ui_story_5051_50510901_141_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5051_50510901_142_dialog_content = "<anim type=Shake>グォォ――！</anim>",
  ui_story_5051_50510901_143_dialog_content = "暗鬼？暗鬼だ！",
  ui_story_5051_50510901_144_dialog_content = "飾り用の木箱の中にどうして暗鬼なんか潜んでたんだ？",
  ui_story_5051_50510901_145_dialog_content = "逃げろ！",
  ui_story_5051_50510901_146_dialog_content = "え…ど、どうして？",
  ui_story_5051_50510901_147_dialog_content = "私の…私のせいなの？",
  ui_story_5051_50510901_148_dialog_content = "<anim type=Shake>グォォ――！</anim>",
  ui_story_5051_50510901_149_dialog_content = "わ、私がでしゃばって出てきたから…",
  ui_story_5051_50510901_150_dialog_content = "どうして何かしようとすると、いつもこうなるの？",
  ui_story_5051_50510901_151_dialog_content = "いつも、悪い結果にしかならない…",
  ui_story_5051_50510901_152_dialog_content = "騎士団に入りたいと？ヴェロニカ、余はお前が人より抜きんでることなど望んでおらぬ。\nただ母上にだけは心配をかけるな。",
  ui_story_5051_50510901_153_dialog_content = "殿下、私どもと一緒に戦いに出る必要はございません。\n安全な所でお待ちいただければ結構です。",
  ui_story_5051_50510901_154_dialog_content = "ヴェロニカ、どうしたの…？",
  ui_story_5051_50510901_155_dialog_content = "いやあぁぁ――！",
  ui_story_5051_50510901_156_dialog_content = "全部、私…私のせいなんだわ…",
  ui_story_5051_50510901_157_dialog_content = "敵から目をそらさず、後退せよ！",
  ui_story_5051_50510901_158_dialog_content = "えっ？",
  ui_story_5051_50510901_159_dialog_content = "<anim type=Shake>グオオオ！！</anim>",
  ui_story_5051_50510901_160_dialog_content = "支配者の刃！",
  ui_story_5051_50510901_161_dialog_content = "お父様？ほ、本物のお父様？",
  ui_story_5051_50510901_162_dialog_content = "ミヤ、大丈夫？",
  ui_story_5051_50510901_163_dialog_content = "PlayerName…私は大丈夫よ。ただちょっと気が散ってしまっただけ。",
  ui_story_5051_50510901_164_dialog_content = "まことに大事ないか？",
  ui_story_5051_50510901_165_dialog_content = "だ、大丈夫です！",
  ui_story_5051_50510901_166_dialog_content = "よし、では余と共に突破せよ。",
  ui_story_5051_50510901_167_dialog_content = "初めてです。お父様と一緒に戦うのは、これが初めてです。",
  ui_story_5051_50510901_168_dialog_content = "それから…",
  ui_story_5051_50510901_169_dialog_content = "ヒポカを召喚したいのであれば、召喚すればよい。",
  ui_story_5051_50510901_170_dialog_content = "え、お父様？",
  ui_story_5051_50510901_171_dialog_content = "準備はよいか？",
  ui_story_5051_50510901_172_dialog_content = "…はい！",
  ui_story_5051_50510901_173_dialog_content = "<color=#e8d9bb>一方で</color>",
  ui_story_5051_50510901_174_dialog_content = "あの黒い怪物は…暗鬼なの！？",
  ui_story_5051_50510901_175_dialog_content = "お母様、カレンが皆を守ります！",
  ui_story_5051_50510901_176_dialog_content = "カレン、あなたにはその力があるって信じてるわ。\nでも、今はまだその時じゃないの。分かるわね？",
  ui_story_5051_50510901_177_dialog_content = "…はい。",
  ui_story_5051_50510901_178_dialog_content = "ヨシュア、Ms.ロトがお主とカレンを守る。急いで逃げよ！",
  ui_story_5051_50510901_179_dialog_content = "ダニエル、わたくしも…",
  ui_story_5051_50510901_180_dialog_content = "ヨシュア、安心せよ。",
  ui_story_5051_50510901_181_dialog_content = "余が必ず無事にヴェロニカを連れて帰る。",
  ui_story_5051_50510901_182_dialog_content = "わたくしはあなたにもあの子にも無事に帰ってきていただきたいの。",
  ui_story_5051_50510901_183_dialog_content = "<anim type=Shake>グオオオ！</anim>",
  ui_story_5051_50510901_184_dialog_content = "一切を支配する！",
  ui_story_5051_50510901_185_dialog_content = "すでにここまで来たか。",
  ui_story_5051_50510901_186_dialog_content = "フッ、自ら苦しみを求めるのなら、余がその願いをかなえてやろう。",
  ui_story_5051_50511001_1_dialog_content = "インヴェニレエウム～、インヴェニレエウム～、インヴェニレエウム。",
  ui_story_5051_50511001_2_dialog_content = "どうか教えてください。私の思う城主様は今どこにいるんですか？",
  ui_story_5051_50511001_3_dialog_content = "<size=42>アブラカダブラ！</size>",
  ui_story_5051_50511001_4_dialog_content = "<color=#e8d9bb>ウオーン…</color>",
  ui_story_5051_50511001_5_dialog_content = "わ、水晶玉がこんなに激しく答えてくれるのは初めてです！",
  ui_story_5051_50511001_6_dialog_content = "どうやら私は今まで本当に、最後の呪文をとなえ間違えてたんですね？",
  ui_story_5051_50511001_7_dialog_content = "でも、やっぱり不思議です…",
  ui_story_5051_50511001_8_dialog_content = "呪文をとなえるたびに、なんで最後に「アブラカダブラ」をつけなきゃいけないんです？",
  ui_story_5051_50511001_9_dialog_content = "「アブラカダブラ」って言葉に何か特別な意味でもあるんですか？",
  ui_story_5051_50511001_10_dialog_content = "えーっと、なんて意味だったかしら…",
  ui_story_5051_50511001_11_dialog_content = "ああ、思い出したわ～。",
  ui_story_5051_50511001_12_dialog_content = "「言うこと聞かないなら、消してやる」って意味よ！",
  ui_story_5051_50511001_13_dialog_content = "え――！？",
  ui_story_5051_50511001_14_dialog_content = "アハハハ、そんなに驚いちゃって、あなた面白いわね。アハハハ。",
  ui_story_5051_50511001_15_dialog_content = "何です？私をバカにしてるんですか？",
  ui_story_5051_50511001_16_dialog_content = "<size=30>小さい頃の優しいママの思い出は、\n本当は私が頭の中で勝手に作り上げたものだったんでしょうか…</size>",
  ui_story_5051_50511001_17_dialog_content = "ちょっと、何をブツブツ言ってるの？\nそろそろ水晶玉に応えてあげないと、情報が消えちゃうわよ。",
  ui_story_5051_50511001_18_dialog_content = "あ、一番大事なことを忘れるところでした！",
  ui_story_5051_50511001_19_dialog_content = "水晶玉の情報では…",
  ui_story_5051_50511001_20_dialog_content = "城主様はPlayerNameとミヤと同じ方角にいるんですか？",
  ui_story_5051_50511001_21_dialog_content = "もう合流してたんですね。",
  ui_story_5051_50511001_22_dialog_content = "…ってことは、私一人ここでだいぶ時間を無駄にしてたんですね？",
  ui_story_5051_50511001_23_dialog_content = "時間のムダなんかじゃないでしょ～？",
  ui_story_5051_50511001_24_dialog_content = "私だけの呪文を教えてあげたのよ～！？",
  ui_story_5051_50511001_25_dialog_content = "それもそうですね！",
  ui_story_5051_50511001_26_dialog_content = "初めて探してる人の位置を正確に占えました！",
  ui_story_5051_50511001_27_dialog_content = "ただ…",
  ui_story_5051_50511001_28_dialog_content = "「アブラカダブラ」って、いったいどういう意味なんです？",
  ui_story_5051_50511001_29_dialog_content = "ああ、頭が痛いわ～！",
  ui_story_5051_50511001_30_dialog_content = "おいしいものを飲ませてくれなきゃ思い出せないわ。",
  ui_story_5051_50511001_31_dialog_content = "もうっ、またですか？",
  ui_story_5051_50511001_32_dialog_content = "ここならもう大丈夫だろう？",
  ui_story_5051_50511001_33_dialog_content = "いや、もう少し遠くへ逃げよう、急げ！",
  ui_story_5051_50511001_34_dialog_content = "あれれ？人がなんで急に広場から逃げてきてるんです？",
  ui_story_5051_50511001_35_dialog_content = "落ち着くのだ、転ばないように気を付けろ！",
  ui_story_5051_50511001_36_dialog_content = "騎士さん、聞きたいことがあるんですけど…",
  ui_story_5051_50511001_37_dialog_content = "何だ？",
  ui_story_5051_50511001_38_dialog_content = "わぁ、私より年下みたいですね？",
  ui_story_5051_50511001_39_dialog_content = "何か用か？",
  ui_story_5051_50511001_40_dialog_content = "えーと、広場で何があったのか聞きたいんです。",
  ui_story_5051_50511001_41_dialog_content = "詳しいことは私にも分からない。ただ、上から避難誘導するよう命令が下った。",
  ui_story_5051_50511001_42_dialog_content = "でも…広場に知人がいるんです！",
  ui_story_5051_50511001_43_dialog_content = "待て、その風貌は…",
  ui_story_5051_50511001_44_dialog_content = "アハハ、みんなからママ…いえ、ボアーズによく似てるって言われるんです。",
  ui_story_5051_50511001_45_dialog_content = "赤い髪に緑色の瞳…あなたはジャキーニか？",
  ui_story_5051_50511001_46_dialog_content = "え？なんで私の名前を知ってるんです？",
  ui_story_5051_50511001_47_dialog_content = "ままままま、待ってください！\nまさか、あなたもうっかり中に入ってきちゃったんですか？",
  ui_story_5051_50511001_48_dialog_content = "すまないが、何を言っているのか分からない。",
  ui_story_5051_50511001_49_dialog_content = "私はただ少し前にヴェロニカ殿下の友人であるPlayerNameから、\nあなたと2人の男の行方を探すように頼まれたのだ。",
  ui_story_5051_50511001_50_dialog_content = "そうです！私もPlayerNameを探しに行くんです！",
  ui_story_5051_50511001_51_dialog_content = "でも、まだ中央広場にいるみたいなんですよ。",
  ui_story_5051_50511001_52_dialog_content = "まずは私に付いて来い。\nここが落ち着いたら、PlayerNameを探しに連れて行ってやる。",
  ui_story_5051_50511001_53_dialog_content = "ありがとうございます。でも…",
  ui_story_5051_50511001_54_dialog_content = "おそらくそれでは間に合いません。一刻も早くみんなと合流しなきゃいけないんです！",
  ui_story_5051_50511001_55_dialog_content = "つまりあなたは、酒に酔った女を連れて、\n暗鬼が暴れている所に入っていこうというのか？",
  ui_story_5051_50511001_56_dialog_content = "暗鬼？",
  ui_story_5051_50511001_57_dialog_content = "ちょっとちょっと、私は酔ってないわよ！",
  ui_story_5051_50511001_58_dialog_content = "うーん…それは確かによくありませんね。",
  ui_story_5051_50511001_59_dialog_content = "だったら、騎士さん、この人を見ててもらえます？",
  ui_story_5051_50511001_60_dialog_content = "1人で広場に探しに行くつもりか？",
  ui_story_5051_50511001_61_dialog_content = "えへへ、私こんな見た目ですけど、暗鬼くらいなんてことないんです。",
  ui_story_5051_50511001_62_dialog_content = "なんて子なの…芸を盗むだけ盗んだら、あとは放ったらかしなのね。",
  ui_story_5051_50511001_63_dialog_content = "この私、ボアーズが、暗鬼なんて怖がると思う？",
  ui_story_5051_50511001_64_dialog_content = "正しい呪文の唱え方を教えてくれてありがとうございました！",
  ui_story_5051_50511001_65_dialog_content = "ほんのわずかな時間でしたが、会えただけで満足です。できることなら…",
  ui_story_5051_50511001_66_dialog_content = "私だって、ここで別れたくありません。",
  ui_story_5051_50511001_67_dialog_content = "でも…友だちを放っておくことなんて、できないんです！",
  ui_story_5051_50511001_68_dialog_content = "私のせいで…みんなが今危険な目に遭ってるんですから。",
  ui_story_5051_50511001_69_dialog_content = "何を言ってるのか分からないわ…とにかく、連れて行って！",
  ui_story_5051_50511001_70_dialog_content = "もう占いを教わらなくていいの？それに…私はまだ飲み足りないわ！",
  ui_story_5051_50511001_71_dialog_content = "…",
  ui_story_5051_50511001_72_dialog_content = "このような危機を前にしながら、友を想うとは。\nジャキーニ、あなたに敬意を表しよう。",
  ui_story_5051_50511001_73_dialog_content = "実は私も広場に応援に駆け付けたいと思っていたのだ。",
  ui_story_5051_50511001_74_dialog_content = "あなたたちがどうしても広場に行くというのなら、私が送っていってやろう。",
  ui_story_5051_50511001_75_dialog_content = "え？本当ですか？",
  ui_story_5051_50511001_76_dialog_content = "付いて来い。私が前方より迫る暗鬼を片付ける！",
  ui_story_5051_50511002_1_dialog_content = "状況はどうだ？",
  ui_story_5051_50511002_2_dialog_content = "この近くの暗鬼は片づけたと思います。",
  ui_story_5051_50511002_3_dialog_content = "よろしい。",
  ui_story_5051_50511002_4_dialog_content = "この先に小道がある。暗鬼が暴れている地区を抜ける近道だ。",
  ui_story_5051_50511002_5_dialog_content = "余の後に付いて来い。",
  ui_story_5051_50511002_6_dialog_content = "え？今ですか？",
  ui_story_5051_50511002_7_dialog_content = "お前はもう長い間戦い続けておる。休まねばならぬ。",
  ui_story_5051_50511002_8_dialog_content = "でも…",
  ui_story_5051_50511002_9_dialog_content = "「でも」は許さぬ。",
  ui_story_5051_50511002_10_dialog_content = "ここで時間と力を無為に使ってはならぬぞ。",
  ui_story_5051_50511002_11_dialog_content = "わ、私はみんなのためにもっと暗鬼を倒したいんです…",
  ui_story_5051_50511002_12_dialog_content = "<size=45>あきらめるのだ、急げ！</size>",
  ui_story_5051_50511002_13_dialog_content = "えっ？",
  ui_story_5051_50511002_14_dialog_content = "ヴェロニカ、お前は戦いの才に恵まれておらぬ。これ以上の執着は無用だ。",
  ui_story_5051_50511002_15_dialog_content = "うっ…",
  ui_story_5051_50511002_X15_dialog_content = "（ミヤの今の表情、決闘の前とそっくりだ）",
  ui_story_5051_50511002_X16_dialog_content = "（まさか、また何か良くないことを思い出したの？）",
  ui_story_5051_50511002_16_dialog_content = "ミヤ、何か思い出したの？",
  ui_story_5051_50511002_17_dialog_content = "ご、ごめんなさい！",
  ui_story_5051_50511002_18_dialog_content = "私がいけないの。全部、私のせいよ…",
  ui_story_5051_50511002_19_dialog_content = "ソルラドさん、今の言葉がミヤを刺激したんじゃないでしょうか？",
  ui_story_5051_50511002_20_dialog_content = "ミヤの病状は良くなってきたばかりなんです。過度の刺激には耐えられないんです。",
  ui_story_5051_50511002_21_dialog_content = "…",
  ui_story_5051_50511002_22_dialog_content = "わ、私はやっぱりお父様に満足していただけない…",
  ui_story_5051_50511002_23_dialog_content = "わ、私はお父様の娘失格なんだわ。娘失格なの。",
  ui_story_5051_50511002_X21_dialog_content = "家庭内のことに僕が口出しすべきじゃないってことは分かってます。",
  ui_story_5051_50511002_X22_dialog_content = "でも、子どもが自分のお父さんをこんなに怖がるなんて、普通じゃないと思うんです。",
  ui_story_5051_50511002_24_dialog_content = "ソルラドさん、ミヤはどうしてこんなにあなたを怖がるんですか？",
  ui_story_5051_50511002_25_dialog_content = "それは…",
  ui_story_5051_50511002_26_dialog_content = "ミヤを長い間影ノ街に放っておいたからですか？",
  ui_story_5051_50511002_27_dialog_content = "ミヤを放っておいたことなどない！",
  ui_story_5051_50511002_28_dialog_content = "…お主が知る必要のないことだ。",
  ui_story_5051_50511002_X28_dialog_content = "余の家庭にお主がとやかく言う資格はない。",
  ui_story_5051_50511002_X29_dialog_content = "お父様、PlayerNameにそんなにきつく当たらないでください…",
  ui_story_5051_50511002_X30_dialog_content = "お前は黙っていなさい。余とてわきまえている。",
  ui_story_5051_50511002_X31_dialog_content = "いいえ、お父様、そんな風に…きつく当たらないでください！",
  ui_story_5051_50511002_X32_dialog_content = "ミヤ…？",
  ui_story_5051_50511002_X33_dialog_content = "「白夜城城主」、「一族を守る者」…お父様には立派な肩書がたくさんあります。",
  ui_story_5051_50511002_X34_dialog_content = "でも、私には…そんなもの、息苦しいものでしかないんです。",
  ui_story_5051_50511002_X35_dialog_content = "他の人たちにとって、お父様は偉大で、貴い存在なのかもしれません。",
  ui_story_5051_50511002_X36_dialog_content = "でも、私の知ってるお父様は、いつだって声を荒立てて、周りの人を傷つけばかり…",
  ui_story_5051_50511002_X37_dialog_content = "…",
  ui_story_5051_50511002_29_dialog_content = "家庭内のことに僕が口出しすべきじゃないってことは分かってます。",
  ui_story_5051_50511002_30_dialog_content = "でも、ミヤにはあなたの答えが必要なんです！",
  ui_story_5051_50511002_31_dialog_content = "…",
  ui_story_5051_50511002_32_dialog_content = "全部私のせいよ。私はみんなの足を引っ張ってばかり…",
  ui_story_5051_50511002_33_dialog_content = "ミヤ、聞いて。絶対にそんなことないよ！",
  ui_story_5051_50511002_34_dialog_content = "わかってるわ。慰めてくれなくていいの。私がみんなをこんな目に遭わせたんだから。",
  ui_story_5051_50511002_35_dialog_content = "さっき、私が木箱を壊さなかったら、暗鬼なんて出てこなかった…",
  ui_story_5051_50511002_36_dialog_content = "あの暗鬼は反乱を企む人たちがわざと箱の中に隠してたんだよ。\nミヤとは何の関係もないんだ！",
  ui_story_5051_50511002_37_dialog_content = "逆にミヤはずっと皆を助けてるんだよ！",
  ui_story_5051_50511002_38_dialog_content = "私が…みんなを助けてる？",
  ui_story_5051_50511002_39_dialog_content = "城外で、君は僕を暗鬼から救ってくれた。",
  ui_story_5051_50511002_40_dialog_content = "城内に入ってからも、みんなを助けて城内に紛れこもうとした暗鬼を阻止したでしょ。",
  ui_story_5051_50511002_41_dialog_content = "それから今も、戦う術のないたくさんの一般市民を暗鬼から救ったじゃないか。",
  ui_story_5051_50511002_42_dialog_content = "ミヤ、それでも君は自分に力がないって言うの？",
  ui_story_5051_50511002_43_dialog_content = "そ、それはみんな偶然で…ただ運が良かっただけよ。",
  ui_story_5051_50511002_44_dialog_content = "ミヤ、どうして僕の言うことを信じてくれないの？",
  ui_story_5051_50511002_45_dialog_content = "ソルラドさんは僕よりも色々なことを知ってますよね。",
  ui_story_5051_50511002_46_dialog_content = "ミヤに話したいことがたくさんあるはずです。",
  ui_story_5051_50511002_47_dialog_content = "…",
  ui_story_5051_50511002_X38_dialog_content = "い、今いったことが私の正直な気持ちです。",
  ui_story_5051_50511002_X39_dialog_content = "もしお怒りになったのなら、私をお叱りになればいい…\n私の友だちを困らせないでください！",
  ui_story_5051_50511002_48_dialog_content = "うう…",
  ui_story_5051_50511002_49_dialog_content = "お前は、恐れておるのか？",
  ui_story_5051_50511002_50_dialog_content = "わ、私は…「怖い」なんて言っちゃいけないんです。",
  ui_story_5051_50511002_51_dialog_content = "長女ですもの。何でも一番できなくちゃ、お父様はがっかりなさいます。",
  ui_story_5051_50511002_52_dialog_content = "私の好きな音楽や美術も、私の苦手な政や戦闘も…",
  ui_story_5051_50511002_53_dialog_content = "全部上手にできなきゃいけないんです。",
  ui_story_5051_50511002_54_dialog_content = "ああ、我が娘よ。お前はすでによくやっておる。",
  ui_story_5051_50511002_55_dialog_content = "でも、私はまだお父様のお力になれていません。",
  ui_story_5051_50511002_56_dialog_content = "私、思い出したんです。全部思い出したんです。",
  ui_story_5051_50511002_57_dialog_content = "昔私は勇気を出して騎士団に入りました。でも、すぐに暗鬼との戦闘でケガをしました。",
  ui_story_5051_50511002_58_dialog_content = "その後…お母様が助けてくださったんでしょう？",
  ui_story_5051_50511002_59_dialog_content = "何もできないばかりか、面倒を増やしてばかりです。",
  ui_story_5051_50511002_60_dialog_content = "それに今も…私が何もかも台無しにしたんですよね？",
  ui_story_5051_50511002_61_dialog_content = "そうじゃなかったら…お父様がお怒りになるはずないもの…\n私にここを離れるようにおっしゃるはずありません。",
  ui_story_5051_50511002_X61_dialog_content = "私があまりにも役立たずだから…\nだからお父様はずっとお怒りになっているんだわ、そうですよね…？",
  ui_story_5051_50511002_62_dialog_content = "ミヤ、さような意味で言ったのではない。",
  ui_story_5051_50511002_63_dialog_content = "お父様はまた…私を<color=#FFB400>遠い所</color>へおやりになるのですか？",
  ui_story_5051_50511002_64_dialog_content = "！！！",
  ui_story_5051_50511002_65_dialog_content = "お前を影ノ街に送り、身元を隠して治療を受けさせたのは、\n余とて苦渋の選択だったのだ。",
  ui_story_5051_50511002_66_dialog_content = "だが、認めよう。あの時余もあまりにも若すぎた。",
  ui_story_5051_50511002_67_dialog_content = "もし再びやり直せるのなら、必ずや万全の策を探し出すだろう。",
  ui_story_5051_50511002_68_dialog_content = "今さらこのようなことを言ったとて遅いのは分かっておる。\nだがあれは…確かに余の成した最悪の決断の一つだ。",
  ui_story_5051_50511002_69_dialog_content = "長い間、お前ひとりに苦しみを背負わせてしまった。",
  ui_story_5051_50511002_70_dialog_content = "お父様…",
  ui_story_5051_50511002_71_dialog_content = "わ、私…お母様とカレンが…お父様のことが…ずっと恋しかったんです。",
  ui_story_5051_50511002_72_dialog_content = "分かっておる、我が娘よ。",
  ui_story_5051_50511002_73_dialog_content = "お前が影ノ街で暮らしている間、イスタバンが余にお前の様子を知らせてくれていた。",
  ui_story_5051_50511002_74_dialog_content = "病状が良くなってきているのは知っておった。\nいつか全てを話せる日も来ようと思っていたのだが…",
  ui_story_5051_50511002_75_dialog_content = "まさか、このような事態に巻き込まれるとは…",
  ui_story_5051_50511002_76_dialog_content = "約束する。元の世界に戻ったら、真実を全て話そう。\nだが、今はここを離れることが先決だ。",
  ui_story_5051_50511002_77_dialog_content = "ええと…その…",
  ui_story_5051_50511002_79_dialog_content = "で、でも、ここを離れたら私はもう二度とお母様に会えないんですよね？",
  ui_story_5051_50511002_80_dialog_content = "…",
  ui_story_5051_50511002_81_dialog_content = "私のせいですか？",
  ui_story_5051_50511002_82_dialog_content = "お母様は、私のせいでお亡くなりになったんですか？",
  ui_story_5051_50511002_83_dialog_content = "その事は後で改めて話すとしよう。",
  ui_story_5051_50511002_84_dialog_content = "まずはここを離れねば。",
  ui_story_5051_50511002_85_dialog_content = "ここを…離れる？",
  ui_story_5051_50511002_86_dialog_content = "お前に何かあっては困るのだ。よいな？",
  ui_story_5051_50511002_87_dialog_content = "…はい。",
  ui_story_5051_50511002_88_dialog_content = "さあ、立てるか？",
  ui_story_5051_50511002_89_dialog_content = "さあ、手を。共にここを離れよう。",
  ui_story_5051_50511002_90_dialog_content = "<color=#e8d9bb>シュッ！</color>",
  ui_story_5051_50511002_91_dialog_content = "むむ？",
  ui_story_5051_50511002_92_dialog_content = "これはいったい…どういう状況？",
  ui_story_5051_50511002_93_dialog_content = "お父様！",
  ui_story_5051_50511002_94_dialog_content = "ヴェロニカ、その者から離れるのだ。",
  ui_story_5051_50511002_95_dialog_content = "お前を連れ去ろうとする賊だ、近づくでない！",
  ui_story_5051_50511002_96_dialog_content = "…",
  ui_story_5051_50511002_97_dialog_content = "（若い頃のソルラドさんは相手が自分だってことに気づいてないの！？）",
  ui_story_5051_50511002_98_dialog_content = "（でも…それもそうか…）",
  ui_story_5051_50511002_99_dialog_content = "（僕だって事情を知らなかったら、目の前の2人が同一人物だなんて信じられないから）",
  ui_story_5051_50511002_100_dialog_content = "ソルラドの娘をさらう度胸がありながら…",
  ui_story_5051_50511002_101_dialog_content = "何ゆえ余と正々堂々戦わぬ？",
  ui_story_5051_50511002_102_dialog_content = "不必要な誤解は避けたいだけだ。",
  ui_story_5051_50511002_103_dialog_content = "不必要な誤解だと？",
  ui_story_5051_50511002_104_dialog_content = "お主などと会ったことはない。",
  ui_story_5051_50511002_105_dialog_content = "トロイ家の者か？いや、そうではないな。",
  ui_story_5051_50511002_106_dialog_content = "では、カルティマ家の者か？",
  ui_story_5051_50511002_107_dialog_content = "そのいずれでもない。余はヴェロニカの…",
  ui_story_5051_50511002_108_dialog_content = "友だ。",
  ui_story_5051_50511002_109_dialog_content = "友だと？",
  ui_story_5051_50511002_110_dialog_content = "友の友は、友だ。",
  ui_story_5051_50511002_111_dialog_content = "面白いことを言うではないか。だが残念だ。\n余は「敵の敵は味方」という言葉しか知らぬ。",
  ui_story_5051_50511002_112_dialog_content = "今、知ったではないか。",
  ui_story_5051_50511002_113_dialog_content = "その口ぶりでは、余の友になりたいとは思えぬな。",
  ui_story_5051_50511002_114_dialog_content = "お父様、この人は本当に…私が影ノ街で知り合った友人なんです。",
  ui_story_5051_50511002_115_dialog_content = "さっきも私を助けてくれました。",
  ui_story_5051_50511002_116_dialog_content = "そやつはよりによって暗鬼が現れた時に姿を現した。",
  ui_story_5051_50511002_117_dialog_content = "偶然にも程があろう。",
  ui_story_5051_50511002_118_dialog_content = "ヴェロニカ、今後友人をつくる時は母上に相談してからにするがよい。",
  ui_story_5051_50511002_119_dialog_content = "…",
  ui_story_5051_50511002_120_dialog_content = "（…うーん、ソルラドさんはきっと若い時の自分にすごく腹を立ててるだろうな）",
  ui_story_5051_50511002_121_dialog_content = "（でも、このままじゃらちが明かない…）",
  ui_story_5051_50511002_122_dialog_content = "（かといって、若い時のソルラドさんに\n「この人は10数年後のあなたです」って言うわけにもいかないし…）",
  ui_story_5051_50511002_123_dialog_content = "（一か八かやってみるしかない…）",
  ui_story_5051_50511002_124_dialog_content = "実は！",
  ui_story_5051_50511002_125_dialog_content = "むむ？",
  ui_story_5051_50511002_126_dialog_content = "ソルラドさん、どうか許してください。",
  ui_story_5051_50511002_127_dialog_content = "実はこの人は僕の父…ソロスです。",
  ui_story_5051_50511002_128_dialog_content = "ヴェロニカ殿下と白夜城に戻ることを僕が話してなくて…",
  ui_story_5051_50511002_129_dialog_content = "それで人づてに聞いて、白夜城まで探しにきてくれたんです。",
  ui_story_5051_50511002_130_dialog_content = "でも、まさか会った途端に暗鬼の襲撃に遭うとは…",
  ui_story_5051_50511002_131_dialog_content = "そ、そうなんです！",
  ui_story_5051_50511002_132_dialog_content = "ハハハ、言ったであろう。誤解であると。",
  ui_story_5051_50511002_133_dialog_content = "いずれにせよ、貴殿とご家族にはPlayerNameが世話になった。感謝する。",
  ui_story_5051_50511002_134_dialog_content = "さようか。ならば、我々のもてなしに落ち度があったようだ。",
  ui_story_5051_50511002_135_dialog_content = "ただ…",
  ui_story_5051_50511002_136_dialog_content = "まだ、信じられぬと？",
  ui_story_5051_50511002_137_dialog_content = "PlayerNameはヴェロニカとほぼ変わらぬ年頃であろう？",
  ui_story_5051_50511002_138_dialog_content = "PlayerNameの祖父殿かと思ったのだが。",
  ui_story_5051_50511002_139_dialog_content = "ハハハ…若者よ。",
  ui_story_5051_50511002_140_dialog_content = "貴殿のおかげで、\n余が若い頃いかに他人に嫌われる存在であったか解せた気がする。感謝する。",
  ui_story_5051_50511002_141_dialog_content = "左様であろうな。",
  ui_story_5051_50511002_142_dialog_content = "幸い、これ程の歳になると、細かいことは気にならなくなるものだ。",
  ui_story_5051_50511002_143_dialog_content = "余の予想が確かならば、貴殿にはまだやらねばならぬことがあるのだろう？",
  ui_story_5051_50511002_144_dialog_content = "それがいかがしたのだ？",
  ui_story_5051_50511002_145_dialog_content = "こう見えても、暗鬼との戦いには経験があるのだ。",
  ui_story_5051_50511002_146_dialog_content = "余がヴェロニカとPlayerNameを安全な所まで連れて行こう。",
  ui_story_5051_50511002_147_dialog_content = "気遣いに感謝する。",
  ui_story_5051_50511002_148_dialog_content = "だが、ヴェロニカは我が娘だ。",
  ui_story_5051_50511002_149_dialog_content = "我が娘は余が責任をもって守ろう。",
  ui_story_5051_50511002_150_dialog_content = "他人の手を借りるつもりはない。",
  ui_story_5051_50511002_151_dialog_content = "…",
  ui_story_5051_50511002_152_dialog_content = "<color=#FFB400>お父様</color>…",
  ui_story_5051_50511002_153_dialog_content = "（今のは…）",
  ui_story_5051_50511002_154_dialog_content = "（どっちの「<color=#FFB400>お父様</color>」だろう？）",
  ui_story_5051_50511101_1_dialog_content = "水晶玉の反応が激しくなってきてますよ。",
  ui_story_5051_50511101_2_dialog_content = "PlayerNameたちはきっとこの近くにいるはずです！",
  ui_story_5051_50511101_3_dialog_content = "静かだ。",
  ui_story_5051_50511101_4_dialog_content = "本当ですね…途中の「にぎやか」な様子とはまったく違います。",
  ui_story_5051_50511101_5_dialog_content = "ねえ、にぎやかな所に行って遊びましょうよ！",
  ui_story_5051_50511101_6_dialog_content = "ここはさみしすぎるわ。",
  ui_story_5051_50511101_7_dialog_content = "おいしいお酒なんて到底手に入りそうもないもの～。",
  ui_story_5051_50511101_8_dialog_content = "オホン。私たちは遊びに来たんじゃありません。",
  ui_story_5051_50511101_9_dialog_content = "あら、弟子にもなってないのに、私をだまそうたって、そうはいかないわよ。",
  ui_story_5051_50511101_10_dialog_content = "さっきの黒い礼服を着た人たち、ギャーギャー騒がしく客引きしてたじゃない。",
  ui_story_5051_50511101_11_dialog_content = "「黒い礼服を着た人たち」？まさか暗鬼のこと言ってるんですか？",
  ui_story_5051_50511101_12_dialog_content = "暗鬼の見分けもつかないほど酔っぱらってるんですか？",
  ui_story_5051_50511101_13_dialog_content = "<size=30>どうりで、私のこと分からないわけですね…</size>",
  ui_story_5051_50511101_14_dialog_content = "見たところ、このあたりの暗鬼はすでにきれいに片付いているようだ。",
  ui_story_5051_50511101_15_dialog_content = "城主様と殿下のいらっしゃる所はさらに多くの人員が配備されている。",
  ui_story_5051_50511101_16_dialog_content = "あなたの友人は城主様と殿下と一緒にいるというのなら、きっと無事だ。",
  ui_story_5051_50511101_17_dialog_content = "騎士さん、ありがとうございます。",
  ui_story_5051_50511101_18_dialog_content = "さっきあなたが「シャシャシャシャーッ」と暗鬼を片付けてくれなかったら、\nこんなに早くここまで来られませんでした。",
  ui_story_5051_50511101_19_dialog_content = "白夜城で会った騎士の中で、一番頼りがいのある騎士さんですね！",
  ui_story_5051_50511101_20_dialog_content = "水晶玉を使わなくても、わかります…",
  ui_story_5051_50511101_21_dialog_content = "あなたは将来きっと世に名をとどろかす大物になりますよ！",
  ui_story_5051_50511101_22_dialog_content = "もったいない言葉だ。",
  ui_story_5051_50511101_23_dialog_content = "今の私は騎士予備兵にすぎない。",
  ui_story_5051_50511101_24_dialog_content = "だが、そのように信じてくれたことは大きな励みだ。",
  ui_story_5051_50511101_25_dialog_content = "大丈夫ですよ。まだ若いんですから！この先チャンスはいくらでも…",
  ui_story_5051_50511101_26_dialog_content = "あっ、待ってください！",
  ui_story_5051_50511101_27_dialog_content = "（「記憶の鏡晶」が記録しているのは12年前に起こった事ですよね）",
  ui_story_5051_50511101_28_dialog_content = "（ということは、この見たところすごく若い騎士さんも\n実際には私よりずっと年上ってことですよね！？）",
  ui_story_5051_50511101_29_dialog_content = "オホン…騎士さん、あなた…今年いくつになります？",
  ui_story_5051_50511101_30_dialog_content = "あら、この子ったら、さっき私の弟子になりたいって言った時は\nずいぶん威勢がよかったのに…",
  ui_story_5051_50511101_31_dialog_content = "なんだって急にモジモジし出したの？",
  ui_story_5051_50511101_32_dialog_content = "好きなら好きってハッキリ言えばいいじゃない！",
  ui_story_5051_50511101_33_dialog_content = "ちょっと！そういう意味じゃないんですって！",
  ui_story_5051_50511101_34_dialog_content = "ん？",
  ui_story_5051_50511101_35_dialog_content = "もちろん、嫌いって意味じゃありません！",
  ui_story_5051_50511101_36_dialog_content = "つまり、その…ああ、もうっ、うまく言えませんが――",
  ui_story_5051_50511101_37_dialog_content = "12年後もまだ白夜城で騎士さんやってたら…",
  ui_story_5051_50511101_38_dialog_content = "私たちきっと、また会えますよ！",
  ui_story_5051_50511101_39_dialog_content = "あらイヤだ。「何年経っても必ず会いに行く。だから待っててくれ」ってヤツ？",
  ui_story_5051_50511101_40_dialog_content = "そんなよくあるセリフ、私は8歳の時から使ってるわ。もっと新鮮なのはないの？",
  ui_story_5051_50511101_41_dialog_content = "ううう…",
  ui_story_5051_50511101_42_dialog_content = "この大酒飲みはずっと口からデマカセばかり言うんです。\n騎士さん、気にしないでくださいね！",
  ui_story_5051_50511101_43_dialog_content = "約束だ。",
  ui_story_5051_50511101_44_dialog_content = "えっ？",
  ui_story_5051_50511101_45_dialog_content = "さまざまな理由から、私は一族から期待されていないが――",
  ui_story_5051_50511101_46_dialog_content = "一族の者たちが代わる代わる育ててくれなかったら、今の私はいなかった。",
  ui_story_5051_50511101_47_dialog_content = "だから私はいつの日か自身の存在価値を一族に証明してみせたい。\nそして、カルティマ家の栄光の歴史を再び残していきたい。",
  ui_story_5051_50511101_48_dialog_content = "12年後…",
  ui_story_5051_50511101_49_dialog_content = "あなたと私が再会する時までに、必ず何千何万の軍を統率する最強の騎士になってみせる。",
  ui_story_5051_50511101_50_dialog_content = "わぁ、なんだかカッコいいですね！",
  ui_story_5051_50511101_51_dialog_content = "じゃあ、約束ですよ。私必ず騎士団まで訪ねに行きますから！",
  ui_story_5051_50511101_52_dialog_content = "あ…でも、まだ名前聞いてませんでしたね。",
  ui_story_5051_50511101_53_dialog_content = "「キシローナ・カルティマ」だ。",
  ui_story_5051_50511101_54_dialog_content = "「キシローナ」ですか。可愛らしい名前ですね。",
  ui_story_5051_50511101_55_dialog_content = "え…ちょっと待ってください…",
  ui_story_5051_50511101_56_dialog_content = "騎士さんって、女の子だったんですか！？",
  ui_story_5051_50511101_57_dialog_content = "<color=#e8d9bb>街の別の場所では</color>",
  ui_story_5051_50511101_58_dialog_content = "若者よ、急いではならぬ。",
  ui_story_5051_50511101_59_dialog_content = "貴殿の置かれている状況も、気持ちも分からぬではないが…",
  ui_story_5051_50511101_60_dialog_content = "年を重ね、ようやく「柔よく剛を制す」という道理が分かるようになった。",
  ui_story_5051_50511101_61_dialog_content = "よく考えるのだ。家族を巻き込むでない。",
  ui_story_5051_50511101_62_dialog_content = "今度機会があれば、お主を元老院の各位に紹介してやろう。",
  ui_story_5051_50511101_63_dialog_content = "きっと話が合うであろう。いずれも「若者」を導くことを好む者ばかりだ。",
  ui_story_5051_50511101_64_dialog_content = "…そんな風に考えていたのか。",
  ui_story_5051_50511101_65_dialog_content = "…それもそうだな。何ゆえ忘れていたのであろう…",
  ui_story_5051_50511101_66_dialog_content = "若き頃の余は「自分こそ正しい」と言わんばかりの説教を最も嫌っていた。",
  ui_story_5051_50511101_67_dialog_content = "<size=45>わぁ――！</size>",
  ui_story_5051_50511101_68_dialog_content = "むむ？",
  ui_story_5051_50511101_69_dialog_content = "やっと見つけましたよ！みなさん、無事でしたか！？",
  ui_story_5051_50511101_70_dialog_content = "五体満足、生き生きとした表情…なんともないみたいですね。ああ、よかった！",
  ui_story_5051_50511101_71_dialog_content = "ジャキーニ…",
  ui_story_5051_50511101_72_dialog_content = "PlayerName、私の心配はいりませんって！\nほら、見ての通りピンピンしてます！",
  ui_story_5051_50511101_73_dialog_content = "さあ、合流できたんですから、ここを離れましょう。",
  ui_story_5051_50511101_74_dialog_content = "コホン…ちょっと特殊な事情があって…",
  ui_story_5051_50511101_75_dialog_content = "「今日」中にここから出なきゃいけないんです。",
  ui_story_5051_50511101_76_dialog_content = "シーッ…",
  ui_story_5051_50511101_77_dialog_content = "え？何か問題でも？",
  ui_story_5051_50511101_78_dialog_content = "あ、もしかして、この酔っぱらいが誰か聞きたいんですか？",
  ui_story_5051_50511101_79_dialog_content = "説明し出すと長くなるんですけど…ある騎士さんが私たちを助けてくれたんです！",
  ui_story_5051_50511101_80_dialog_content = "あれ？騎士さんは？",
  ui_story_5051_50511101_81_dialog_content = "友だちが見つかったのを見て、何も言わず帰っちゃったんでしょうか？",
  ui_story_5051_50511101_82_dialog_content = "まったく…白夜城の人って、なんでお別れの挨拶をしたがらないんです？",
  ui_story_5051_50511101_83_dialog_content = "ちょっと。この人たちが探してた友だち？",
  ui_story_5051_50511101_84_dialog_content = "どこかで会った気がするわ！？",
  ui_story_5051_50511101_85_dialog_content = "ボアーズか？昨晩のうちに北境へ戻ったのではないのか？",
  ui_story_5051_50511101_86_dialog_content = "せっかく白夜城に来たのよ…ゲプッ。ゆっくり楽しみたいじゃな～い。",
  ui_story_5051_50511101_87_dialog_content = "あ～、思い出したわ。あなた、昨日の…",
  ui_story_5051_50511101_88_dialog_content = "城主様ね！",
  ui_story_5051_50511101_89_dialog_content = "（え？こ、この人が…ここの城主様！？）",
  ui_story_5051_50511101_90_dialog_content = "（どうりでさっきからPlayerNameが目配せしてたわけですね…）",
  ui_story_5051_50511101_91_dialog_content = "<size=30>PlayerName、ちょっとこっちこっち！</size>",
  ui_story_5051_50511101_92_dialog_content = "な、何？そんな引っ張らないで…",
  ui_story_5051_50511101_93_dialog_content = "ちょっと、これはいったいどういう状況なんです？",
  ui_story_5051_50511101_94_dialog_content = "僕もきちんと状況を整理しようとしてたんだけど、君の出現で状況はさらに複雑になった気がする…",
  ui_story_5051_50511101_95_dialog_content = "この世に複雑なことなんてありませんよ。考えすぎじゃありません？",
  ui_story_5051_50511101_96_dialog_content = "とにかく、ソルラドさんがさっきソルラドさんを見つけちゃって、ソルラドさんのことを賊だって勘違いしちゃって…",
  ui_story_5051_50511101_97_dialog_content = "聞けば聞くほど、わからないんですけど？",
  ui_story_5051_50511101_98_dialog_content = "だから、複雑な状況だって言ったんだよ…",
  ui_story_5051_50511101_99_dialog_content = "要はどうやって2人の城主様を区別するかってことですね？",
  ui_story_5051_50511101_100_dialog_content = "さっき僕はこの世界に一緒に入ってきたソルラドさんのことを僕の父親で、「ソロス」って名前だって説明したんだ…",
  ui_story_5051_50511101_101_dialog_content = "「ソロス」？PlayerNameの巨像みたいな名前ですね。",
  ui_story_5051_50511101_102_dialog_content = "あまりにも急だったから、他にいい名前が思いつかなくて…",
  ui_story_5051_50511101_103_dialog_content = "一方は年取った城主様、もう一方は若い城主様――それでいいんじゃありません？",
  ui_story_5051_50511101_104_dialog_content = "ソルラドさんにはちょっと申し訳ないけど、その方が理解しやすいなら…",
  ui_story_5051_50511101_105_dialog_content = "さっき年取ったソルラドさんがミヤを連れて行こうとしたら、若いソルラドさんに賊と間違えられちゃったんだ。",
  ui_story_5051_50511101_106_dialog_content = "今どうやったらこの状況を切り抜けられるか、考えてたところだよ。",
  ui_story_5051_50511101_107_dialog_content = "なるほど。わかりました！",
  ui_story_5051_50511101_108_dialog_content = "任せてください！",
  ui_story_5051_50511101_109_dialog_content = "…大丈夫よ、私酔ってなんかいないから！",
  ui_story_5051_50511101_110_dialog_content = "ふむ。では隣におる者は何者か紹介してもらえるかな？",
  ui_story_5051_50511101_111_dialog_content = "いえいえ、自己紹介しますよ！私はボアーズの弟子です、えへへ。",
  ui_story_5051_50511101_112_dialog_content = "北境の女王が使者を2名遣わしたとは聞いておらぬが。",
  ui_story_5051_50511101_113_dialog_content = "城主様はご存じなくて当然ですよ。だって、使者は1人だけですから。",
  ui_story_5051_50511101_114_dialog_content = "私はただのお付きです。でも、お付きにはお付きの任務があるんです！",
  ui_story_5051_50511101_115_dialog_content = "私の任務はボアーズとは別件だったので、城主様と夫人に謁見してなかったんですよ。",
  ui_story_5051_50511101_116_dialog_content = "ほう？では、お主の任務とは何か？",
  ui_story_5051_50511101_117_dialog_content = "PlayerNameを女王陛下の開催するパーティーに招待し、北境まで連れて行くことです。",
  ui_story_5051_50511101_118_dialog_content = "え！？",
  ui_story_5051_50511101_119_dialog_content = "PlayerNameは知らぬようだが。",
  ui_story_5051_50511101_120_dialog_content = "コホン、知らなくて当然ですよ。だって、今ようやく本人を見つけたんですから。",
  ui_story_5051_50511101_121_dialog_content = "PlayerName、どうです？行きます？",
  ui_story_5051_50511101_122_dialog_content = "<size=30>コホン…さっさと答えてくださいよっ！</size>",
  ui_story_5051_50511101_123_dialog_content = "え？ああ…",
  ui_story_5051_50511101_124_dialog_content = "女王陛下の誘いなら、もちろん断るわけないよ！",
  ui_story_5051_50511101_125_dialog_content = "そうですか、それは良かったです！",
  ui_story_5051_50511101_126_dialog_content = "師匠の任務も完了、私の任務も完了しました。",
  ui_story_5051_50511101_127_dialog_content = "じゃあ、みなさん一緒に楽しく北境に帰りましょう！",
  ui_story_5051_50511101_128_dialog_content = "（ジャキーニって本当天才だな！）",
  ui_story_5051_50511101_129_dialog_content = "（これで、若いソルラドさんも僕たちを帰らせてくれるよね？）",
  ui_story_5051_50511101_130_dialog_content = "…",
  ui_story_5051_50511101_131_dialog_content = "（ただ、どうして年取ったソルラドさんは神経を張り詰めたままなんだろう？）",
  ui_story_5051_50511101_132_dialog_content = "（僕もジャキーニも簡単に考えすぎてたのかな？）",
  ui_story_5051_50511101_133_dialog_content = "左様であったか。",
  ui_story_5051_50511101_134_dialog_content = "（錯覚かな？若いソルラドさん、今鼻で笑ったような…）",
  ui_story_5051_50511101_135_dialog_content = "余は北境の女王には敬意をもっておる。女王の客人とあらば、余の客人でもある。",
  ui_story_5051_50511101_136_dialog_content = "すまぬことをした。各位の前で白夜城の醜態をさらしてしまったな。",
  ui_story_5051_50511101_137_dialog_content = "だが、この混乱も長くは続かぬと誓おう。",
  ui_story_5051_50511101_138_dialog_content = "この先は各位とも余の後に付いてきていただく。",
  ui_story_5051_50511101_139_dialog_content = "余自ら安全をお守りしよう！",
  ui_story_5051_50511101_140_dialog_content = "<size=30>さっきと…態度がガラッと変わった…？</size>",
  ui_story_5051_50511101_141_dialog_content = "<size=30>コマ自ら飛び込んできたら、\nPlayerName、お主はいかがする？</size>",
  ui_story_5051_50511101_142_dialog_content = "<size=30>コマ？</size>",
  ui_story_5051_50511101_143_dialog_content = "（どういう意味だろう？僕たちが若いソルラドさんのコマになるってこと？）",
  ui_story_5051_50511101_144_dialog_content = "（でも、僕たちに何ができるっていうんだろう？）",
  ui_story_5051_50511101_145_dialog_content = "（それに…年取ったソルラドさんがそんなこと言うのは…）",
  ui_story_5051_50511101_146_dialog_content = "（ソルラドさんも過去に…こんな風に他人をコマにしてたから？）",
  ui_story_5051_50511101_147_dialog_content = "<size=30>PlayerName、チェスは決して気楽なお遊びではない。\n今それがよく分かったであろう</size>",
  ui_story_5051_50511101_148_dialog_content = "お父様！",
  ui_story_5051_50511101_149_dialog_content = "この声は…",
  ui_story_5051_50511101_150_dialog_content = "お父様！",
  ui_story_5051_50511101_151_dialog_content = "カレ…",
  ui_story_5051_50511101_152_dialog_content = "カレン、何ゆえここにおるのだ？",
  ui_story_5051_50511101_153_dialog_content = "わたくしが連れて来たの。",
  ui_story_5051_50511101_154_dialog_content = "…",
  ui_story_5051_50511101_155_dialog_content = "何ゆえ戻ってきた？次の暗鬼どもも片付けたのか？",
  ui_story_5051_50511101_156_dialog_content = "「次の暗鬼」？",
  ui_story_5051_50511101_157_dialog_content = "うっ…他の場所でも暗鬼が出現しているのではないかと思ってな。",
  ui_story_5051_50511101_158_dialog_content = "確信はないが、まだ気を緩めるのは早い。",
  ui_story_5051_50511101_159_dialog_content = "Ms.ロトはいかがした？\nお主たちの避難に同行させたであろう？何ゆえ身勝手に任を離れた？",
  ui_story_5051_50511101_160_dialog_content = "Ms.ロトは任を離れてなどいないわ。\nわたくしたちよりも周辺の住民こそ彼女の助けを必要としているの。",
  ui_story_5051_50511101_161_dialog_content = "ヨシュア、さように勝手なことをしては…",
  ui_story_5051_50511101_162_dialog_content = "ダニエル、わたくしのことはよく知っているでしょう？",
  ui_story_5051_50511101_163_dialog_content = "わたくしの剣の腕はあなたにも劣らないこと、\nいつになったら思い出してくれるのかしら？",
  ui_story_5051_50511101_164_dialog_content = "ここにも助けの必要な方がたくさんいるようだし…",
  ui_story_5051_50511101_165_dialog_content = "ダニエル、わたくしもあなたの役に立ちたいの。",
  ui_story_5051_50511101_166_dialog_content = "ヨシュア！",
  ui_story_5051_50511101_167_dialog_content = "ゴホッゴホゴホッ…",
  ui_story_5051_50511101_168_dialog_content = "あら？そちらの方、どうかなさいました？",
  ui_story_5051_50511101_169_dialog_content = "…どこかでお会いしたことがありますか？",
  ui_story_5051_50511101_170_dialog_content = "そうかもしれぬな。初めて会った時もそう言っていた。",
  ui_story_5051_50511101_171_dialog_content = "わたくしたち…どこかでお会いしました？",
  ui_story_5051_50511101_172_dialog_content = "（さっきこの世界と深く関わるなって言ったのはソルラドさんなのに…）",
  ui_story_5051_50511101_173_dialog_content = "コホン、父さんは城主夫人に会ったことあるの？",
  ui_story_5051_50511101_174_dialog_content = "…申し訳ない。人違いだったようだ。",
  ui_story_5051_50511101_175_dialog_content = "まあ、PlayerNameのお父様でしたの。どうりで会ったことがある気がしたわけですね。",
  ui_story_5051_50511101_176_dialog_content = "ぎゃあああ――！",
  ui_story_5051_50511101_177_dialog_content = "暗鬼だ…なんでまた暗鬼がこんなにたくさん！",
  ui_story_5051_50511101_178_dialog_content = "城主様がさっき言った通りですね。やっぱりまだ暗鬼がいたみたいです！",
  ui_story_5051_50511101_179_dialog_content = "まさか城主様も占いができるんですか？しかも私よりもずっと当たる占術だったり！？",
  ui_story_5051_50511101_180_dialog_content = "…",
  ui_story_5051_50511101_181_dialog_content = "ダニエル！",
  ui_story_5051_50511101_182_dialog_content = "周囲に注意し、暗鬼を警戒せよ！",
  ui_story_5051_50511101_183_dialog_content = "<color=#e8d9bb>ダッダッダッ！</color>",
  ui_story_5051_50511101_184_dialog_content = "この音、足並みがそろってる…",
  ui_story_5051_50511101_185_dialog_content = "暗鬼じゃないよ！",
  ui_story_5051_50511101_186_dialog_content = "よかった！",
  ui_story_5051_50511101_187_dialog_content = "応援の衛兵が来たんですね！",
  ui_story_5051_50511101_188_dialog_content = "待たれよ。",
  ui_story_5051_50511101_189_dialog_content = "衛兵はどうやら我々の応援に駆け付けたのではなさそうだ。",
  ui_story_5051_50511101_190_dialog_content = "えっ？",
  ui_story_5051_50511101_191_dialog_content = "突撃！",
  ui_story_5051_50511101_192_dialog_content = "うわぁ――！",
  ui_story_5051_50511101_193_dialog_content = "この人たち、なんで私たちに武器を向けるんです！？",
  ui_story_5051_50511102_1_dialog_content = "ジャキーニ、左斜め後ろに気をつけて！",
  ui_story_5051_50511102_2_dialog_content = "来ないでください！",
  ui_story_5051_50511102_3_dialog_content = "うぐっ…",
  ui_story_5051_50511102_4_dialog_content = "あれ？PlayerNameが助けてくれたんですか？",
  ui_story_5051_50511102_5_dialog_content = "ち、違うと思うよ！？",
  ui_story_5051_50511102_6_dialog_content = "ちょっとちょっと、石の妖怪ども、道を歩く時は気をつけなさいよ。",
  ui_story_5051_50511102_7_dialog_content = "弟子がケガしたら、お酒が飲めないじゃない！",
  ui_story_5051_50511102_8_dialog_content = "…私の知ってる、強くて怖いものナシのボアーズがやっと戻ってきたんですね！",
  ui_story_5051_50511102_9_dialog_content = "あ～、頭がクラクラする…さっき力入れすぎたのかしら？",
  ui_story_5051_50511102_10_dialog_content = "お嬢ちゃん、あとは任せたわ。私、もう…ダメ…",
  ui_story_5051_50511102_11_dialog_content = "ちょっと――！まだ全然「思い出話」してないんですよ！",
  ui_story_5051_50511102_12_dialog_content = "…まったく、こんな時に眠っちゃうなんて…前言撤回です！",
  ui_story_5051_50511102_13_dialog_content = "PlayerName、お主はジャキーニとミヤを連れ、\n右手の隙から包囲を突破せよ！余が援護する！",
  ui_story_5051_50511102_14_dialog_content = "他のみんなを置いて…逃げるんですか？",
  ui_story_5051_50511102_15_dialog_content = "もたもたするでない！<color=#FFB400>反乱</color>はすでに始まっておるのだ。\nここに留まるのは危険極まりない！",
  ui_story_5051_50511102_16_dialog_content = "反乱…ですって？",
  ui_story_5051_50511102_17_dialog_content = "わ、私…どうして思い出せないの…当時の私は知ってたの？",
  ui_story_5051_50511102_18_dialog_content = "ミヤ、無理して思い出さなくていいんだよ！",
  ui_story_5051_50511102_19_dialog_content = "<color=#e8d9bb>シュッ――！</color>",
  ui_story_5051_50511102_20_dialog_content = "誰？",
  ui_story_5051_50511102_21_dialog_content = "何か空から降りてきませんでした？\n目標に向かって一直線に下りてきた気がしましたけど？",
  ui_story_5051_50511102_22_dialog_content = "目標ってまさか…<color=#FFB400>若いソルラドさん</color>！？",
  ui_story_5051_50511102_23_dialog_content = "若いソルラドさんは敵に囲まれてて、上から迫った危険に気付いてないみたいですよ？",
  ui_story_5051_50511102_24_dialog_content = "でも、どうして…？今のソルラドさんだっているんだよ、気づくはずでしょ？",
  ui_story_5051_50511102_25_dialog_content = "…",
  ui_story_5051_50511102_26_dialog_content = "ダニエル、危ない！！",
  ui_story_5051_50511102_27_dialog_content = "はあっ――！",
  ui_story_5051_50511102_28_dialog_content = "うっ…",
  ui_story_5051_50511102_29_dialog_content = "うわあああ！い、痛そうです！",
  ui_story_5051_50511102_30_dialog_content = "肩を刺された？",
  ui_story_5051_50511102_31_dialog_content = "注意が反れている隙にここから離れるのだ！",
  ui_story_5051_50511102_32_dialog_content = "で、でも…",
  ui_story_5051_50511102_33_dialog_content = "お父様！",
  ui_story_5051_50511102_34_dialog_content = "カレンがお父様を助けるわ！",
  ui_story_5051_50511102_35_dialog_content = "おや、そうですか？",
  ui_story_5051_50511102_36_dialog_content = "「カレン」…",
  ui_story_5051_50511102_37_dialog_content = "大変だ、隠れてたカレンが反乱軍に見つかっちゃった！",
  ui_story_5051_50511102_38_dialog_content = "…なに？",
  ui_story_5051_50511102_39_dialog_content = "あ、あなた…悪者ね？",
  ui_story_5051_50511102_40_dialog_content = "お姫様、ごきげんよう。",
  ui_story_5051_50511102_41_dialog_content = "カ、カレンは、あなたなんて怖くないわ！",
  ui_story_5051_50511102_42_dialog_content = "私の剣術はすごいのよ！たくさんの衛兵を倒してきたの！",
  ui_story_5051_50511102_43_dialog_content = "それは残念ですね。私は衛兵たちのように手加減はいたしませんから。",
  ui_story_5051_50511102_44_dialog_content = "あっ…",
  ui_story_5051_50511102_45_dialog_content = "アハハハ、まだ全力を出しておりませんのに、もうお転びになったのですか？",
  ui_story_5051_50511102_46_dialog_content = "無理して立ち上がる必要はございません。どうせまたお転びになるのですから。",
  ui_story_5051_50511102_47_dialog_content = "あっ――！",
  ui_story_5051_50511102_48_dialog_content = "支配者の刃！",
  ui_story_5051_50511102_49_dialog_content = "な…なにぃ…",
  ui_story_5051_50511102_50_dialog_content = "（年取ったソルラドさんも口では逃げようっていいながら、\nやっぱりカレンを助けずにはいられなかったんだね…）",
  ui_story_5051_50511102_51_dialog_content = "カレンは…助かったの？お父様、お父様が助けてくださったの…？",
  ui_story_5051_50511102_52_dialog_content = "…",
  ui_story_5051_50511102_53_dialog_content = "カレン！！",
  ui_story_5051_50511102_54_dialog_content = "カレン、どこをケガしたの？",
  ui_story_5051_50511102_55_dialog_content = "お母様、心配しないで。カレン…ケガしてないわ。",
  ui_story_5051_50511102_56_dialog_content = "あなたって子は…こんな時に強がったりして…",
  ui_story_5051_50511102_57_dialog_content = "…おそらく驚いただけであろう。",
  ui_story_5051_50511102_58_dialog_content = "PlayerNameのお父様、カレンを救っていただいてありがとうございます！",
  ui_story_5051_50511102_59_dialog_content = "礼などいらぬ。当然のことだ。",
  ui_story_5051_50511102_60_dialog_content = "可哀想に。",
  ui_story_5051_50511102_61_dialog_content = "お母様。お父様は…ゴホゴホッ…お父様は？",
  ui_story_5051_50511102_62_dialog_content = "お父様は…",
  ui_story_5051_50511102_63_dialog_content = "心配いらないわよ。お父様がもうじき悪い人たちを捕まえてくれるわ。",
  ui_story_5051_50511102_64_dialog_content = "お母様、お父様を助けに行って！カレンは…大丈夫！",
  ui_story_5051_50511102_65_dialog_content = "あなたって子はもう…",
  ui_story_5051_50511102_66_dialog_content = "はぁっ！",
  ui_story_5051_50511102_67_dialog_content = "ゴホッ…",
  ui_story_5051_50511102_68_dialog_content = "ダニエル！",
  ui_story_5051_50511102_69_dialog_content = "心配は無用だ。刺客などあやつ独りで十分だ。",
  ui_story_5051_50511102_70_dialog_content = "でも、ケガをしているんです。やっぱり…",
  ui_story_5051_50511102_71_dialog_content = "では、「そなたの夫」は余が助けよう。そなたはここにいるがよい。",
  ui_story_5051_50511102_72_dialog_content = "え？命の危険を冒してまで、そのようなことをなさる必要はありません。",
  ui_story_5051_50511102_73_dialog_content = "反乱軍の目標はみなさんではなく、わたくしたちなのですから。",
  ui_story_5051_50511102_74_dialog_content = "このような危機的状況で他人行儀はかえって仇となる。",
  ui_story_5051_50511102_75_dialog_content = "待っているがよい。",
  ui_story_5051_50511102_76_dialog_content = "PlayerName、お主もジャキーニ、ミヤと共にここにおれ。",
  ui_story_5051_50511102_77_dialog_content = "すぐに戻る。",
  ui_story_5051_50511102_78_dialog_content = "待ってください！",
  ui_story_5051_50511102_79_dialog_content = "わ、私も行きます。",
  ui_story_5051_50511102_80_dialog_content = "…",
  ui_story_5051_50511102_81_dialog_content = "では、お前は左、余は右から攻撃する。行くぞ！",
  ui_story_5051_50511102_82_dialog_content = "…は、はい！",
  ui_story_5051_50511102_83_dialog_content = "錯覚かしら？",
  ui_story_5051_50511102_84_dialog_content = "PlayerNameのお父様とダニエルの姿が重なるなんて…",
  ui_story_5051_50511102_85_dialog_content = "うっ…",
  ui_story_5051_50511102_86_dialog_content = "待っていたぞ。",
  ui_story_5051_50511102_87_dialog_content = "なにぃ？",
  ui_story_5051_50511102_88_dialog_content = "フッ、思っていたよりも軽い傷で済んだようだ。",
  ui_story_5051_50511102_89_dialog_content = "…最初から分かっていたのか。",
  ui_story_5051_50511102_90_dialog_content = "無駄話はよい。速戦即決せよ。",
  ui_story_5051_50511102_91_dialog_content = "わ、私も手伝います！",
  ui_story_5051_50511102_92_dialog_content = "撤収だ！！",
  ui_story_5051_50511102_93_dialog_content = "全員、早急に撤収せよ！",
  ui_story_5051_50511102_94_dialog_content = "よい機会を与えてくれた。感謝する…",
  ui_story_5051_50511102_95_dialog_content = "光のもとで、万物は輝く！",
  ui_story_5051_50511102_96_dialog_content = "うわっ！",
  ui_story_5051_50511102_97_dialog_content = "言ったであろう…",
  ui_story_5051_50511102_98_dialog_content = "一城の主たる者、飾りのはずがない。",
  ui_story_5051_50511201_1_dialog_content = "はぁ…はぁ…はぁ…",
  ui_story_5051_50511201_2_dialog_content = "叔父上、ご無事ですか？",
  ui_story_5051_50511201_3_dialog_content = "キシローナ！？",
  ui_story_5051_50511201_4_dialog_content = "半日の休みを与えただろう、どうしてここにいる？",
  ui_story_5051_50511201_5_dialog_content = "今朝ヴェロニカ殿下の友人と人探しを手伝うと約束したでしょう？\n私も何かお手伝いできるかと…",
  ui_story_5051_50511201_6_dialog_content = "叔父上の言いつけに従わなかったのは申し訳ありません。",
  ui_story_5051_50511201_7_dialog_content = "しかし、城内に突然暗鬼が現れたのです。\n騎士予備兵として、皆を守るのは当然のことです。",
  ui_story_5051_50511201_8_dialog_content = "それに、城内を巡回しているカルティマ家の者たちのことも心配です…\nもちろん叔父上のことも。",
  ui_story_5051_50511201_9_dialog_content = "…そうか。",
  ui_story_5051_50511201_10_dialog_content = "だが、お前はすぐに戻れ。叔母上と弟妹たちを連れて白夜城を離れるのだ！",
  ui_story_5051_50511201_11_dialog_content = "庭に停めてある飛空艇を使え。",
  ui_story_5051_50511201_12_dialog_content = "叔父上、な…なぜです？",
  ui_story_5051_50511201_13_dialog_content = "聞くな、言う通りにすればいい！",
  ui_story_5051_50511201_14_dialog_content = "叔父上、街に出現した暗鬼たちは\nどうやら私や叔父上に攻撃を仕掛ける気はないようです。",
  ui_story_5051_50511201_15_dialog_content = "カルティマ家の血は暗鬼の天敵なのかもしれません。",
  ui_story_5051_50511201_16_dialog_content = "この機に一族を挙げて白夜城のため暗鬼駆逐に力を尽くせば…",
  ui_story_5051_50511201_17_dialog_content = "城主様にも重用され、カルティマ家の栄光を取り戻せるはずです！",
  ui_story_5051_50511201_18_dialog_content = "せっかくの機会になぜ私に家族を連れて逃げるようおっしゃるのですか…？",
  ui_story_5051_50511201_19_dialog_content = "お前の言葉で思い出した。白夜城を離れても、他の暗鬼に遭遇するかもしれん…",
  ui_story_5051_50511201_20_dialog_content = "私の書斎にカルティマ家が代々受け継いできた太刀「碧光」が置いてある。",
  ui_story_5051_50511201_21_dialog_content = "それも持って行け！",
  ui_story_5051_50511201_22_dialog_content = "叔父上、どういうことですか…",
  ui_story_5051_50511201_23_dialog_content = "あの予言は正しかったのかもしれない。\nただ私が信じようとしなかっただけのようだ。",
  ui_story_5051_50511201_24_dialog_content = "カルティマ家を救えるのはお前だ…",
  ui_story_5051_50511201_25_dialog_content = "私ではない。",
  ui_story_5051_50511201_26_dialog_content = "…",
  ui_story_5051_50511201_27_dialog_content = "これも…当時と同じですか？",
  ui_story_5051_50511201_28_dialog_content = "左様だ。",
  ui_story_5051_50511201_29_dialog_content = "ただ当時、カレンの傷はもう少し深かった。余も守ってやることはできなかった。",
  ui_story_5051_50511201_30_dialog_content = "だから、カレンの声が聞こえた時、思わず駆け付けたんですね。",
  ui_story_5051_50511201_31_dialog_content = "当時の埋め合わせをしようとしたんですか？",
  ui_story_5051_50511201_32_dialog_content = "あの時のことを後悔しておらぬと言えば、嘘になる。",
  ui_story_5051_50511201_33_dialog_content = "カレンの傷はどのような状況か？",
  ui_story_5051_50511201_34_dialog_content = "軽いわ。手足の皮が擦り剝けてしまったくらい。",
  ui_story_5051_50511201_35_dialog_content = "それよりもあなた、肩から血が出ているわ。",
  ui_story_5051_50511201_36_dialog_content = "これしきの傷、蚊に刺されたのと変わらぬ。",
  ui_story_5051_50511201_37_dialog_content = "そういえば…わたくしたちしばらく一緒に剣術の訓練をしてないわね。",
  ui_story_5051_50511201_38_dialog_content = "昔なら、あの程度の不意打ちでケガを負うことなんてなかったのに…",
  ui_story_5051_50511201_39_dialog_content = "突如襲われたからな。少し態勢が崩れていたのやもしれぬ。",
  ui_story_5051_50511201_40_dialog_content = "「ソルラド家記念日」を祝う日に暗鬼に白夜城を襲わせ、\n混乱に乗じて暗殺をしかけるなんて…",
  ui_story_5051_50511201_41_dialog_content = "わたくしたちにいったいどれ程の恨みを抱いているの？",
  ui_story_5051_50511201_42_dialog_content = "城主様、城主夫人。",
  ui_story_5051_50511201_43_dialog_content = "隊を率い駆け付けるのが遅くなりましたことをお許しください。",
  ui_story_5051_50511201_44_dialog_content = "私が至らぬばかりにカレン殿下と城主様が負傷されてしまい…",
  ui_story_5051_50511201_45_dialog_content = "Ms.ロト、あなたのせいではないわ。",
  ui_story_5051_50511201_46_dialog_content = "あなたは市民の安全を守ったのよ。それこそあなたの責務だわ。",
  ui_story_5051_50511201_47_dialog_content = "城主夫人、お言葉痛み入ります。",
  ui_story_5051_50511201_48_dialog_content = "まだ何かあるのか？",
  ui_story_5051_50511201_49_dialog_content = "はい、城主様。",
  ui_story_5051_50511201_50_dialog_content = "先程この辺りに捜査網を張り巡らし隈なく捜索したところ、\n反乱軍のメンバー数名を捕らえることができました。",
  ui_story_5051_50511201_51_dialog_content = "うむ、何か分かったか。申せ。",
  ui_story_5051_50511201_52_dialog_content = "メンバーはいずれも特殊な紋様の付いた武器を持っておりました。",
  ui_story_5051_50511201_53_dialog_content = "対照の結果、その紋様はカルティマの紋章であると判明いたしました。",
  ui_story_5051_50511201_54_dialog_content = "カルティマ家ですって？",
  ui_story_5051_50511201_55_dialog_content = "数日前マイム夫人と晩さん会で楽しくお話したばかりよ。",
  ui_story_5051_50511201_56_dialog_content = "お子さんもカレンと同じくらいの年頃で…",
  ui_story_5051_50511201_57_dialog_content = "おかしいわ…こんなの、おかしいわ。",
  ui_story_5051_50511201_58_dialog_content = "反乱軍のメンバーが自分たちの正体を明かすような武器をわざわざ持っているかしら？",
  ui_story_5051_50511201_59_dialog_content = "尊大な者ほど単純なのだ。",
  ui_story_5051_50511201_60_dialog_content = "今日見事余を葬り、\n「ソルラド家」の統治を終わらせることができると思っておったのであろう。",
  ui_story_5051_50511201_61_dialog_content = "Ms.ロト。",
  ui_story_5051_50511201_62_dialog_content = "はい、城主様。",
  ui_story_5051_50511201_63_dialog_content = "カルティマ家が反乱を企てた、確かな証拠もあると法廷に知らせよ。",
  ui_story_5051_50511201_64_dialog_content = "即刻カルティマ家<color=#FFB400>全員</color>を指名手配とし、\n城内を隈なく捜索せねばならぬ。",
  ui_story_5051_50511201_65_dialog_content = "法廷には指名手配書を緊急発令し、\n我々の捜査逮捕に協力するよう要請するのだ。",
  ui_story_5051_50511201_66_dialog_content = "抵抗する者はその場で処刑せよ。",
  ui_story_5051_50511201_67_dialog_content = "承知いたしました、城主様。",
  ui_story_5051_50511201_68_dialog_content = "「カルティマ家全員」ですって？ダニエル、それはどういう…？",
  ui_story_5051_50511201_69_dialog_content = "今年はこんなことばかりだわ。",
  ui_story_5051_50511201_70_dialog_content = "ピュロス家とゴーティエ家の犠牲だけでは足りないとでも？",
  ui_story_5051_50511201_71_dialog_content = "ヨシュア…",
  ui_story_5051_50511201_72_dialog_content = "カレンには休養が必要だ。先に帰っておれ。",
  ui_story_5051_50511201_73_dialog_content = "…",
  ui_story_5051_50511201_74_dialog_content = "ちょうどよい。ヨシュア…夫人、余も我が子を連れてここを離れるところだ。",
  ui_story_5051_50511201_75_dialog_content = "送って差し上げよう。",
  ui_story_5051_50511201_76_dialog_content = "ご厚意に感謝します。",
  ui_story_5051_50511201_77_dialog_content = "でも、城内の暗鬼はすでに倒されていますし、わたくしだけで十分ですわ。",
  ui_story_5051_50511201_78_dialog_content = "ソロス殿、確か「ソロス」殿であったな？",
  ui_story_5051_50511201_79_dialog_content = "うむ。",
  ui_story_5051_50511201_80_dialog_content = "先頃は疑ってしまい悪かった。",
  ui_story_5051_50511201_81_dialog_content = "貴殿の暗鬼との戦いぶりには、貴殿の申した通り、余も学ぶものがあった。",
  ui_story_5051_50511201_82_dialog_content = "貴殿のように秀でた戦闘能力を持つ者がこうして埋もれているのは惜しい。",
  ui_story_5051_50511201_83_dialog_content = "今日はもてなしに至らぬところがあった。\nすべてが済んだ後、またゆっくりと話せるやもしれぬ。",
  ui_story_5051_50511201_84_dialog_content = "余はただの老いぼれだ。",
  ui_story_5051_50511201_85_dialog_content = "我が子が無事家に戻ることだけが余の望みだ。",
  ui_story_5051_50511201_86_dialog_content = "残念だ。話が合うかと思ったが。",
  ui_story_5051_50511201_87_dialog_content = "似すぎる者同士はかえって友人にはふさわしくなかろう。",
  ui_story_5051_50511201_88_dialog_content = "フッ、そうかもしれぬな。",
  ui_story_5051_50511201_89_dialog_content = "では、ヴェロニカ、行くぞ。",
  ui_story_5051_50511201_90_dialog_content = "わ、私ですか？",
  ui_story_5051_50511201_91_dialog_content = "他にヴェロニカという名の者がおるのか？",
  ui_story_5051_50511201_92_dialog_content = "どこへ行くんですか？",
  ui_story_5051_50511201_93_dialog_content = "反乱軍カルティマの残党を追捕する。",
  ui_story_5051_50511201_94_dialog_content = "今日よりお前も余に付いて戦い方を学ぶがよい。",
  ui_story_5051_50511201_95_dialog_content = "お、お父様は、私にその資格があると…？",
  ui_story_5051_50511201_96_dialog_content = "ヴェロニカ殿下の実力は皆が認めておる。",
  ui_story_5051_50511201_97_dialog_content = "だが、まだ年若く、今日は体力も使いつくしておろう。",
  ui_story_5051_50511201_98_dialog_content = "早めに休ませた方がよい。",
  ui_story_5051_50511201_99_dialog_content = "ソロス殿、ご子息のPlayerNameには休養が必要であろうが、\nヴェロニカは余の娘だ。",
  ui_story_5051_50511201_100_dialog_content = "世話を焼くのはお互い我が子のみとしよう。",
  ui_story_5051_50511201_101_dialog_content = "<size=30>あ、あの…</size>",
  ui_story_5051_50511201_102_dialog_content = "殿下には休養が必要だ。",
  ui_story_5051_50511201_103_dialog_content = "必要なのは学びだ。",
  ui_story_5051_50511201_104_dialog_content = "<size=45>あの！</size>",
  ui_story_5051_50511201_105_dialog_content = "うむ？",
  ui_story_5051_50511201_106_dialog_content = "わ、私…",
  ui_story_5051_50511201_107_dialog_content = "一緒に行きたいです！",
  ui_story_5051_50511201_108_dialog_content = "！？",
  ui_story_5051_50511201_109_dialog_content = "お父様がこんな風に認めてくださったのは初めてなんです…",
  ui_story_5051_50511201_110_dialog_content = "だ、だから、きっと期待に応えてみせます！",
  ui_story_5051_50511201_111_dialog_content = "そ、それに確めたいんです。\n自分が経験しなかったこの歴史がいったいどんなものだったのか。",
  ui_story_5051_50511201_112_dialog_content = "…",
  ui_story_5051_50511201_113_dialog_content = "ヴェロニカ、行くぞ！",
  ui_story_5051_50511201_114_dialog_content = "は、はい！",
  ui_story_5051_50511201_115_dialog_content = "だったら僕も一緒に行きます！",
  ui_story_5051_50511201_116_dialog_content = "お主らときたら…身勝手にも程がある。",
  ui_story_5051_50511201_117_dialog_content = "あの、年取った城主様…\nボアーズがずいぶん深く眠りこけていて、ちょっと普通じゃない気がするんです…",
  ui_story_5051_50511201_118_dialog_content = "城主夫人が宮殿で診てくださるとおっしゃって…\nわ、私もこのまま放っておけないんです。",
  ui_story_5051_50511201_119_dialog_content = "みなさんも他の所へ行かれるなら、どうか安全には気を付けてください。",
  ui_story_5051_50511201_120_dialog_content = "それから、必ず今日一日が終わってしまう前に戻ってきてくださいね。\nじゃないと、私たち永遠にこの中に閉じ込められてしまいます…",
  ui_story_5051_50511201_121_dialog_content = "…よかろう。",
  ui_story_5051_50511201_122_dialog_content = "ただ、お主、今余を何と呼んだか？",
  ui_story_5051_50511201_123_dialog_content = "あ…つい口を滑らしてしまいました。",
  ui_story_5051_50511201_124_dialog_content = "とにかく、早く帰ってきてくださいね！",
  ui_story_5051_50511201_125_dialog_content = "<color=#e8d9bb>オットー邸</color>",
  ui_story_5051_50511201_126_dialog_content = "トロイ公爵、もしやとうの昔にこの件を存じておったか？",
  ui_story_5051_50511201_127_dialog_content = "はて、ハメス公爵は何のことをおっしゃっているのか。",
  ui_story_5051_50511201_128_dialog_content = "外は大混乱の真っただ中。もったいぶることもなかろう。",
  ui_story_5051_50511201_129_dialog_content = "おお！どこぞの誰かが暗鬼で混乱を起こし、その期に乗じて城主を暗殺しようとした件か。",
  ui_story_5051_50511201_130_dialog_content = "さようだ！",
  ui_story_5051_50511201_131_dialog_content = "どんなにソルラドのやり方が気に食わないとしても、\n卑劣な手段を使えば、我が一族の名を汚すだけだ。",
  ui_story_5051_50511201_132_dialog_content = "では、真に知らぬと？",
  ui_story_5051_50511201_133_dialog_content = "おやおや、ハメス公爵は四六時中疑心暗鬼でおられるようだな。\n一通り全員疑ってみないと気がすまないとでも？",
  ui_story_5051_50511201_134_dialog_content = "トロイ公爵を疑ってはおらぬわ。",
  ui_story_5051_50511201_135_dialog_content = "わしは…お主も知っておろう？ハメス家の子孫は騎士団に所属しておる。",
  ui_story_5051_50511201_136_dialog_content = "ソルラドは今、全騎士団を挙げて影ノ街を支援しようとしておろう？\nわしはこれに一貫して反対しておるのだ。",
  ui_story_5051_50511201_137_dialog_content = "そもそも暗鬼なぞ地上にはびこる害虫にすぎぬ。\n我々白夜城に害を及ぼすわけでもあるまいに。",
  ui_story_5051_50511201_138_dialog_content = "何故わざわざ死を選ばねばならぬのだ？",
  ui_story_5051_50511201_139_dialog_content = "さように考えておるのはわし一人じゃなかろう？",
  ui_story_5051_50511201_140_dialog_content = "ハメス公爵、城主にもそれなりの考えがあるのだよ。",
  ui_story_5051_50511201_141_dialog_content = "影ノ街を守りきれば、\n我々白夜城の影ノ街に対する支配権を強化できるというものだろう？",
  ui_story_5051_50511201_142_dialog_content = "そのくらいの道理ハメス公爵に分からないはずがない。",
  ui_story_5051_50511201_143_dialog_content = "フンッ、あそこがもたらす利益など、たかが知れておるわ。\n時がくれば、いずれソルラド一人のものになるであろうに。",
  ui_story_5051_50511201_144_dialog_content = "「ソルラド家記念日」などよく祝えたものだわい。",
  ui_story_5051_50511201_145_dialog_content = "白夜城の今日があるのは、ひとえにハメス家とトロイ家のおかげであろうに！",
  ui_story_5051_50511201_146_dialog_content = "何故ありとあらゆる利益をソルラド家に譲らねばならぬのだ？",
  ui_story_5051_50511201_147_dialog_content = "カルティマ家が事前に計画を明らかにし、我々数家が結集しておれば…",
  ui_story_5051_50511201_148_dialog_content = "ソルラドなど恐るるに足らぬわ。",
  ui_story_5051_50511201_149_dialog_content = "ハメス公爵、言葉には気を付けたまえ…",
  ui_story_5051_50511201_150_dialog_content = "先程入ったばかりの情報では、\n城主はすでにカルティマ全員を捕らえよとの命を下したらしい。",
  ui_story_5051_50511201_151_dialog_content = "カルティマがどんな末路をたどるか、想像には難くない。",
  ui_story_5051_50511201_152_dialog_content = "よもやピュロスとゴーティエのごとき結末になると？",
  ui_story_5051_50511201_153_dialog_content = "まだ分からないか？問題はそこだ。",
  ui_story_5051_50511201_154_dialog_content = "むむ？つまり…",
  ui_story_5051_50511201_155_dialog_content = "待て、解せたぞ。これですべてつながったわい！",
  ui_story_5051_50511201_156_dialog_content = "愚かなカルティマめが！",
  ui_story_5051_50511201_157_dialog_content = "これではかえってソルラドに権威を高める機会を与えてしまうではないか…",
  ui_story_5051_50511201_158_dialog_content = "ソルラドはこの機に乗じ、\n騎士団、さらには私兵を有するすべての一族を影ノ街へ送り込める。",
  ui_story_5051_50511201_159_dialog_content = "マイム・カルティマめ！身体ばかり立派な、能無しの愚か者が！",
  ui_story_5051_50511201_160_dialog_content = "ハメス公爵、こうなっては口を慎む方が賢明だぞ。",
  ui_story_5051_50511201_161_dialog_content = "さきほどの話は居眠りしていて、聞いていなかったことにしてやろう。",
  ui_story_5051_50511201_162_dialog_content = "…感謝するぞ、トロイ公爵。ならばわしもこれで失礼するとしよう。",
  ui_story_5051_50511201_163_dialog_content = "誰かいるか。",
  ui_story_5051_50511201_164_dialog_content = "はい。",
  ui_story_5051_50511201_165_dialog_content = "カルティマ家との信書をすべて処分しろ。",
  ui_story_5051_50511201_166_dialog_content = "<color=#e8d9bb>ガチャン！</color>",
  ui_story_5051_50511201_167_dialog_content = "何事だ！？",
  ui_story_5051_50511201_168_dialog_content = "見てまいります。",
  ui_story_5051_50511201_169_dialog_content = "誰かいたのか？",
  ui_story_5051_50511201_170_dialog_content = "ローシお嬢様です。お夕食前にお会いになると約束をしていらっしゃいましたので――",
  ui_story_5051_50511201_171_dialog_content = "部屋の外でしばらくお待ちになっていたようでございます。",
  ui_story_5051_50511201_172_dialog_content = "しかし、先程慌てたご様子で走り去っていかれました。",
  ui_story_5051_50511201_173_dialog_content = "まったくどいつもこいつも世話が焼ける…",
  ui_story_5051_50511301_1_dialog_content = "城主様、カルティマのこちらの屋敷では何も見つかりませんでした。",
  ui_story_5051_50511301_2_dialog_content = "カルティマ家がアップタウンに所有する不動産はすべて差し押さえました。\n使用人以外に武装した者はおりませんでした。",
  ui_story_5051_50511301_3_dialog_content = "警告も顧みず白夜城を離れた飛空艇が一隻ございましたが…",
  ui_story_5051_50511301_4_dialog_content = "それ以外のカルティマの者はおそらく全員、まだ白夜城内に身を潜めているでしょう。",
  ui_story_5051_50511301_5_dialog_content = "ミッドタウンとダウンタウンはどうだ？",
  ui_story_5051_50511301_6_dialog_content = "すでに人を遣り調べさせておりますが、\n状況が判明するにはもう少し時間がかかるかと思います。",
  ui_story_5051_50511301_7_dialog_content = "逃げずに白夜城内に身を潜めておると？",
  ui_story_5051_50511301_8_dialog_content = "どうやらまだ反撃の機をうかがっておるようだな。",
  ui_story_5051_50511301_9_dialog_content = "カルティマ家は人数も多く、近年では彼らを頼る者も多くおりました。",
  ui_story_5051_50511301_10_dialog_content = "状況は想像以上に厳しいかと…",
  ui_story_5051_50511301_11_dialog_content = "だが、座して待つわけにはいかぬ。",
  ui_story_5051_50511301_12_dialog_content = "引き続きミッドタウンを捜索する。",
  ui_story_5051_50511301_13_dialog_content = "お待ちいただこう。",
  ui_story_5051_50511301_14_dialog_content = "や、やっぱり来たんですね！",
  ui_story_5051_50511301_15_dialog_content = "…",
  ui_story_5051_50511301_16_dialog_content = "<size=30>ミヤ、怖がるでない。お前を連れ帰るために来たのではない</size>",
  ui_story_5051_50511301_17_dialog_content = "<size=30>余も決心がついた。お前にはこの歴史を知る権利がある</size>",
  ui_story_5051_50511301_18_dialog_content = "おや？ソロス殿か。すぐに再会できると思っておったぞ。",
  ui_story_5051_50511301_19_dialog_content = "ただ、こうも早いとは思わなかったが。",
  ui_story_5051_50511301_20_dialog_content = "思い出したのだ。捜索に役立つ手がかりを握っていたことを。",
  ui_story_5051_50511301_21_dialog_content = "時間稼ぎでないとよいが。",
  ui_story_5051_50511301_22_dialog_content = "もちろん時間稼ぎなどではない。\n余はただ我が子が一刻も早くわがままをやめ、共に帰路について欲しいだけだ。",
  ui_story_5051_50511301_23_dialog_content = "ただ約束してもらいたい。情報の出処を追求せんで欲しい。",
  ui_story_5051_50511301_24_dialog_content = "よかろう。情報の出処は追求せぬ。では話してもらおうか。どのような手がかりだ？",
  ui_story_5051_50511301_25_dialog_content = "ダウンタウンの今だ手つかずの荒野に、近頃私兵が駐屯していたらしき痕跡がある。",
  ui_story_5051_50511301_26_dialog_content = "Ms.ロト、お主は聞いたことがあるか？",
  ui_story_5051_50511301_27_dialog_content = "城外の荒野ですか…",
  ui_story_5051_50511301_28_dialog_content = "もしやあの岩石の丘陵のことでしょうか？",
  ui_story_5051_50511301_29_dialog_content = "確かにあの地では時々奇怪な動物の鳴き声が聞こえ、\n辺りには人気がないと聞いてはいますが…",
  ui_story_5051_50511301_30_dialog_content = "ソロス殿はカルティマの者がそこに隠れているとお考えか？",
  ui_story_5051_50511301_31_dialog_content = "確かだ。",
  ui_story_5051_50511301_32_dialog_content = "なぜそこまで言い切れる？いったいどこから入手した情報なのだ？",
  ui_story_5051_50511301_33_dialog_content = "出処は追求しないと約束したはずだが？",
  ui_story_5051_50511301_34_dialog_content = "出処は言えぬが、確かな情報だ。\nもし虚偽の情報であったのなら、どのような処罰も受けよう。",
  ui_story_5051_50511301_35_dialog_content = "うむ。ではMs.ロト、まずはその荒野へ向かうとしよう。",
  ui_story_5051_50511301_36_dialog_content = "城主様、本当に信じてよろしいのでしょうか？",
  ui_story_5051_50511301_37_dialog_content = "カルティマ家は遅かれ早かれ投降する。",
  ui_story_5051_50511301_38_dialog_content = "1度くらいやつを信じても、我々に差し支えはなかろう。",
  ui_story_5051_50511301_39_dialog_content = "むろん、他の地区の捜索を止めてはならぬ。",
  ui_story_5051_50511301_40_dialog_content = "承知いたしました、城主様。",
  ui_story_5051_50511301_41_dialog_content = "うーん…",
  ui_story_5051_50511301_42_dialog_content = "何か言いたげであるな。",
  ui_story_5051_50511301_43_dialog_content = "さっきの手がかりは当時も誰かがソルラドさんに教えたんですか？",
  ui_story_5051_50511301_44_dialog_content = "いや、当時我々は城内を捜索したが、有用な情報は何一つ得られなかった。",
  ui_story_5051_50511301_45_dialog_content = "夜になってようやく荒野の怪しい動きに気づき、\n反乱軍の激しい攻撃を受けることになった。",
  ui_story_5051_50511301_46_dialog_content = "だが、結局彼らは敗北の運命を逃れられはしなかったがな。",
  ui_story_5051_50511301_47_dialog_content = "僕たちが少しでも早く帰れるように、歴史が進むのを速めたってことですか？",
  ui_story_5051_50511301_48_dialog_content = "時おり思うのだ。あの時余がすぐに反乱軍を見つけておれば…",
  ui_story_5051_50511301_49_dialog_content = "長年余に付き従って来た衛兵たちも、\n今頃心を砕いてやまぬ我が子をもうけていたかもしれぬと。",
  ui_story_5051_50511301_50_dialog_content = "ソルラドさんはずっと僕たちがこの世界を変えてしまうことを恐れてましたよね？",
  ui_story_5051_50511301_51_dialog_content = "すでに深く関わってしまったのだ。今一つ関わりが増えたとて、さして変わらぬ。",
  ui_story_5051_50511301_52_dialog_content = "なんだか…僕の知ってるソルラドさんじゃないみたいですね。",
  ui_story_5051_50511301_53_dialog_content = "さようか？確かに城主という肩書を外した後、何かが変わったようにも思う。",
  ui_story_5051_50511301_54_dialog_content = "殊に過去の己と会った後はな…",
  ui_story_5051_50511301_55_dialog_content = "ここか？",
  ui_story_5051_50511301_56_dialog_content = "先に行っていた偵察員の報告では、\nカルティマ家の者が確かに前方の丘に集まっているとのことです。",
  ui_story_5051_50511301_57_dialog_content = "どうやら丘陵地で背水の陣を敷き、最後まで抵抗する気のようです！",
  ui_story_5051_50511301_58_dialog_content = "ヴェロニカ、申してみよ。",
  ui_story_5051_50511301_59_dialog_content = "今のこの状況で指揮を執るとしたら、お前はいかがする？",
  ui_story_5051_50511301_60_dialog_content = "私だったら…",
  ui_story_5051_50511301_61_dialog_content = "使者を遣わし、情と理を説いて――",
  ui_story_5051_50511301_62_dialog_content = "過ちを認め、この先の手柄で償うよう説得します。",
  ui_story_5051_50511301_63_dialog_content = "ヴェロニカ、それは誤りだ。",
  ui_story_5051_50511301_64_dialog_content = "より大きな責任を背負う者にならんとすれば、<color=#FFB400>手段を選ばず</color>勝ちにいかねばならぬ。",
  ui_story_5051_50511301_65_dialog_content = "手段を選ばず…勝ちに行く？",
  ui_story_5051_50511301_66_dialog_content = "上はアップタウン、下は影ノ街まで、数え切れぬ程の人々がこの戦いを注視しておる。",
  ui_story_5051_50511301_67_dialog_content = "皆勝敗が決するのを待っているのだ。\n勝者がどちらであろうと、やつらは勝者にのみ賛美の言葉を捧げる。",
  ui_story_5051_50511301_68_dialog_content = "戦場では、勝者は王となり、敗者は賊となるのだ。",
  ui_story_5051_50511301_69_dialog_content = "白夜城の歴史は今夜変わるやもしれぬな。",
  ui_story_5051_50511301_70_dialog_content = "ヴェロニカ、お前の学ぶべきことはまだ山のようにある。",
  ui_story_5051_50511301_71_dialog_content = "手段を選ばない…その価値観にはちょっと…賛同できません。",
  ui_story_5051_50511301_72_dialog_content = "左様か？",
  ui_story_5051_50511301_73_dialog_content = "（あ、忘れてた。過去のソルラドさんを批判するってことは\n今のソルラドさんを批判するってことだよね！？）",
  ui_story_5051_50511301_74_dialog_content = "あ、あの…ソルラドさんのことを悪く言おうと思ったわけじゃ…",
  ui_story_5051_50511301_75_dialog_content = "高みに立てば、己の意のままにならぬことも多い…\n責任逃れの言い訳に聞こえるであろうがな。",
  ui_story_5051_50511301_76_dialog_content = "今の余には自信をもって、己が一つの欠点もない偉人だと言うことはできぬ。",
  ui_story_5051_50511301_77_dialog_content = "だが…",
  ui_story_5051_50511301_78_dialog_content = "お主にはこれから先新たな道を切り開き、自らの生き方を見つけて欲しいと思っておる。",
  ui_story_5051_50511301_79_dialog_content = "はい！",
  ui_story_5051_50511301_80_dialog_content = "年を取った時、若い頃の自分を悔いることがないようにします。",
  ui_story_5051_50511301_81_dialog_content = "あ…え、ええと皮肉を言ったわけじゃありません！",
  ui_story_5051_50511301_82_dialog_content = "ハハハハハ！",
  ui_story_5051_50511301_83_dialog_content = "（ソルラドさんがこんなに思いっきり笑ったところを見るのは初めてな気がする…）",
  ui_story_5051_50511301_84_dialog_content = "（やっと分かってきた。\n今目の前にいる年取ったソルラドさんと若いソルラドさんのほかにも…）",
  ui_story_5051_50511301_85_dialog_content = "（それよりもっと前には、まだ世間を知らない、思いっきり声を上げて笑う…\nダニエルがいたんだよね）",
  ui_story_5051_50511301_86_dialog_content = "何か動きがあったようだが？",
  ui_story_5051_50511301_87_dialog_content = "…潜伏していた反乱軍でしょうか！？",
  ui_story_5051_50511302_1_dialog_content = "主な部屋はすべて探し尽くしました。",
  ui_story_5051_50511302_2_dialog_content = "それなのになぜ、見つからないのでしょう！？",
  ui_story_5051_50511302_3_dialog_content = "まさか人知れぬ秘密の部屋でもあるのでしょうか？",
  ui_story_5051_50511302_4_dialog_content = "きっとそうに違いない！",
  ui_story_5051_50511302_5_dialog_content = "ソルラドの性格からして、姉さんに隠している秘密がたくさんあるはず…",
  ui_story_5051_50511302_6_dialog_content = "秘密の部屋の入口は書斎でしょうか？",
  ui_story_5051_50511302_7_dialog_content = "おや？本棚にあるアレは…",
  ui_story_5051_50511302_8_dialog_content = "「記憶の鏡晶」！？",
  ui_story_5051_50511302_9_dialog_content = "間違いありません、「記憶の鏡晶」です！",
  ui_story_5051_50511302_10_dialog_content = "最も危険な場所こそ最も安全な場所、というわけですか？",
  ui_story_5051_50511302_11_dialog_content = "アハハハハハ。",
  ui_story_5051_50511302_12_dialog_content = "こんな貴重なものをこんな所に置いておくとは。",
  ui_story_5051_50511302_13_dialog_content = "まるで姉さんをないがしろにするようではないですか…",
  ui_story_5051_50511302_14_dialog_content = "城主夫人、お帰りなさいませ！",
  ui_story_5051_50511302_15_dialog_content = "姉さん…",
  ui_story_5051_50511302_16_dialog_content = "ずいぶん慌てているようだけど、何かあったの？",
  ui_story_5051_50511302_17_dialog_content = "…私の無能をお許しください！",
  ui_story_5051_50511302_18_dialog_content = "本日の午後、守衛が1名何者かに気絶させられ、今も床に臥せっております。",
  ui_story_5051_50511302_19_dialog_content = "隅々まで探し回ったのですが、悪しき侵入者を発見できず…",
  ui_story_5051_50511302_20_dialog_content = "またカルティマ家の者なの？",
  ui_story_5051_50511302_21_dialog_content = "分かったわ。",
  ui_story_5051_50511302_22_dialog_content = "今晩はお客様もいらっしゃるから、外を十分見張っていてちょうだい。",
  ui_story_5051_50511302_23_dialog_content = "承知いたしました、城主夫人！",
  ui_story_5051_50511302_24_dialog_content = "それと、負傷した守衛には安心して養生するように言っておいて。",
  ui_story_5051_50511302_25_dialog_content = "治療費もわたくしが負担するわ。",
  ui_story_5051_50511302_26_dialog_content = "ありがとうございます！",
  ui_story_5051_50511302_27_dialog_content = "カルティマ家ですか…",
  ui_story_5051_50511302_28_dialog_content = "あなたもカルティマ家の誰かを知っているの？",
  ui_story_5051_50511302_29_dialog_content = "はい…ただ、彼女も反乱軍の一味なのかはわかりません。",
  ui_story_5051_50511302_30_dialog_content = "すごく善良で、まっすぐな人に見えたので…",
  ui_story_5051_50511302_31_dialog_content = "将来は威厳ある騎士団長になりたいって言ってたんです！",
  ui_story_5051_50511302_32_dialog_content = "あなたのお友だちは事情を知らなかったようね。",
  ui_story_5051_50511302_33_dialog_content = "捕まったら…どうなるんですか？",
  ui_story_5051_50511302_34_dialog_content = "今はまだ分からないわ。",
  ui_story_5051_50511302_35_dialog_content = "でも、安心して。罪のない者が罰せられないよう、わたくしが力を尽くすわ。",
  ui_story_5051_50511302_36_dialog_content = "彼女の一族がご自身とご家族を暗殺しようとしたのに、ですか？",
  ui_story_5051_50511302_37_dialog_content = "罪ある者は罰を受けるべきよ。",
  ui_story_5051_50511302_38_dialog_content = "でも、血縁だからという理由で、罪のない人にまで罰を与えてはいけないわ…",
  ui_story_5051_50511302_39_dialog_content = "さあ、この話はやめましょう。",
  ui_story_5051_50511302_40_dialog_content = "まずは夕食とボアーズさんの酔い覚ましのスープを準備するわ。",
  ui_story_5051_50511302_41_dialog_content = "あの…城主様のことは心配じゃないんですか？",
  ui_story_5051_50511302_42_dialog_content = "ふふ、もちろん心配よ。",
  ui_story_5051_50511302_43_dialog_content = "でも、わたくしは心配よりもダニエルを信じていたいの。必ず無事だってね。",
  ui_story_5051_50511302_44_dialog_content = "だから、夕食を準備して、帰りを待っていなきゃいけないのよ。",
  ui_story_5051_50511302_45_dialog_content = "ヨシュア夫人、今からすでに夫人のことが恋しくなってきました！",
  ui_story_5051_50511302_46_dialog_content = "それなら今後いつでも白夜城に遊びにくるといいわ。",
  ui_story_5051_50511302_47_dialog_content = "ヴェロニカとカレンもあなたのようなお友だちを大好きになると思うわ。",
  ui_story_5051_50511302_48_dialog_content = "ううう、ぐすっ！",
  ui_story_5051_50511302_49_dialog_content = "シーッ――",
  ui_story_5051_50511302_50_dialog_content = "ボアーズさんとカレンが目を覚ましちゃうわ。寝かせておいてあげましょう。",
  ui_story_5051_50511401_1_dialog_content = "暗鬼を利用して混乱を起せば、簡単にソルラドを捕らえられると思ったのだが。",
  ui_story_5051_50511401_2_dialog_content = "奴の実力を見くびっていたようだ。",
  ui_story_5051_50511401_3_dialog_content = "対外的には体調を崩していると言っていたが…わざとだったのか？",
  ui_story_5051_50511401_4_dialog_content = "どうやら、とうの昔に私の計画に気づいていたらしい。",
  ui_story_5051_50511401_5_dialog_content = "…フッ、狡猾さでソルラドの右に出る者は白夜城にはいないな。",
  ui_story_5051_50511401_6_dialog_content = "ああ！長い年月をかけ、私も十分狡猾になれたと思っていたのに…",
  ui_story_5051_50511401_7_dialog_content = "…",
  ui_story_5051_50511401_8_dialog_content = "どういうこと？マイム、<color=#FFB400>龍脈</color>に目覚めたですって？",
  ui_story_5051_50511401_9_dialog_content = "カルティマ家では許されないことなのよ！",
  ui_story_5051_50511401_10_dialog_content = "わざとじゃないんだよ！母さん、助けて！",
  ui_story_5051_50511401_11_dialog_content = "いいわね。このことは誰にも言っちゃダメよ。",
  ui_story_5051_50511401_12_dialog_content = "で、でも、頭が割れそうに痛いよ…",
  ui_story_5051_50511401_13_dialog_content = "マイム、我慢するの！あなたならその力を抑えられるって言いなさい！",
  ui_story_5051_50511401_14_dialog_content = "カルティマ家の家長になるのは、あなたなのよ！",
  ui_story_5051_50511401_15_dialog_content = "痛い…痛いよ…僕にはできない！",
  ui_story_5051_50511401_16_dialog_content = "やらなきゃダメ！",
  ui_story_5051_50511401_17_dialog_content = "もう一度言ってみろ。",
  ui_story_5051_50511401_18_dialog_content = "わしをこの倒れかけの塔に閉じ込めようが…ゲホッゴホゴホッ…",
  ui_story_5051_50511401_19_dialog_content = "わしは同じことしか言わん！",
  ui_story_5051_50511401_20_dialog_content = "マイム、そちにカルティマは救えん。",
  ui_story_5051_50511401_21_dialog_content = "カルティマの家長はそちではない！",
  ui_story_5051_50511401_22_dialog_content = "その通りだ。私は龍脈に目覚めた。だが、それが何だと言うんだ？",
  ui_story_5051_50511401_23_dialog_content = "私はすでにカルティマの家長だ。これはもう紛れもない事実。",
  ui_story_5051_50511401_X23_dialog_content = "龍脈に目覚めたじゃと！？",
  ui_story_5051_50511401_X24_dialog_content = "「龍脈」を罪悪とみる一族の者をあざむくとは…確かに少しはできるようじゃの。",
  ui_story_5051_50511401_X25_dialog_content = "だが、それでもわしは同じことしか言わん。カルティマを救うのはそちではない。",
  ui_story_5051_50511401_X26_dialog_content = "龍脈に目覚めたかどうかとは関係のないことじゃ。",
  ui_story_5051_50511401_X27_dialog_content = "実に残念だ。お前の予言を信じる者はいない。",
  ui_story_5051_50511401_24_dialog_content = "ハハハハハ…ゴホゴホッ…",
  ui_story_5051_50511401_25_dialog_content = "恐れおののくがいい！カルティマを救う少女はまもなくそちの近くに現れる！",
  ui_story_5051_50511401_26_dialog_content = "完全に気が違ったか。",
  ui_story_5051_50511401_27_dialog_content = "…一族の方々は皆この子を嫌い、\n引き取って育てようとする方がいらっしゃらないのです。",
  ui_story_5051_50511401_28_dialog_content = "マイム様、こんばんは。",
  ui_story_5051_50511401_29_dialog_content = "キシローナ…です。",
  ui_story_5051_50511401_30_dialog_content = "！！！",
  ui_story_5051_50511401_31_dialog_content = "長老が言っていたのはお前か？",
  ui_story_5051_50511401_32_dialog_content = "絶対に迷惑は掛けません。",
  ui_story_5051_50511401_33_dialog_content = "この子は、私が引き取ろう。",
  ui_story_5051_50511401_34_dialog_content = "あ、ありがとうございます、マイム様！",
  ui_story_5051_50511401_35_dialog_content = "覚えておけ。ここにいる限り、お前が頭角を現す日は永遠にこない。",
  ui_story_5051_50511401_36_dialog_content = "えっ…",
  ui_story_5051_50511401_37_dialog_content = "マイム様、マイム様…",
  ui_story_5051_50511401_38_dialog_content = "何事だ？",
  ui_story_5051_50511401_39_dialog_content = "カルティマ家の兵士および一族の者が全員集結いたしました。",
  ui_story_5051_50511401_40_dialog_content = "結局、皆を巻き込むことになったか…",
  ui_story_5051_50511401_41_dialog_content = "マイム様、そのようなことおっしゃらないでください！",
  ui_story_5051_50511401_42_dialog_content = "ソルラドは我々カルティマ家のもつ権力をそぎ続けてきました。",
  ui_story_5051_50511401_43_dialog_content = "マイム様がいらっしゃらなかったら、\nカルティマ家はとうの昔にソルラドに見捨てられていました。",
  ui_story_5051_50511401_44_dialog_content = "その話はよしてくれ。",
  ui_story_5051_50511401_45_dialog_content = "いいえ、言わせてください！",
  ui_story_5051_50511401_46_dialog_content = "ここ数年マイム様がカルティマ家に尽くしてきたことは、皆がよく知っています。",
  ui_story_5051_50511401_47_dialog_content = "私たちは望んでマイム様に付いてきたのです。何の恨み言もありません！",
  ui_story_5051_50511401_48_dialog_content = "それなのにソルラドときたら、\n大貴族はみな影ノ街に応援の兵を送るのに反対しているのを知りながら…",
  ui_story_5051_50511401_49_dialog_content = "今日の儀式でマイム様に奴に従い影ノ街に支援の兵を送ると誓わせようとしました。",
  ui_story_5051_50511401_50_dialog_content = "我々カルティマ家を他の一族の矢面に立たせ、\n自身の輝かしい功績の盾としようとしたのです。",
  ui_story_5051_50511401_51_dialog_content = "ソルラドの利益のために暗鬼の餌食になるくらいなら…",
  ui_story_5051_50511401_52_dialog_content = "カルティマ家のためにこの命を捧げます！",
  ui_story_5051_50511401_53_dialog_content = "<size=45>カルティマのために！カルティマのために！カルティマのために！</size>",
  ui_story_5051_50511401_54_dialog_content = "ハハハ、よし！だが、一つだけ間違っているぞ。",
  ui_story_5051_50511401_55_dialog_content = "この勝負、まだ勝敗は決していない！",
  ui_story_5051_50511401_56_dialog_content = "マイム様…おっしゃる通りです！",
  ui_story_5051_50511401_57_dialog_content = "我々はマイム様に従い、カルティマ家が失った栄光をことごとく奪い返してみせます！",
  ui_story_5051_50511401_58_dialog_content = "準備は万全です。後はご命令を待つのみです。",
  ui_story_5051_50511401_59_dialog_content = "我々は死してもカルティマの栄光を守ります！",
  ui_story_5051_50511401_60_dialog_content = "<size=45>カルティマの栄光を！カルティマの栄光を！カルティマの栄光を！</size>",
  ui_story_5051_50511401_61_dialog_content = "よし！",
  ui_story_5051_50511401_62_dialog_content = "では、我々の最後の戦士を迎えるとしよう。",
  ui_story_5051_50511401_63_dialog_content = "最後の戦士…ですか？",
  ui_story_5051_50511401_64_dialog_content = "「空を舞う飛天の龍よ、我がカルティマの永遠の伴侶よ」",
  ui_story_5051_50511401_65_dialog_content = "「その双翼を広げ、果て無く続く闇夜を切り裂き」",
  ui_story_5051_50511401_66_dialog_content = "「我が元へ舞い降りよ」",
  ui_story_5051_50511401_67_dialog_content = "「我々の元へ舞い降りよ」",
  ui_story_5051_50511401_68_dialog_content = "「カルティマはこの誓約を忘れたことはない」",
  ui_story_5051_50511401_69_dialog_content = "<anim type=Shake><size=45>グォアアア！</size></anim>",
  ui_story_5051_50511401_70_dialog_content = "この声は…",
  ui_story_5051_50511401_71_dialog_content = "マイム様、まさか<color=#FFB400>ドラゴン</color>を召喚なさったのですか！？",
  ui_story_5051_50511401_72_dialog_content = "ドラゴンは我がカルティマの最も忠実なる友だ。",
  ui_story_5051_50511401_73_dialog_content = "カルティマの力を恐れる者が我らが先祖に龍脈は不吉の象徴だと吹き込み、\n信じさせたにすぎない。",
  ui_story_5051_50511401_74_dialog_content = "まさか、それがソルラド家だったのですか…？",
  ui_story_5051_50511401_75_dialog_content = "<size=45>出でよ、ガノン！友と家族の元へ舞い降りよ！</size>",
  ui_story_5051_50511401_76_dialog_content = "<anim type=Shake><size=45>グオオ――！</size></anim>",
  ui_story_5051_50511401_77_dialog_content = "我々はもう異様な視線を恐れる必要などない。",
  ui_story_5051_50511401_78_dialog_content = "<anim type=Shake><size=45>グオオ――！</size></anim>",
  ui_story_5051_50511401_79_dialog_content = "カルティマの者たちよ！",
  ui_story_5051_50511401_80_dialog_content = "今、ドラゴンが我々の元に戻った！",
  ui_story_5051_50511401_81_dialog_content = "ドラゴンは我々を助け、白夜城の主宰となる！",
  ui_story_5051_50511401_82_dialog_content = "ドラゴン万歳！",
  ui_story_5051_50511401_83_dialog_content = "<anim type=Shake><size=45>グオオ――！！</size></anim>",
  ui_story_5051_50511401_84_dialog_content = "<color=#e8d9bb>同じ頃、影ノ街では</color>",
  ui_story_5051_50511401_85_dialog_content = "今の音、聞こえたか？",
  ui_story_5051_50511401_86_dialog_content = "耳鳴りかと思ったよ！",
  ui_story_5051_50511401_87_dialog_content = "まさか暗鬼が攻めてきたのか！？",
  ui_story_5051_50511401_88_dialog_content = "バカなこと言ってないで…さっさと帰ろう！",
  ui_story_5051_50511401_89_dialog_content = "そうだな、どうせなら家で死を待とうじゃないか。",
  ui_story_5051_50511401_90_dialog_content = "私の知っている影ノ街はこんなにジメジメとしていなかった。",
  ui_story_5051_50511401_91_dialog_content = "ここから眺める白夜城は…",
  ui_story_5051_50511401_92_dialog_content = "やはり違う。",
  ui_story_5051_50511401_93_dialog_content = "白夜城の夜はここよりも寒かった気がする。",
  ui_story_5051_50511401_94_dialog_content = "今の鳴き声は…暗鬼ですか？",
  ui_story_5051_50511401_95_dialog_content = "いや、暗鬼ではない。",
  ui_story_5051_50511401_96_dialog_content = "暗鬼じゃないなら、何なんですか？",
  ui_story_5051_50511401_97_dialog_content = "見よ、やってきた。",
  ui_story_5051_50511401_98_dialog_content = "<anim type=Shake><size=45>グオオ――！！</size></anim>",
  ui_story_5051_50511401_99_dialog_content = "龍…ドラゴンか？",
  ui_story_5051_50511401_100_dialog_content = "フッ、案の定ドラゴンの怨恨に目をくらまされたか。",
  ui_story_5051_50511401_101_dialog_content = "カルティマの血は永遠にあの身売り契約から逃れられぬというわけか。",
  ui_story_5051_50511401_102_dialog_content = "ドラゴンが近づいてきます！",
  ui_story_5051_50511401_103_dialog_content = "ヴェロニカ、下がっておれ！",
  ui_story_5051_50511401_104_dialog_content = "見せてもらうとしよう。ドラゴンにいったい何ができるのかを。",
  ui_story_5051_50511401_105_dialog_content = "あのドラゴンは巨大だ。灼熱の炎を吐き出す。",
  ui_story_5051_50511401_106_dialog_content = "深手を負いたくなければ、最初の一手で弱点を突け。",
  ui_story_5051_50511401_107_dialog_content = "ドラゴンの弱点は…",
  ui_story_5051_50511401_108_dialog_content = "もちろん、知っておる。",
  ui_story_5051_50511401_109_dialog_content = "あれ、聞かないで行っちゃいましたよ？",
  ui_story_5051_50511401_110_dialog_content = "どうやら、この戦いは時間がかかりそうだな。",
  ui_story_5051_50511401_111_dialog_content = "当時ドラゴンの弱点はどこか知らなかったんですか？",
  ui_story_5051_50511401_112_dialog_content = "それとも…最初の一手で弱点を突けなかったんですか？",
  ui_story_5051_50511401_113_dialog_content = "…",
  ui_story_5051_50511401_114_dialog_content = "<color=#e8d9bb>ヒュウゥ…</color>",
  ui_story_5051_50511401_115_dialog_content = "風が出て来たな。あの時風はなかった。",
  ui_story_5051_50511401_116_dialog_content = "（さっきの質問はわざと無視したのかな…）",
  ui_story_5051_50511401_117_dialog_content = "か、風です…風向きを利用できれば、もしかしたら…",
  ui_story_5051_50511401_118_dialog_content = "戦いはすぐに終わるやもしれぬ。",
  ui_story_5051_50511401_119_dialog_content = "ハア――！！",
  ui_story_5051_50511401_120_dialog_content = "「白夜の光よ！」",
  ui_story_5051_50511401_121_dialog_content = "<anim type=Shake>グオオ！！</anim>",
  ui_story_5051_50511401_122_dialog_content = "（攻撃がドラゴンののどに命中した…一時的に炎を吐けなくなったのかな？）",
  ui_story_5051_50511401_123_dialog_content = "（のどが弱点ってこと？）",
  ui_story_5051_50511401_124_dialog_content = "（よく見えないけど、ドラゴンの背に…誰かいるみたいだ…）",
  ui_story_5051_50511401_125_dialog_content = "マイム・カルティマ！",
  ui_story_5051_50511401_126_dialog_content = "え？入城する時に会った、あの騎士団長さん…？",
  ui_story_5051_50511401_127_dialog_content = "ハハハ、ドラゴンの攻撃とはこの程度か？",
  ui_story_5051_50511401_128_dialog_content = "全力を出すまでもない。",
  ui_story_5051_50511401_129_dialog_content = "運よく攻撃をかわしたな。",
  ui_story_5051_50511401_130_dialog_content = "尊き城主様、運も実力のうちだと思わない方がいいぞ。",
  ui_story_5051_50511401_131_dialog_content = "たまたまガノンの炎を逃れられたにすぎない…\nたまたま城主の椅子に座れたにすぎないようにな。",
  ui_story_5051_50511401_132_dialog_content = "ガノン？ドラゴンに名前を付けたか。",
  ui_story_5051_50511401_133_dialog_content = "愚かなことをしたものだな、マイム。",
  ui_story_5051_50511401_134_dialog_content = "それが命を落とした時、胸を痛めることになるというに。",
  ui_story_5051_50511401_135_dialog_content = "無駄口を叩くのもそこまでだ！",
  ui_story_5051_50511401_136_dialog_content = "ガノン、行け！",
  ui_story_5051_50511401_137_dialog_content = "目の前のこの男に最も激しい炎をたっぷりと浴びせてやれ！",
  ui_story_5051_50511401_138_dialog_content = "お主からの「贈り物」なら、すでに肩にもらった。さらなる贈り物は遠慮しておこう。",
  ui_story_5051_50511401_139_dialog_content = "今度は余が「返礼」を贈ろうではないか！",
  ui_story_5051_50511401_140_dialog_content = "「暗夜を破れ、永久の日輪よ！」",
  ui_story_5051_50511401_141_dialog_content = "<color=#e8d9bb>ドーン！！</color>",
  ui_story_5051_50511401_142_dialog_content = "突撃だ！",
  ui_story_5051_50511401_143_dialog_content = "反乱軍も突撃してきました…",
  ui_story_5051_50511401_144_dialog_content = "全員よく聞きなさい！",
  ui_story_5051_50511401_145_dialog_content = "戦闘準備です！",
  ui_story_5051_50511401_146_dialog_content = "…",
  ui_story_5051_50511401_147_dialog_content = "ミヤも行くの？",
  ui_story_5051_50511401_148_dialog_content = "できることなら、武器を同胞の血で染めたくない…",
  ui_story_5051_50511401_149_dialog_content = "お父様、どうして私たちはこうしなきゃいけなかったんですか？",
  ui_story_5051_50511401_150_dialog_content = "あやつらが己の武器を我々の血で染めようとしたからだ。",
  ui_story_5051_50511402_1_dialog_content = "<anim type=Shake>グオオ…</anim>",
  ui_story_5051_50511402_2_dialog_content = "ガノン！逝かないでくれ！！",
  ui_story_5051_50511402_3_dialog_content = "これは現実ではない…",
  ui_story_5051_50511402_4_dialog_content = "こんなはずではなかった！！",
  ui_story_5051_50511402_5_dialog_content = "（若いソルラドさんは案の定風向きを利用して、見事ドラゴンを倒した…）",
  ui_story_5051_50511402_6_dialog_content = "（想像してたよりもずっと早く終わったね）",
  ui_story_5051_50511402_7_dialog_content = "マイム・カルティマ！",
  ui_story_5051_50511402_8_dialog_content = "白夜城の騎士団長たるもの、白夜城を守護する堅固な力となるべきである。",
  ui_story_5051_50511402_9_dialog_content = "だが、お主は白夜城に背き、騎士としての信仰に背いた。",
  ui_story_5051_50511402_10_dialog_content = "白夜城の民に取り返しのつかぬ経済的損失と精神的痛みを与えたのだ。",
  ui_story_5051_50511402_11_dialog_content = "白夜に捧ぐ！",
  ui_story_5051_50511402_12_dialog_content = "お主の行いは内乱罪に相当する。",
  ui_story_5051_50511402_13_dialog_content = "今この時をもって、お主の爵位および職位を永遠にはく奪する。",
  ui_story_5051_50511402_14_dialog_content = "監獄で法廷の最終審判を待つがよい。",
  ui_story_5051_50511402_15_dialog_content = "ハハハハハ、何を待てというのだ…",
  ui_story_5051_50511402_16_dialog_content = "ソルラド、今すぐここで殺せ！",
  ui_story_5051_50511402_17_dialog_content = "一族の者に会いたくはないのか？",
  ui_story_5051_50511402_18_dialog_content = "…クッ！",
  ui_story_5051_50511402_19_dialog_content = "全部私がやったことだ。一族の者たちは関係ない！",
  ui_story_5051_50511402_20_dialog_content = "私が奴らを脅し、無理やり共に兵を挙げさせたのだ…",
  ui_story_5051_50511402_21_dialog_content = "お前にまだ良心があるなら、老人子どもは許してやってくれ！",
  ui_story_5051_50511402_22_dialog_content = "事ここに至っては、余一人で決められぬ。",
  ui_story_5051_50511402_23_dialog_content = "今申したことは法廷に託せ。",
  ui_story_5051_50511402_24_dialog_content = "法廷は必ずや公正な裁決を下すだろう。",
  ui_story_5051_50511402_25_dialog_content = "フフッ…",
  ui_story_5051_50511402_26_dialog_content = "<anim type=Shake><size=45>アハハハハハハハ！</size></anim>",
  ui_story_5051_50511402_27_dialog_content = "カルティマを救えるのは、やはり私ではなかったか…",
  ui_story_5051_50511402_28_dialog_content = "長老の言葉が本当なら、奴が必ず私の果たせなかった使命を果たすだろう！",
  ui_story_5051_50511402_29_dialog_content = "カルティマはお主自らの手で滅ぼしたのだ。",
  ui_story_5051_50511402_30_dialog_content = "お主が約束通り、人々の前で余と共に影ノ街の支援へ向かうと誓うのならば…",
  ui_story_5051_50511402_31_dialog_content = "別の結末も有り得るやもしれぬ。",
  ui_story_5051_50511402_32_dialog_content = "クッ…",
  ui_story_5051_50511402_33_dialog_content = "ふざけるな！",
  ui_story_5051_50511402_34_dialog_content = "危ない！！",
  ui_story_5051_50511402_35_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5051_50511402_36_dialog_content = "ううっ…",
  ui_story_5051_50511402_37_dialog_content = "（もう形勢が逆転することなんて有り得ないと知りながら、\nマイムは一か八かで反撃しようとした…？）",
  ui_story_5051_50511402_38_dialog_content = "マイム・カルティマ。お主のその勇気を讃えよう。",
  ui_story_5051_50511402_39_dialog_content = "Ms.ロト、後は任せたぞ。",
  ui_story_5051_50511402_40_dialog_content = "余はカレンの様子を見てくる。議事堂で待っておれ。",
  ui_story_5051_50511402_41_dialog_content = "承知いたしました！",
  ui_story_5051_50511501_1_dialog_content = "ヨシュア、戻ったぞ。",
  ui_story_5051_50511501_2_dialog_content = "ダニエル…",
  ui_story_5051_50511501_3_dialog_content = "早く見せてちょうだい。傷口は開いていない？傷は増えていないわよね？",
  ui_story_5051_50511501_4_dialog_content = "安心しろ、ヨシュア。お主には余計な心配はかけぬと申したであろう。",
  ui_story_5051_50511501_5_dialog_content = "それよりも、カレンの具合はどうだ？",
  ui_story_5051_50511501_6_dialog_content = "お医者様に見ていただいたわ。大したことないそうよ。数日休めばよくなるわ。",
  ui_story_5051_50511501_7_dialog_content = "ならばよい。",
  ui_story_5051_50511501_8_dialog_content = "お夕食の準備ができているわ。少しでも食べてちょうだい。",
  ui_story_5051_50511501_9_dialog_content = "いや、まだやらねばならぬことがある。",
  ui_story_5051_50511501_10_dialog_content = "先に休め。",
  ui_story_5051_50511501_11_dialog_content = "ダニエル、今日はあなた一日中忙しくしてたのよ。\n休まなければならないのはあなたよ。",
  ui_story_5051_50511501_12_dialog_content = "カルティマの一件について、\nすぐにでも元老院および法廷の者たちと協議せねばならぬのだ。",
  ui_story_5051_50511501_13_dialog_content = "すまぬ、ヨシュア。",
  ui_story_5051_50511501_14_dialog_content = "この一件が落ち着いたら、家族4人でゆっくり食卓を囲もう。",
  ui_story_5051_50511501_15_dialog_content = "ダニエル…教えてもらえるかしら？カルティマ家はどうなるの？",
  ui_story_5051_50511501_16_dialog_content = "お主が気をもむことではない。\nただ、カルティマ家がそれ相応の代償を払うことになるのは確実だ。",
  ui_story_5051_50511501_17_dialog_content = "何も知らなかった者も？",
  ui_story_5051_50511501_18_dialog_content = "その人たちまで巻き添えになるの？",
  ui_story_5051_50511501_19_dialog_content = "ヨシュア、忘れてはならん。",
  ui_story_5051_50511501_20_dialog_content = "カルティマの者は今日、その冷ややかな刃を我々に、\n我々の愛する娘に向けたのだぞ。",
  ui_story_5051_50511501_21_dialog_content = "反乱を起こした時、我々の娘には罪のないことをあやつらは考えたろうか！？",
  ui_story_5051_50511501_22_dialog_content = "でも…",
  ui_story_5051_50511501_23_dialog_content = "ダニエル、1つ答えてちょうだい。",
  ui_story_5051_50511501_24_dialog_content = "あなたはカルティマが反乱を起こそうとしてたこと、前々から知っていたの…？",
  ui_story_5051_50511501_25_dialog_content = "誰から聞いたのだ？",
  ui_story_5051_50511501_26_dialog_content = "あなたよ、ダニエル。最近行動がおかしかったわ。",
  ui_story_5051_50511501_27_dialog_content = "おかしなことを考えるでない。",
  ui_story_5051_50511501_28_dialog_content = "でも、どうして今日、あなたは暗鬼の襲撃が2回あることを知っていたの？",
  ui_story_5051_50511501_29_dialog_content = "それに…",
  ui_story_5051_50511501_30_dialog_content = "わたくしと練習していた頃は、\n50m以上先のわずかな動きも察知することができていたはず。",
  ui_story_5051_50511501_31_dialog_content = "それなのに、なぜ今日刺客があれだけ堂々と襲ってきても、反応しなかったのかしら？",
  ui_story_5051_50511501_32_dialog_content = "もしかして…<color=#FFB400>わざと</color>だったのかしら？",
  ui_story_5051_50511501_33_dialog_content = "ただ、どう考えても、あなたがそうした理由が分からないの。",
  ui_story_5051_50511501_34_dialog_content = "ケガをすれば、同情を得られて、カルティマの罪を確実なものにできるから？",
  ui_story_5051_50511501_35_dialog_content = "お主の思っているようなことではない。",
  ui_story_5051_50511501_36_dialog_content = "あやつらの計画を知っていたら、お主と子どもたちを連れて行くわけがなかろう？",
  ui_story_5051_50511501_37_dialog_content = "！！！",
  ui_story_5051_50511501_38_dialog_content = "わたくしとカレンがそばにいれば、反乱軍は疑うことなく計画通りに事を進める…",
  ui_story_5051_50511501_39_dialog_content = "あなたはわたくしたちを<color=#FFB400>コマ</color>にしたの？",
  ui_story_5051_50511501_40_dialog_content = "…",
  ui_story_5051_50511501_41_dialog_content = "余は白夜城の主、この浮空島の将来は我が肩にかかっている。",
  ui_story_5051_50511501_42_dialog_content = "目的を果たすためならば、己をコマとすることもいとわぬ。",
  ui_story_5051_50511501_43_dialog_content = "それが我々に課せられた責任なのだ、ヨシュア。",
  ui_story_5051_50511501_44_dialog_content = "すべて暗鬼に対抗する力を得るためにしているってことくらい、分かっているわ。",
  ui_story_5051_50511501_45_dialog_content = "でも、どうして話してくれないの？",
  ui_story_5051_50511501_46_dialog_content = "2人ならもっといい方法が見つけられるかもしれないわ。",
  ui_story_5051_50511501_47_dialog_content = "…わたくしをコマにするのは構わないわ。",
  ui_story_5051_50511501_48_dialog_content = "でも、まだ幼い子どもたちまで本当にコマにできるの？",
  ui_story_5051_50511501_49_dialog_content = "今日万が一カレンが本当に…",
  ui_story_5051_50511501_50_dialog_content = "さようなこと余がさせぬ。",
  ui_story_5051_50511501_51_dialog_content = "実際、カレンは無事ではないか？",
  ui_story_5051_50511501_52_dialog_content = "今回は運がよかったのよ。でも万が一ってこともあるでしょう？",
  ui_story_5051_50511501_53_dialog_content = "もし次にもこういうことがあったら、前もってわたくしにも話すと約束してくれる？",
  ui_story_5051_50511501_54_dialog_content = "実際の政は書籍に書かれているよりもはるかに複雑なのだ。",
  ui_story_5051_50511501_55_dialog_content = "ヨシュア、お主を愛している…",
  ui_story_5051_50511501_56_dialog_content = "だからこそ、お主までこの汚れた渦の中に巻き込みたくはないのだ。",
  ui_story_5051_50511501_57_dialog_content = "一緒に勉強してた頃は、そんなこと言ってなかったわ。",
  ui_story_5051_50511501_58_dialog_content = "あなたは、わたくしと一緒に白夜城を変えると言ったのよ。",
  ui_story_5051_50511501_59_dialog_content = "今はもう、わたくしを信じてくださらないのね。",
  ui_story_5051_50511501_60_dialog_content = "お主を信じなかったことなどない。この家も任せているではないか。",
  ui_story_5051_50511501_61_dialog_content = "同じように、余の政における判断も信じてもらわねば。",
  ui_story_5051_50511501_62_dialog_content = "他の一族を犠牲にして、自身の統治を確固たるものにするのね。",
  ui_story_5051_50511501_63_dialog_content = "それがあなたの熟慮の末の結論なら――",
  ui_story_5051_50511501_64_dialog_content = "ダニエル…あなた、変わってしまったわ。",
  ui_story_5051_50511501_65_dialog_content = "城主の地位を確固たるものにするため、手段を選ばなくなった。",
  ui_story_5051_50511501_66_dialog_content = "いえ、手段を選ばないだけじゃないわ。",
  ui_story_5051_50511501_67_dialog_content = "あなたの心は北境の山の頂を覆う氷と雪よりも冷たくなってしまったわ！",
  ui_story_5051_50511501_68_dialog_content = "ヴェロニカはあなたのせいで怪物扱いされて…",
  ui_story_5051_50511501_69_dialog_content = "カレンも遅かれ早かれ、あなたのために命を犠牲にするのでしょう…？",
  ui_story_5051_50511501_70_dialog_content = "そしてわたくしも…あなたのそばを離れて、この世界から完全に消えてしまうのね…",
  ui_story_5051_50511501_71_dialog_content = "ヨシュア…ヨシュア！",
  ui_story_5051_50511501_72_dialog_content = "愛しいヨシュア！",
  ui_story_5051_50511501_73_dialog_content = "何ゆえだ？",
  ui_story_5051_50511501_74_dialog_content = "<size=45>何ゆえ余から離れていくのだ！？</size>",
  ui_story_5051_50511501_75_dialog_content = "<anim type=Shake>はぁ…はぁ…はぁ…</anim>",
  ui_story_5051_50511501_76_dialog_content = "ご気分が悪いのですか？",
  ui_story_5051_50511501_77_dialog_content = "ヨシュア！",
  ui_story_5051_50511501_78_dialog_content = "あら、ソロスさん、どうなさいました？",
  ui_story_5051_50511501_79_dialog_content = "「父さん」、そのままじゃ城主夫人がケガをしてしまいますよ…",
  ui_story_5051_50511501_80_dialog_content = "ああ、失礼した。",
  ui_story_5051_50511501_X80_dialog_content = "突然よく見る悪夢を思い出したのだ。",
  ui_story_5051_50511501_81_dialog_content = "歳であろう。少し休んだ方がよいやもしれぬ。",
  ui_story_5051_50511501_82_dialog_content = "では、ゆっくりお休みください。後ほど一緒にお食事しましょう。",
  ui_story_5051_50511501_83_dialog_content = "ヨシュア、もてなしご苦労だった。",
  ui_story_5051_50511501_84_dialog_content = "お夕食がもうすぐ準備できるわ。一緒に食堂へ行きましょう。",
  ui_story_5051_50511501_85_dialog_content = "いや、まだやらねばならぬことがある。",
  ui_story_5051_50511501_86_dialog_content = "お主らは先に食事をして早めに休め。",
  ui_story_5051_50511501_87_dialog_content = "ダニエル、今日はあなた一日中忙しくしてたのよ。\n休まなければならないのはあなたよ。",
  ui_story_5051_50511501_88_dialog_content = "…",
  ui_story_5051_50511501_89_dialog_content = "<size=30>PlayerName、急ぎ皆の注意を引きつけよ！</size>",
  ui_story_5051_50511501_90_dialog_content = "<size=30>え？どうしてですか？</size>",
  ui_story_5051_50511501_91_dialog_content = "<size=30>でなければ、これから二度と見たくもない言い争いが始まってしまうのだ…</size>",
  ui_story_5051_50511501_92_dialog_content = "カルティマの一件について、\nすぐにでも元老院および法廷の者たちと協議せねばならぬのだ。",
  ui_story_5051_50511501_93_dialog_content = "すまぬ、ヨシュア。",
  ui_story_5051_50511501_94_dialog_content = "この一件が落ち着いたら、家族4人でゆっくり食卓を囲もう。",
  ui_story_5051_50511501_95_dialog_content = "いいですね！大賛成です！",
  ui_story_5051_50511501_96_dialog_content = "まあ！？",
  ui_story_5051_50511501_97_dialog_content = "仕事の終わってない人は仕事して、休むべき人は残って休む――",
  ui_story_5051_50511501_98_dialog_content = "すごくいいと思います…誰にとっても、いいと思います。",
  ui_story_5051_50511501_99_dialog_content = "うむ。余も子どもたちも今日はろくに食事も摂っておらぬ。",
  ui_story_5051_50511501_100_dialog_content = "では、ソロス殿。ゆっくり休まれよ。改めて話すとしよう。",
  ui_story_5051_50511501_101_dialog_content = "では、これで。",
  ui_story_5051_50511501_102_dialog_content = "…",
  ui_story_5051_50511501_103_dialog_content = "本当にあのままもう行ってしまったのかしら。",
  ui_story_5051_50511501_104_dialog_content = "ソロスさん、申し訳ありません。皆さんももうしばらくお待ちください。",
  ui_story_5051_50511501_105_dialog_content = "夕食をすぐに準備しますから。",
  ui_story_5051_50511501_106_dialog_content = "…お頼みする。",
  ui_story_5051_50511501_107_dialog_content = "僕には想像できません。こんなに穏やかなヨシュア夫人と言い争いなんて。",
  ui_story_5051_50511501_108_dialog_content = "お父様とお母様は過去のこの日…言い争いをしたんですか？",
  ui_story_5051_50511501_109_dialog_content = "…",
  ui_story_5051_50511501_110_dialog_content = "自分のしたことを認めないのですか？",
  ui_story_5051_50511501_111_dialog_content = "カレブさん！？どこから湧いて出たんです？",
  ui_story_5051_50511501_112_dialog_content = "お…叔父様？",
  ui_story_5051_50511501_113_dialog_content = "カレブ、ジャキーニを置いて独りどこかへ行っていたと聞いた。\nお主、いつになったら落ち着くのだ？",
  ui_story_5051_50511501_114_dialog_content = "話をそらさないでください、城主様。",
  ui_story_5051_50511501_115_dialog_content = "自分のしたことなのに認めないのですか？",
  ui_story_5051_50511501_116_dialog_content = "僕が思い出させてさしあげましょう。",
  ui_story_5051_50511501_117_dialog_content = "あの時の言い争いが原因で、姉さんは幼いカレンを連れて宮殿を離れました。",
  ui_story_5051_50511501_118_dialog_content = "それ以降、あなたたちは二度と言葉を交わすこともなく、\n家庭の温かみのある食事を共にすることもありませんでした…",
  ui_story_5051_50511501_119_dialog_content = "姉さんが戦場から息も絶え絶えになったヴェロニカを連れ帰るまでは。",
  ui_story_5051_50511501_120_dialog_content = "あなたは暗鬼との戦いに没頭しているふりをしていましたが、\n本当はただ姉さんの目を見るのが恐ろしかっただけだ…",
  ui_story_5051_50511501_121_dialog_content = "その後これまた自身の政における目的を果たすために、\n負傷したヴェロニカを啓光の実験室へと送りました。",
  ui_story_5051_50511501_122_dialog_content = "ですが、まさかその実験室というのが狂気の研究者が操る修羅場だったとは。",
  ui_story_5051_50511501_123_dialog_content = "姉さんは再びヴェロニカを危機から救い出しましたが、\nそれが原因で重い病にかかってしまった…",
  ui_story_5051_50511501_124_dialog_content = "間違いありませんね、「兄さん」。",
  ui_story_5051_50511501_125_dialog_content = "<color=#FFB400>啓光の実験室</color>…うっ、頭が痛いわ。",
  ui_story_5051_50511501_126_dialog_content = "ミヤ、座って休むといいよ。無理して思い出さなくていいんだ。",
  ui_story_5051_50511501_127_dialog_content = "…",
  ui_story_5051_50511501_128_dialog_content = "カレブさん、いったいどこへ行ってたんです？",
  ui_story_5051_50511501_129_dialog_content = "ずっと連絡がなかったんで、まさかここから出たくなくなったのかと思いましたよ！",
  ui_story_5051_50511501_130_dialog_content = "僕はずっとここにいましたよ。\nただ「あの人」はこの姿を僕だと分からなかっただけです。",
  ui_story_5051_50511501_131_dialog_content = "また僕が目の前に現れたら、「姉さん」を困らせてしまう…",
  ui_story_5051_50511501_132_dialog_content = "…だから、これ以上ここにいるわけにはいきません。",
  ui_story_5051_50511501_133_dialog_content = "ジャキーニさん、早く僕を連れ出してください！",
  ui_story_5051_50511501_134_dialog_content = "あった途端にそんな直球型の要求を突きつけるんですか？",
  ui_story_5051_50511501_135_dialog_content = "これで全員そろいましたよ。戻らない理由がありますか？",
  ui_story_5051_50511501_136_dialog_content = "前に言っていたでしょう？早く「記憶の鏡晶」の中から出ないと危険だと。",
  ui_story_5051_50511501_137_dialog_content = "それはその通りですよ。",
  ui_story_5051_50511501_138_dialog_content = "では、みなさん、準備はいいですか？",
  ui_story_5051_50511501_139_dialog_content = "「お母様」が夕食を一緒に食べようと待ってるわ…",
  ui_story_5051_50511501_140_dialog_content = "まだ時間はあろう。しばし留まってもよいのではないか？",
  ui_story_5051_50511501_141_dialog_content = "ソルラドさんはずっと早くここを出たがって、僕たちを急かしてませんでしたか？",
  ui_story_5051_50511501_142_dialog_content = "それは我々が危険な状況にあったからだ。",
  ui_story_5051_50511501_143_dialog_content = "今や最も危険な時は過ぎ去った。",
  ui_story_5051_50511501_144_dialog_content = "それにもし…",
  ui_story_5051_50511501_145_dialog_content = "（カレブの申した通りだ。あの時の言い争いがすべての不幸の始まりだった）",
  ui_story_5051_50511501_146_dialog_content = "（あの日余は確かに白夜城のすべての貴族の支持を得ることに成功したが、\n愛する者の心を深く傷つけてしまった）",
  ui_story_5051_50511501_147_dialog_content = "お父様？",
  ui_story_5051_50511501_148_dialog_content = "それにもし、今我々がここを離れれば…",
  ui_story_5051_50511501_149_dialog_content = "「ヨシュア」はまたあの時と同じように、独り不穏な一夜を過ごさねばならぬ。",
  ui_story_5051_50511501_150_dialog_content = "ソルラド、今さら善人のフリをして何になるのですか。",
  ui_story_5051_50511501_151_dialog_content = "カレブ、お主がヨシュアのことで余を憎んでいることは承知している。",
  ui_story_5051_50511501_152_dialog_content = "いかに後悔しようと時間は戻らぬ。やり直すことなどできぬ。",
  ui_story_5051_50511501_153_dialog_content = "お主の憎しみを受け入れよう。",
  ui_story_5051_50511501_154_dialog_content = "だが、もし今一度機会を与えてもらえるのならば、余はきっとヨシュアに…",
  ui_story_5051_50511501_155_dialog_content = "アハハ、今さらそんなことを言っても無意味ですよ。",
  ui_story_5051_50511501_156_dialog_content = "この世界はそもそもニセモノなのですから…",
  ui_story_5051_50511501_157_dialog_content = "ここでいくらざん悔しようと、何も変わりません！",
  ui_story_5051_50511501_158_dialog_content = "お、叔父様…",
  ui_story_5051_50511501_159_dialog_content = "私も「お母様」にきちんとお別れがしたいんです。",
  ui_story_5051_50511501_160_dialog_content = "この世界はニセモノだけど、みんなの気持ちまでもニセモノとは限りません。",
  ui_story_5051_50511501_161_dialog_content = "だから…最後に少しだけ時間をください。",
  ui_story_5051_50511501_162_dialog_content = "じ、実は…私もある人とお別れがしたいんです。",
  ui_story_5051_50511501_163_dialog_content = "とにかくまだ時間はありますし、ひとまず危険もありませんから…",
  ui_story_5051_50511501_164_dialog_content = "みんなできちんとお別れをしてから戻りましょうよ！",
  ui_story_5051_50511501_165_dialog_content = "だって、次に入ってきた時にはもう、\nここの人たちは私たちのこと忘れてるかもしれないんですから。",
  ui_story_5051_50511501_166_dialog_content = "あなたたちという人は…！",
  ui_story_5051_50511501_167_dialog_content = "PlayerName、「ヨシュア」に別れを告げるのに付き合ってくれぬか？",
  ui_story_5051_50511501_168_dialog_content = "今のあやつにとって余は夫ではない。\nお主を連れて行かねば、女性に対して無礼になる。",
  ui_story_5051_50511501_169_dialog_content = "でも、僕の父親って立場じゃ、言いたいことも伝えられないんじゃありませんか？",
  ui_story_5051_50511501_170_dialog_content = "「ヨシュア」さんがソルラドさんだと分かってくれればいいんですけど…",
  ui_story_5051_50511501_171_dialog_content = "あ、ねえジャキーニ、君は「記憶の鏡晶」を操れるんだよね？",
  ui_story_5051_50511501_172_dialog_content = "「ヨシュア」さんにソルラドさんだって分かってもらう方法はないかな？",
  ui_story_5051_50511501_173_dialog_content = "方法はないわけじゃありません。",
  ui_story_5051_50511501_174_dialog_content = "ただ…試したことないので、また何か問題が起こるかもしれませんよ。",
  ui_story_5051_50511501_175_dialog_content = "構わぬ、試してみよ。",
  ui_story_5051_50511501_176_dialog_content = "城主様はまだ私を信じてくれるんですか？",
  ui_story_5051_50511501_177_dialog_content = "城主様の悔いを晴らすためなら、私なんでもやります！",
  ui_story_5051_50511501_178_dialog_content = "ただ…えへへ。",
  ui_story_5051_50511501_179_dialog_content = "まずは調べさせてください！",
  ui_story_5051_50511501_180_dialog_content = "…コホン、ソルラドさん、本当に大丈夫でしょうか？",
  ui_story_5051_50511501_181_dialog_content = "PlayerName、余は10数年避け続けてきた…",
  ui_story_5051_50511501_182_dialog_content = "余には今回この世界に入ってきたことが単純な予想外の事態とは思えぬのだ。",
  ui_story_5051_50511501_183_dialog_content = "光の神が導いてくれたのやもしれぬ。",
  ui_story_5051_50511501_184_dialog_content = "己の弱さに向き合うべき時が来たのだ。",
  ui_story_5051_50511501_185_dialog_content = "城主様、先に言っておきますが、この幻術は少しの間しか持ちません。",
  ui_story_5051_50511501_186_dialog_content = "姿が戻ってしまう前に帰ってきてくださいね。",
  ui_story_5051_50511501_187_dialog_content = "準備はできている。",
  ui_story_5051_50511501_188_dialog_content = "じゃあ始めますよ～！",
  ui_story_5051_50511501_189_dialog_content = "ミュタティーオ～ミュタティーオ～ミュタティーオ！",
  ui_story_5051_50511501_190_dialog_content = "ダニエル・ソルラドを若い時の姿に戻してください！",
  ui_story_5051_50511501_191_dialog_content = "アブラカダブラ！",
  ui_story_5051_50511501_192_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5051_50511501_193_dialog_content = "え！？",
  ui_story_5051_50511501_194_dialog_content = "PlayerName、いかがした？何ゆえ驚いておる？",
  ui_story_5051_50511501_195_dialog_content = "ソルラドさんの若い時の姿…やっぱり衝撃的ですね。",
  ui_story_5051_50511501_196_dialog_content = "ううっ…",
  ui_story_5051_50511501_197_dialog_content = "うーん…ジャキーニ、\nどうしてソルラドさんが下級裁判官の兄弟みたいになってるのかな…？",
  ui_story_5051_50511501_198_dialog_content = "下級裁判官だと！？",
  ui_story_5051_50511501_199_dialog_content = "オホン…たぶん興奮しすぎて、\n城主様の若い時の姿をちゃんと思い浮かべられなかったんでしょう…",
  ui_story_5051_50511501_200_dialog_content = "ジャキーニもさっき若い時の城主様に会ったでしょ？",
  ui_story_5051_50511501_201_dialog_content = "あ、そ、そうでした！",
  ui_story_5051_50511501_202_dialog_content = "これで大丈夫です。もう一度やってみます！",
  ui_story_5051_50511501_203_dialog_content = "ミュタティーオ～ミュタティーオ～ミュタティーオ！",
  ui_story_5051_50511501_204_dialog_content = "ダニエル・ソルラドを若い時の姿に戻してください！",
  ui_story_5051_50511501_205_dialog_content = "アブラカダブラ！",
  ui_story_5051_50511501_206_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5051_50511501_207_dialog_content = "衛兵、いるの？",
  ui_story_5051_50511501_208_dialog_content = "夕食の準備ができたわ。みなさんを呼んできてくれる？",
  ui_story_5051_50511501_209_dialog_content = "…",
  ui_story_5051_50511501_210_dialog_content = "衛兵？",
  ui_story_5051_50511501_211_dialog_content = "あら？",
  ui_story_5051_50511501_212_dialog_content = "……",
  ui_story_5051_50511501_213_dialog_content = "<size=30>すまぬ</size>",
  ui_story_5051_50511501_214_dialog_content = "え？何か言った？",
  ui_story_5051_50511501_215_dialog_content = "いや、何でもない。",
  ui_story_5051_50511501_216_dialog_content = "ダニエル、まさか今「すまぬ」って言ったの？",
  ui_story_5051_50511501_217_dialog_content = "ヨシュア…",
  ui_story_5051_50511501_218_dialog_content = "いいのよ。帰ってきてくれれば、それでいいの。",
  ui_story_5051_50511501_219_dialog_content = "疲れたら、帰ってきて。",
  ui_story_5051_50511501_220_dialog_content = "大丈夫よ。わたくしも子どもたちもずっとあなたのそばにいるから。",
  ui_story_5051_50511501_221_dialog_content = "…",
  ui_story_5051_50511501_222_dialog_content = "あなたは少し休んでいて。食器を用意させるわ。",
  ui_story_5051_50511501_223_dialog_content = "…",
  ui_story_5051_50511501_224_dialog_content = "ダニエル、そんなふうにつかんでたら、準備しにいけないわ。",
  ui_story_5051_50511501_225_dialog_content = "お主に伝えたいことがたくさんあるのだ。",
  ui_story_5051_50511501_226_dialog_content = "ようやく思い出してくれたのね。家に帰れば愚痴も言える家族がいるって。",
  ui_story_5051_50511501_227_dialog_content = "どんな話？今じゃなきゃダメかしら？",
  ui_story_5051_50511501_228_dialog_content = "うむ。",
  ui_story_5051_50511501_229_dialog_content = "そう。では、みなさんにはもうしばらくお腹を空かせていてもらいましょう。",
  ui_story_5051_50511501_230_dialog_content = "まずはあなたの話を聞いてあげなくちゃね。",
  ui_story_5051_50511501_231_dialog_content = "……",
  ui_story_5051_50511501_232_dialog_content = "…会いたかった。",
  ui_story_5051_50511501_233_dialog_content = "えっ？",
  ui_story_5051_50511501_234_dialog_content = "<color=#e8d9bb>別の場所では</color>",
  ui_story_5051_50511501_235_dialog_content = "ジャキーニさん、急いでください！",
  ui_story_5051_50511501_236_dialog_content = "どうして僕には呪文が効かないんですか？",
  ui_story_5051_50511501_237_dialog_content = "ああああ！急かさないでくださいって！\n呪文が効くか効かないかは気持ちの良しあしでも変わるんです！",
  ui_story_5051_50511501_238_dialog_content = "なんなら、さっきの石膏頭に変えてあげましょうか！？",
  ui_story_5051_50511501_239_dialog_content = "そ、そんな…！",
  ui_story_5051_50511501_240_dialog_content = "お父様は…ちゃんとお話できてるかしら？",
  ui_story_5051_50511501_241_dialog_content = "うーん、見たところ、ちゃんと話せてるんじゃないかな？とても仲良さそうだよ！？",
  ui_story_5051_50511501_242_dialog_content = "<size=45>あああ！ソルラドの偽君子め！姉さんに何するのですか！！</size>",
  ui_story_5051_50511501_243_dialog_content = "PlayerName…どうして急に目隠しするの？",
  ui_story_5051_50511501_244_dialog_content = "え？ミヤが急に僕に目隠ししたんじゃないの？",
  ui_story_5051_50511501_245_dialog_content = "オホン…お子様たちは…",
  ui_story_5051_50511501_246_dialog_content = "<size=45>これ以上見てはいけません！</size>",
  ui_story_5051_50511601_1_dialog_content = "ガーッ…ガーッ…ガーッ…",
  ui_story_5051_50511601_2_dialog_content = "まったく…酔い覚ましのスープを飲んだと思ったら、今度は熟睡ですか？",
  ui_story_5051_50511601_3_dialog_content = "でも、むしろこの方がよかったかもしれませんね！だって、何も気にせず…",
  ui_story_5051_50511601_4_dialog_content = "ママって呼べますもん…",
  ui_story_5051_50511601_5_dialog_content = "えへへ、どうしたんでしょうね。いざ話すとなるとちょっと恥ずかしいですね。",
  ui_story_5051_50511601_6_dialog_content = "10数年前ママが家を出て、修行で山に閉じこもってから、\n私はずっとママにもう一度会いたいって思ってきたんです。",
  ui_story_5051_50511601_7_dialog_content = "いつかきっと占いでママが修行してる場所を見つけようって思ってました。",
  ui_story_5051_50511601_8_dialog_content = "それから、ママは昔のままなのかなぁ…とか、色々考えてたんですよ…",
  ui_story_5051_50511601_9_dialog_content = "ママはいつもベールをかぶって、1人森の奥の小屋にこもって忙しくしてましたね。",
  ui_story_5051_50511601_10_dialog_content = "でも、10年以上が過ぎて、\n記憶の中のママの姿はもう、ぼんやりしてきちゃったんです。",
  ui_story_5051_50511601_11_dialog_content = "それが今日、白夜城で若い時のママに会えるなんて思ってもみませんでした！",
  ui_story_5051_50511601_12_dialog_content = "しかも、若い時のママがこんなに…頼りない人だったなんて、思いもしませんでしたよ！",
  ui_story_5051_50511601_13_dialog_content = "でも、記憶の中のママよりもずっと明るくて、可愛らしくて、怖いもの知らずでした…",
  ui_story_5051_50511601_14_dialog_content = "ママがいなくなった後、パパは私を連れて北境を離れようとしたんです。",
  ui_story_5051_50511601_15_dialog_content = "でも、私たちがいなくなったら、いつかママが帰ってきた時、\n家族がいなくなってしまうでしょう？だから私は1人で待つことにしたんです。",
  ui_story_5051_50511601_16_dialog_content = "でも、心配しないでくださいね。私にはたっくさん友だちがいるんですから！",
  ui_story_5051_50511601_17_dialog_content = "それから、ママが残してくれた占いの本で呪文も学びました…\n今はまだ未熟で、騒ぎばかり起こしてますが…",
  ui_story_5051_50511601_18_dialog_content = "で、でも、待っててくださいね！",
  ui_story_5051_50511601_19_dialog_content = "必ずボアーズの一番の弟子になって、\n「記憶の鏡晶」よりもすごい水晶玉を作ってみせますよ！",
  ui_story_5051_50511601_20_dialog_content = "それから…ふふっ、ママが北境のどこに隠れてるかも占いで見つけちゃいますから！",
  ui_story_5051_50511601_21_dialog_content = "とにかく、次に会う時まで楽しみにしててくださいね！",
  ui_story_5051_50511601_22_dialog_content = "いい子ね。",
  ui_story_5051_50511601_23_dialog_content = "あ、ああっ――！お、起きてたんですか？",
  ui_story_5051_50511601_24_dialog_content = "オホン、今のは適当にデタラメを言ってみただけです。気にしないでください。",
  ui_story_5051_50511601_25_dialog_content = "でも、私が何のことを言ってるのか、わかりませんよね…\nごめんなさい、起こしちゃって。私はただお別れを言いたかっただけなんです。",
  ui_story_5051_50511601_26_dialog_content = "あら？私の理解力が低いと言いたいの？",
  ui_story_5051_50511601_27_dialog_content = "だってずっと酔っぱらってて…",
  ui_story_5051_50511601_28_dialog_content = "…あれ？急に真面目くさってどうしたんですか？なんか慣れませんね。",
  ui_story_5051_50511601_29_dialog_content = "「記憶の鏡晶」の秘密を解くのは、あなたの未熟な腕じゃとうてい無理ね。",
  ui_story_5051_50511601_30_dialog_content = "水晶玉を作り出すなんて、なおさらだわ。",
  ui_story_5051_50511601_31_dialog_content = "ジャキーニ、それが本当にあなたのやりたいことなの？",
  ui_story_5051_50511601_32_dialog_content = "そうです！断言できます！",
  ui_story_5051_50511601_33_dialog_content = "…あれ、私を娘のジャキーニだって認めてなかったんじゃないですか？",
  ui_story_5051_50511601_34_dialog_content = "「あなた」は「私」の娘ジャキーニではないわ。",
  ui_story_5051_50511601_35_dialog_content = "でも、私には分かるの。あなたはジャキーニよ。",
  ui_story_5051_50511601_36_dialog_content = "ジャキーニさん、やっと帰ってきましたか。",
  ui_story_5051_50511601_37_dialog_content = "えへへ、ごめんなさい。つい長話しちゃいました。",
  ui_story_5051_50511601_38_dialog_content = "どうしたの、悩み事があるみたいだけど？",
  ui_story_5051_50511601_39_dialog_content = "え？そ、そうですか？",
  ui_story_5051_50511601_40_dialog_content = "そうだ、カレブさん。まだ試しますか？今度こそ若い時の姿に変えてみせますよ！",
  ui_story_5051_50511601_X41_dialog_content = "いいえ、結構です。またウサギにされても困りますから。",
  ui_story_5051_50511601_42_dialog_content = "シーッ…",
  ui_story_5051_50511601_43_dialog_content = "お父様とお母様のお邪魔になってしまうわ。",
  ui_story_5051_50511601_44_dialog_content = "え？城主様はまだ「ヨシュア」夫人とお別れをしてるんですか？",
  ui_story_5051_50511601_45_dialog_content = "この調子だと、もうしばらくかかりそうだよ…",
  ui_story_5051_50511601_46_dialog_content = "あら？子どもたちとお客様はまだいらっしゃらないの？",
  ui_story_5051_50511601_47_dialog_content = "皆…もう休んだのだ。",
  ui_story_5051_50511601_48_dialog_content = "そう、今日はきっと疲れていたのね。でも、食事しなかったら体力も回復しないわ。",
  ui_story_5051_50511601_49_dialog_content = "食事をお部屋に届けさせましょう…",
  ui_story_5051_50511601_50_dialog_content = "そのことなら余が申し付けておいた。お主は何もせんでよい。",
  ui_story_5051_50511601_51_dialog_content = "あら？ダニエル、あやしいわね。",
  ui_story_5051_50511601_52_dialog_content = "何か後ろめたいことでもあるのかしら？",
  ui_story_5051_50511601_53_dialog_content = "うしろめたい？",
  ui_story_5051_50511601_54_dialog_content = "そうよ。普段は政務で忙しい城主様が夫人をいたわるなんて、\nどういう風の吹き回しかしら？",
  ui_story_5051_50511601_55_dialog_content = "余はただ…",
  ui_story_5051_50511601_56_dialog_content = "もうずいぶんとこうして2人で食卓を囲んでいなかったな。",
  ui_story_5051_50511601_57_dialog_content = "それは確かにそうね。でも…あなたはもうそんなこと、気にしないと思っていたわ。",
  ui_story_5051_50511601_58_dialog_content = "すまぬ。",
  ui_story_5051_50511601_59_dialog_content = "もう分かったわ。どうかしたの？今日は謝ってばかりよ。",
  ui_story_5051_50511601_60_dialog_content = "なぜ「すまぬ」なんて言うのかしら？",
  ui_story_5051_50511601_61_dialog_content = "今は話せぬ。",
  ui_story_5051_50511601_62_dialog_content = "ダニエル…？",
  ui_story_5051_50511601_63_dialog_content = "カルティマ家のこと？",
  ui_story_5051_50511601_64_dialog_content = "ダニエル、あなた本当に誰一人として見逃す気はないの？",
  ui_story_5051_50511601_65_dialog_content = "…",
  ui_story_5051_50511601_66_dialog_content = "もちろん、さようなことはせぬ。",
  ui_story_5051_50511601_67_dialog_content = "処罰すべきは真に罪のある者たちだけだ。",
  ui_story_5051_50511601_68_dialog_content = "わたくしを慰めるために、そんなこと言っているのではなくて？",
  ui_story_5051_50511601_69_dialog_content = "そうではない、ヨシュア！",
  ui_story_5051_50511601_70_dialog_content = "<color=#e8d9bb>パリン！</color>",
  ui_story_5051_50511601_71_dialog_content = "む？ヨシュア？",
  ui_story_5051_50511601_72_dialog_content = "<anim type=Shake>…嘘よ</anim>",
  ui_story_5051_50511601_73_dialog_content = "ヨシュア？",
  ui_story_5051_50511601_74_dialog_content = "どうしたのだ？ヨシュア！",
  ui_story_5051_50511601_75_dialog_content = "<anim type=Shake>あなた…わたくしに…嘘を…ついているのね…</anim>",
  ui_story_5051_50511601_76_dialog_content = "ヨシュア、余のせいか？そのような姿になったのは、余のせいなのか？",
  ui_story_5051_50511601_77_dialog_content = "お主の反対も聞き入れず、余はカルティマを処罰した…",
  ui_story_5051_50511601_78_dialog_content = "お主の判断を信じず、お主の忠告を無視した…",
  ui_story_5051_50511601_79_dialog_content = "痛みをいたわってやることもなく、家の事をすべて当然かのようにお主に任せた…",
  ui_story_5051_50511601_80_dialog_content = "お主が必要としている時に、そばにいてやれなかった…",
  ui_story_5051_50511601_81_dialog_content = "…すまなかった！",
  ui_story_5051_50511601_82_dialog_content = "<color=#e8d9bb>ビリッ！パリン！</color>",
  ui_story_5051_50511601_83_dialog_content = "<anim type=Shake>ダニエル…</anim>",
  ui_story_5051_50511601_84_dialog_content = "ここだ、ヨシュア！余はここにいる！",
  ui_story_5051_50511601_85_dialog_content = "<anim type=Shake>ダニエル…ヴェロニカ…カレン…</anim>",
  ui_story_5051_50511601_86_dialog_content = "<anim type=Shake>ああああ！！</anim>",
  ui_story_5051_50511601_87_dialog_content = "ヨシュア！！",
  ui_story_5051_50511601_88_dialog_content = "お母様、お母様はどうなさったの？",
  ui_story_5051_50511601_89_dialog_content = "<color=#e8d9bb>ゴロゴロゴロ！</color>",
  ui_story_5051_50511601_90_dialog_content = "<color=#e8d9bb>ゴロゴロゴロ――！！</color>",
  ui_story_5051_50511601_91_dialog_content = "また雷の音だ…",
  ui_story_5051_50511601_92_dialog_content = "地震？地震ですか？",
  ui_story_5051_50511601_93_dialog_content = "そんなはずはありません。歴史では今晩地震など起こっていません！",
  ui_story_5051_50511601_94_dialog_content = "周りが…ぼんやりしてきた気がするわ。",
  ui_story_5051_50511601_95_dialog_content = "僕もだ！残りわずかな感知能力でなんとか方向が分かるくらいだよ。",
  ui_story_5051_50511601_96_dialog_content = "ジャキーニさん、時間切れなのでは！？",
  ui_story_5051_50511601_97_dialog_content = "まだです。この日の終わりまでは、まだたっぷり時間があるんです…\nそんなはずはありません。",
  ui_story_5051_50511601_98_dialog_content = "まさか僕たち本当に「記憶の鏡晶」と現実世界の隙間に落ちちゃうの？",
  ui_story_5051_50511601_99_dialog_content = "ジャキーニさん、何をモタモタしているのです？",
  ui_story_5051_50511601_100_dialog_content = "早く全員連れ出してください！",
  ui_story_5051_50511601_101_dialog_content = "みなさん、私の近くに来てください！",
  ui_story_5051_50511601_102_dialog_content = "でも、お父様がまだ…",
  ui_story_5051_50511601_103_dialog_content = "あんな見せかけの偽君子など、ここにいる方がお似合いです。\n放っておきましょう。急ぎますよ！",
  ui_story_5051_50511601_104_dialog_content = "たとえ極悪非道な悪人でも、放っておけないよ…",
  ui_story_5051_50511601_105_dialog_content = "ソルラドを呼ぶ",
  ui_story_5051_50511601_106_dialog_content = "ソルラドさん！こっちです！！",
  ui_story_5051_50511601_107_dialog_content = "お父様！",
  ui_story_5051_50511601_108_dialog_content = "城主様！",
  ui_story_5051_50511601_109_dialog_content = "どうして反応がないんだろう…",
  ui_story_5051_50511601_110_dialog_content = "感知を使う",
  ui_story_5051_50511601_111_dialog_content = "クッ…",
  ui_story_5051_50511601_112_dialog_content = "「記憶の鏡晶」の中では、やっぱり感知が使えない！",
  ui_story_5051_50511601_113_dialog_content = "あ…",
  ui_story_5051_50511601_114_dialog_content = "ミヤ、どうしたの？",
  ui_story_5051_50511601_115_dialog_content = "私たちの後ろにあった空間が…ゆっくり崩れて、消えたの！",
  ui_story_5051_50511601_116_dialog_content = "PlayerName、急いでください！",
  ui_story_5051_50511601_117_dialog_content = "皆付いてきて！さっきソルラドさんがいた方に向かうんだ！",
  ui_story_5051_50511601_118_dialog_content = "ジャキーニ、もし最後の最後までソルラドさんを見つけられなかったら…",
  ui_story_5051_50511601_119_dialog_content = "その時は僕たちだけを連れ出して！",
  ui_story_5051_50511601_120_dialog_content = "…わかりました！",
  ui_story_5051_50511601_121_dialog_content = "チッ。",
  ui_story_5051_50511601_122_dialog_content = "<color=#e8d9bb>シュッ――！</color>",
  ui_story_5051_50511601_123_dialog_content = "今誰か走りすぎて行かなかったかしら？",
  ui_story_5051_50511601_124_dialog_content = "この状況で、そんなに速く走れる人いるかな？",
  ui_story_5051_50511601_125_dialog_content = "<anim type=Shake><size=30>ダニエル…ヴェロニカ…カレン…</size></anim>",
  ui_story_5051_50511601_126_dialog_content = "あら？誰かが私の名前を呼んだような？",
  ui_story_5051_50511601_127_dialog_content = "声が小さすぎて、どこから聞こえたのか分からないね。",
  ui_story_5051_50511601_128_dialog_content = "<anim type=Shake>ここに、いたの？</anim>",
  ui_story_5051_50511601_129_dialog_content = "えっ…",
  ui_story_5051_50511601_130_dialog_content = "危ない！！",
  ui_story_5051_50511601_131_dialog_content = "お父様！",
  ui_story_5051_50511601_132_dialog_content = "皆気を付けるのだ。招かれざる客がおるぞ！",
  ui_story_5051_50511601_133_dialog_content = "重い攻撃だ…この状況で、いったい誰が僕たちに攻撃を？",
  ui_story_5051_50511601_134_dialog_content = "僕たちはもう…「記憶の鏡晶」と現実世界の間の隙間に落ちてしまったのですか…",
  ui_story_5051_50511601_135_dialog_content = "いやだ！そんなの駄目です！",
  ui_story_5051_50511601_136_dialog_content = "<anim type=Shake>ここに、いたの？</anim>",
  ui_story_5051_50511601_137_dialog_content = "ああああ！怪物です！",
  ui_story_5051_50511601_138_dialog_content = "PlayerName、今方向が分かるのはお主だけだ。",
  ui_story_5051_50511601_139_dialog_content = "指揮を任せる！",
  ui_story_5051_50511602_1_dialog_content = "ふぅ…ふぅ…",
  ui_story_5051_50511602_2_dialog_content = "ミヤ、少し休め！",
  ui_story_5051_50511602_3_dialog_content = "でも…ダメです。お父様の力に…みんなの力になりたいんです…",
  ui_story_5051_50511602_4_dialog_content = "ここに、いたの？",
  ui_story_5051_50511602_5_dialog_content = "水晶玉よ、お願いします！",
  ui_story_5051_50511602_6_dialog_content = "ああ、勘弁してください…この怪物、どうしてこうしぶとく攻撃してくるんです？",
  ui_story_5051_50511602_7_dialog_content = "ジャキーニ、「記憶の鏡晶」の中にどうしてこんな怪物が？",
  ui_story_5051_50511602_8_dialog_content = "わ、私にもわかりませんよ。",
  ui_story_5051_50511602_9_dialog_content = "この怪物、本当に当時の白夜城で出現したヤツではないんですか？",
  ui_story_5051_50511602_10_dialog_content = "…",
  ui_story_5051_50511602_11_dialog_content = "「白夜！庇護を！」",
  ui_story_5051_50511602_12_dialog_content = "当時の白夜城には、この怪物は現れていない。",
  ui_story_5051_50511602_13_dialog_content = "だが、気を落とすことはない！",
  ui_story_5051_50511602_14_dialog_content = "先程に比べれば、相手の力は明らかに弱っている。攻撃間隔も長くなるばかりだ。",
  ui_story_5051_50511602_15_dialog_content = "ジャキーニ！次の攻撃後の隙を狙い、我々を連れ出すのだ！",
  ui_story_5051_50511602_16_dialog_content = "わかりました、城主様！",
  ui_story_5051_50511602_17_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5051_50511602_18_dialog_content = "どうして急に静まりかえったんでしょう？",
  ui_story_5051_50511602_19_dialog_content = "シーッ、皆には聞こえる？",
  ui_story_5051_50511602_20_dialog_content = "<anim type=Shake><size=30>ダニエル…ヴェロニカ…カレン…</size></anim>",
  ui_story_5051_50511602_21_dialog_content = "あの怪物が…お父様と私たちの名前を？",
  ui_story_5051_50511602_22_dialog_content = "<anim type=Shake>ダニエル、ヴェロニカ、カレン</anim>",
  ui_story_5051_50511602_23_dialog_content = "この声は…",
  ui_story_5051_50511602_24_dialog_content = "<anim type=Shake>それに…カレブ</anim>",
  ui_story_5051_50511602_25_dialog_content = "<color=#FFB400>姉さん</color>！？",
  ui_story_5051_50511602_26_dialog_content = "そんなはずはない！",
  ui_story_5051_50511602_27_dialog_content = "ね、姉さん？姉さんなのですか？",
  ui_story_5051_50511602_28_dialog_content = "違う…そんなはずはない！違う！どうしてこんなことに！\n姉さんがここにいるはずがない！",
  ui_story_5051_50511602_29_dialog_content = "まさか…",
  ui_story_5051_50511602_30_dialog_content = "…",
  ui_story_5051_50511602_31_dialog_content = "どうして急にとまったんだろう？",
  ui_story_5051_50511602_32_dialog_content = "<anim type=Shake>ダメよ！</anim>",
  ui_story_5051_50511602_33_dialog_content = "<anim type=Shake>こんなことしてはいけないわ！</anim>",
  ui_story_5051_50511602_34_dialog_content = "<anim type=Shake>なぜ、いけないの？</anim>",
  ui_story_5051_50511602_35_dialog_content = "<anim type=Shake>彼らこそ苦しみの源</anim>",
  ui_story_5051_50511602_36_dialog_content = "<anim type=Shake>わたくしが理想を実現する邪魔をしたわ！</anim>",
  ui_story_5051_50511602_37_dialog_content = "<anim type=Shake>いいえ、彼らはわたくしが最も気に掛けている家族よ！</anim>",
  ui_story_5051_50511602_38_dialog_content = "<anim type=Shake>彼らさえいなければ、わたくしは外に出て行ける！</anim>",
  ui_story_5051_50511602_39_dialog_content = "<anim type=Shake>何を迷っているの？彼らはもう持たないわ</anim>",
  ui_story_5051_50511602_40_dialog_content = "<anim type=Shake>うるさい…うるさいわね！</anim>",
  ui_story_5051_50511602_41_dialog_content = "<anim type=Shake>早く出て行きなさい！</anim>",
  ui_story_5051_50511602_42_dialog_content = "独り言を言ってる？",
  ui_story_5051_50511602_X43_dialog_content = "ヘンですね…まるで自分とケンカしてるみたいです。",
  ui_story_5051_50511602_44_dialog_content = "姉さん…本当に、姉さんなのですか？",
  ui_story_5051_50511602_45_dialog_content = "お母さん…？",
  ui_story_5051_50511602_46_dialog_content = "ヨシュアの声を真似ているのか？",
  ui_story_5051_50511602_47_dialog_content = "許さぬ！",
  ui_story_5051_50511602_48_dialog_content = "<anim type=Shake>ソル…</anim>",
  ui_story_5051_50511602_49_dialog_content = "「すべての星よ！揺れ動け――！！」",
  ui_story_5051_50511602_50_dialog_content = "<anim type=Shake>うう…</anim>",
  ui_story_5051_50511602_51_dialog_content = "<anim type=Shake><size=45>あなたが…憎い…！</size></anim>",
  ui_story_5051_50511602_52_dialog_content = "なに？",
  ui_story_5051_50511602_53_dialog_content = "城主様の攻撃が効いたみたいです！",
  ui_story_5051_50511602_54_dialog_content = "なんだか苦しそうだ。でも、身体の痛みで苦しいわけじゃなさそうだよ？",
  ui_story_5051_50511602_55_dialog_content = "姉さんであるはずがない。姉さんじゃない…もし姉さんなら…",
  ui_story_5051_50511602_56_dialog_content = "ジャキーニさん、早く僕たちを連れ出してください！早く！",
  ui_story_5051_50511602_57_dialog_content = "<color=#e8d9bb>ボーン！</color>",
  ui_story_5051_50511602_58_dialog_content = "今のって時計の音？",
  ui_story_5051_50511602_59_dialog_content = "たたたた、大変です…12時の鐘が鳴ってしまいました！",
  ui_story_5051_50511602_60_dialog_content = "私たち、ここに閉じ込められるの？",
  ui_story_5051_50511602_61_dialog_content = "なぜです…ようやく見つけたのに…",
  ui_story_5051_50511602_62_dialog_content = "あと少しだったのに…",
  ui_story_5051_50511602_63_dialog_content = "なぜなのです！？",
  ui_story_5051_50511602_64_dialog_content = "あれ？カレブさんが手に持っているのは…",
  ui_story_5051_50511602_65_dialog_content = "この世界の「記憶の鏡晶」じゃありません？",
  ui_story_5051_50511602_66_dialog_content = "「記憶の鏡晶」の中の「記憶の鏡晶」？",
  ui_story_5051_50511602_67_dialog_content = "ハハ…見つけたところで、もう何にもなりません。",
  ui_story_5051_50511602_68_dialog_content = "<color=#e8d9bb>ボーン！</color>",
  ui_story_5051_50511602_69_dialog_content = "12時の鐘の音がもうすぐ終わっちゃう！",
  ui_story_5051_50511602_70_dialog_content = "カレブ、なぜ「記憶の鏡晶」の世界でそれを探していた？",
  ui_story_5051_50511602_71_dialog_content = "もう何の意味もありません…",
  ui_story_5051_50511602_72_dialog_content = "いいえ、もしかしたら助かるかもしれませんよ！！",
  ui_story_5051_50511602_73_dialog_content = "カレブさん、「記憶の鏡晶」を渡してください！",
  ui_story_5051_50511602_74_dialog_content = "どうぞ。",
  ui_story_5051_50511602_75_dialog_content = "「ママ」…",
  ui_story_5051_50511602_76_dialog_content = "まさかあの時、こうなることがわかってたんですか？",
  ui_story_5051_50511602_77_dialog_content = "人は皆占いで未来を知りたがるわ。",
  ui_story_5051_50511602_78_dialog_content = "でも、私は気づいたの。皆自分たちの「忘れる」速度を低く見すぎだって。",
  ui_story_5051_50511602_79_dialog_content = "だから、ある意味未来よりもさらに「予知」が難しいのは、<color=#FFB400>過去</color>なのよ。",
  ui_story_5051_50511602_80_dialog_content = "それが「記憶の鏡晶」を作った理由よ。",
  ui_story_5051_50511602_81_dialog_content = "最初はこれこそ最も安全な過去を振り返る方法だと思ってたわ。",
  ui_story_5051_50511602_82_dialog_content = "でも、あなたに会ったことで\n「記憶の鏡晶」にも予想外のことが起きる可能性があるってことに気づいた。",
  ui_story_5051_50511602_83_dialog_content = "幸い「記憶の鏡晶」の世界には緊急危険回避装置があるの。",
  ui_story_5051_50511602_84_dialog_content = "…「記憶の鏡晶」の中の「記憶の鏡晶」よ。",
  ui_story_5051_50511602_85_dialog_content = "そして、唯一占いの本に書かなかったこと。",
  ui_story_5051_50511602_86_dialog_content = "今後永遠にこの知識を使うことがないように願ってるわ。",
  ui_story_5051_50511602_87_dialog_content = "私、絶対にママをがっかりさせません！",
  ui_story_5051_50511602_88_dialog_content = "リタロ、リタロ、リタロ！",
  ui_story_5051_50511602_89_dialog_content = "アド・プラエセンス！",
  ui_story_5051_50511602_90_dialog_content = "時間よ、起点へ戻り、私たちを現実世界に戻してください！",
  ui_story_5051_50511602_91_dialog_content = "<size=45>アブラカダブラ！</size>",
  ui_story_5051_50511602_92_dialog_content = "ううっ！",
  ui_story_5051_50511602_93_dialog_content = "まただ…この空間が回転するような感覚…",
  ui_story_5051_50511602_94_dialog_content = "みなさん、お互いにしっかり手を握ってください！放しちゃいけませんよ！",
  ui_story_5051_50511602_95_dialog_content = "ミヤ、PlayerName、早く余の元へ！",
  ui_story_5051_50511602_96_dialog_content = "うわあ…どうしましょう？カレブさんが動きません！",
  ui_story_5051_50511602_97_dialog_content = "姉さん、ごめんなさい…もうそばにいられません。",
  ui_story_5051_50511602_98_dialog_content = "ダメだよ…誰一人置いてはいけない！",
  ui_story_5051_50511602_99_dialog_content = "PlayerName！？",
  ui_story_5051_50511602_100_dialog_content = "カレブさん！",
  ui_story_5051_50511602_101_dialog_content = "僕の手をつかんで！",
  ui_story_5051_50511602_102_dialog_content = "えっ！？",
  ui_story_5051_50511602_103_dialog_content = "PlayerName、それ以上乗り出したら、お父様もつかんでいられなくなるわ！",
  ui_story_5051_50511602_104_dialog_content = "あきらめちゃダメだ！",
  ui_story_5051_50511602_105_dialog_content = "PlayerName！！！",
  ui_story_5051_50511602_106_dialog_content = "つかまえた！カレブさんをつかまえたよ！",
  ui_story_5051_50511602_107_dialog_content = "…PlayerName？",
  ui_story_5051_50511602_108_dialog_content = "<color=#e8d9bb>ガチャン！</color>",
  ui_story_5051_50511602_109_dialog_content = "（あら？グラスが割れた音でしょうか？）",
  ui_story_5051_50511602_110_dialog_content = "（部屋の中にグラスは確か1つ…）",
  ui_story_5051_50511602_111_dialog_content = "（銘酒をお飲みになっても、\nカレブ様は気を落ち着かせることができなかったのでしょうか？）",
  ui_story_5051_50511602_112_dialog_content = "おや？「Ms.ロト」、今大きい音がしたようだな。",
  ui_story_5051_50511602_113_dialog_content = "どちらの「賓客」かな？城主の部屋で粗相なさるとは。",
  ui_story_5051_50511602_114_dialog_content = "それとも…どこぞの「賓客」が城主の怒りを買い、物を投げつけられたのかな？",
  ui_story_5051_50511602_115_dialog_content = "公爵、素晴らしい想像力をお持ちで、尊敬いたします。",
  ui_story_5051_50511602_116_dialog_content = "ただ、城主様がお客様と何を話し、\n何をなさるかは私どもがあれこれ詮索してよいことではありません。",
  ui_story_5051_50511602_117_dialog_content = "フン、お前はもうナイトガーディアンの隊長ではないだろう？",
  ui_story_5051_50511602_118_dialog_content = "それでも城主様にお仕えする限り、私は決して責務を怠りません。",
  ui_story_5051_50511602_119_dialog_content = "仕えるだと？一時的に宴の手伝いに来ただけだろうが。",
  ui_story_5051_50511602_120_dialog_content = "そんなに人に仕えるのが好きなら、\n愚息の誕生日の宴でも「Ms.ロト」に手伝いをお願いできるのかな？",
  ui_story_5051_50511602_121_dialog_content = "公爵、さきほどはご説明が十分でなかったようですね。",
  ui_story_5051_50511602_122_dialog_content = "私は今城主様に仕える身でございます。",
  ui_story_5051_50511602_123_dialog_content = "公爵が何をおっしゃろうとも、今晩ご子息にお会いする時間はございません。",
  ui_story_5051_50511602_124_dialog_content = "ハハハ、「Ms.ロト」。これまで私はそんな要求をしたことはないぞ。",
  ui_story_5051_50511602_125_dialog_content = "私はただ夜も更けたことだし、城主様に挨拶をしてから失礼しようと思っただけだ。",
  ui_story_5051_50511602_126_dialog_content = "小人の考えで君子の考えをはかるとは…",
  ui_story_5051_50511602_127_dialog_content = "城主のそば近くに仕える者とは思えないな。",
  ui_story_5051_50511602_128_dialog_content = "あら、そうでございますね。\n城主様に仕える者がめったに気を抜くものではありませんね。",
  ui_story_5051_50511602_129_dialog_content = "<color=#e8d9bb>ヒュ――</color>",
  ui_story_5051_50511602_130_dialog_content = "え？",
  ui_story_5051_50511602_131_dialog_content = "風が…",
  ui_story_5051_50511602_132_dialog_content = "出て来たようですね。",
  ui_story_5051_50511602_133_dialog_content = "<color=#e8d9bb>同じ時間、カレブ邸では</color>",
  ui_story_5051_50511602_134_dialog_content = "<color=#e8d9bb>ヒュ――</color>",
  ui_story_5051_50511602_135_dialog_content = "<color=#e8d9bb>ゴロゴロゴロ！</color>",
  ui_story_5051_50511602_136_dialog_content = "<color=#e8d9bb>ゴロゴロゴロ！</color>",
  ui_story_5051_50511602_137_dialog_content = "…",
  ui_story_5051_50511602_138_dialog_content = "…",
  ui_story_5051_50511602_139_dialog_content = "……",
  ui_story_5051_50511602_140_dialog_content = "<color=#e8d9bb>ゴロゴロゴロ！</color>",
  ui_story_5051_50511602_141_dialog_content = "<color=#e8d9bb>ゴロゴロゴロ…！</color>",
  ui_story_5051_50511602_142_dialog_content = "<color=#e8d9bb>ドーン！</color>",
  ui_story_5051_50511602_143_dialog_content = "つづく…"
}
return config
